/** One picker for single photographs and batches (never the known-hole path).
 * The parent owns course count. Never fetch or assume a count.
 * Every known hole is always selectable and drawn the same; there is no
 * used-hole treatment (BRIEF_HOLE_TAG_BATCH_V3). dimOthers is the batch
 * tagged-review state: the shot's own hole stays selected, the rest dim.
 */
import { Button } from '@/components/ui/button';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import { holeNumbers, selectableHole } from '@/lib/courseMedia/holePickerRules';

interface HolePhotoPickerProps {
  holeCount: number;
  /** Preserve sparse known-hole numbers and order from the analysis RPC. */
  knownHoleNumbers?: readonly number[];
  selectedHole: number | null;
  /** Disables every hole (the batch once nothing is left to tag). */
  disabled?: boolean;
  /** Dims every non-selected hole to 0.4 while the selected one stays solid. */
  dimOthers?: boolean;
  onSelect: (hole: number) => void;
}

export function HolePhotoPicker({ holeCount, knownHoleNumbers, selectedHole, disabled = false, dimOthers = false, onSelect }: HolePhotoPickerProps) {
  const numbers = knownHoleNumbers?.length === holeCount ? knownHoleNumbers : holeNumbers(holeCount);
  return (
    <div role="group" aria-label="Hole" className="grid grid-cols-6 gap-[6px]">
      {numbers.map(hole => {
        const available = knownHoleNumbers ? true : selectableHole(hole, holeCount);
        const selected = available && hole === selectedHole;
        return (
          <Button
            key={hole}
            variant="ghost"
            aria-label={`Hole ${hole}`}
            aria-pressed={selected}
            data-state={!available ? 'closed' : 'open'}
            disabled={!available || disabled}
            onClick={() => onSelect(hole)}
            className="aspect-square h-auto min-w-0 p-0 rounded-[9px] text-sm font-extrabold tabular-nums"
            style={{
              border: `1px ${available ? 'solid' : 'dashed'} ${selected ? A.INK : `color-mix(in srgb, ${A.INK} 12%, transparent)`}`,
              background: selected ? A.INK : 'transparent',
              color: selected ? A.CANVAS : A.BODY,
              opacity: !available ? 0.18 : dimOthers && !selected ? 0.4 : 1,
            }}
          >{hole}</Button>
        );
      })}
    </div>
  );
}

import { Button } from '@/components/ui/button';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import type { FeedPost } from '@/components/media-system/types/media';
import { canTagHolePhoto, holeSourceUrl } from '@/lib/courseMedia/holePhotoData';

export function HolePhotoTagButton({ post, memberId, holeCount, taggedUrls, taggedHoles, onTag }: {
  post: FeedPost; memberId: string | undefined; holeCount: number | null;
  taggedUrls: ReadonlySet<string>; taggedHoles?: ReadonlyMap<string, number>; onTag: (post: FeedPost) => void;
}) {
  const assigned = taggedHoles?.get(holeSourceUrl(post.mediaItems[0]));
  if (assigned != null) return <span className="absolute right-[5px] bottom-[5px] z-10 rounded-full px-2 py-[3px] text-[9.5px] font-extrabold" style={{ background: A.INK, color: A.CANVAS }}>Hole {assigned}</span>;
  if (!canTagHolePhoto(post, memberId, holeCount, taggedUrls)) return null;
  return <Button variant="ghost" size="sm" aria-label={post.mediaItems[0]?.type === 'video' ? 'Tag video' : 'Tag photograph'} className="absolute right-[5px] bottom-[5px] z-10 h-auto min-h-0 rounded-full px-2 py-[3px] text-[9.5px] font-extrabold uppercase tracking-[0.06em]"
    style={{ background: A.INK, color: A.CANVAS }}
    onClick={event => { event.stopPropagation(); onTag(post); }}>Tag a hole</Button>;
}

