const NO_FACES: FacesMap = new Map();

/** V3 §2 caption credit: 14px face + 5px + full name (filled from the shared faces). */
function Credit({ id, name, photo, day, faces }: { id: string | null; name: string | null; photo: string | null; day?: string | null; faces: FacesMap }) {
  const f = id ? faces.get(id) : undefined;
  const full = name || f?.displayName || f?.username || null;
  if (!full) return null;
  return (
    <span data-photo-credit="" style={{ display: 'flex', alignItems: 'center', gap: 5, marginTop: 3, fontSize: 10, lineHeight: '14px', color: 'rgba(255,255,255,.85)', whiteSpace: 'nowrap', overflow: 'hidden' }}>
      <MemberFace face={{ userId: id ?? full, photo: photo || f?.photoUrl || null, name: full }} size={14} />
      <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}>{day ? `${full} \u00B7 ${day}` : full}</span>
    </span>
  );
}

export function PlayedTile({ group, course, tile, faces = NO_FACES, onNavigate, inSheet = false, topGap = TILE_TOP, beforeReview, viewerId = null }: {
  group: CourseGroup; course: PlayedCourse; tile: ReturnType<typeof usePlayedTile>; faces?: FacesMap;
  /** Sheet host: closes itself, then navigates. Defaults to a plain navigate. */
  onNavigate?: (to: string) => void; inSheet?: boolean; topGap?: number;
  /** Sheet host: closes itself before the review sheet opens (the review sheet sits below BottomSheet's layer). */
  beforeReview?: () => void;
  /** The signed-in viewer: named first as "You" in the faces line. */
  viewerId?: string | null;
}) {
  const openLatestReview = useOpenLatestReview();
  const navigate = useNavigate();
  const go = (to: string) => (onNavigate ? onNavigate(to) : navigate(to));
  const open = () => go(`/courses/${course.id}`);
  const openLately = () => go(courseLatelyHref(course.id));
  const { short } = shareCourseName(course.name);
  const title = shortCoursePart(course.name);
  const review = group.rows.length === 0 ? group.reviews[0] ?? null : null;
  const reviewer = review ? group.faces.find((f) => f.userId === review.user_id) ?? null : null;
  const openReview = () => {
    if (!review) return;
    beforeReview?.();
    openLatestReview({
      reviewId: review.id, courseId: course.id, courseName: course.name, courseImage: course.imageUrl,
      rating: Number(review.rating ?? 0), quote: review.review ?? '', at: review.created_at,
      userId: review.user_id, reviewerName: reviewer?.name ?? '', reviewerUsername: null, reviewerAvatar: reviewer?.photo ?? null,
      mediaUrl: null, mediaType: null, posterUrl: null,
      courseCountry: course.country, courseRegion: course.region, courseSubCountry: course.subCountry,
      breakdown: { design: null, conditions: null, clubhouse: null, facilities: null },
    });
  };
  const latest = roundsLately(group.rows);
  const photos = interleaveTilePhotos<TileHolePhoto, TileCoursePhoto>(tile.holes, tile.photos, tile.hardestHole);
  const golfers = orderGolfers(group.rows, group.faces, faces, viewerId);
  const line = golfersLine(golfers.names, golfers.viewer, golfers.total, group.rows.length > 0);
  const capBase: React.CSSProperties = { transform: 'translateZ(0)', position: 'absolute', left: 10, right: 10, bottom: 9 };
  const ell: React.CSSProperties = { display: 'block', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' };

  return (
    <div data-played-tile={course.id} style={{ margin: `${topGap}px 16px 0` }}>
      <div data-tile-head="" style={{ display: 'block', width: '100%' }}>
        <b data-tile-title="" style={{ display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 2, overflow: 'hidden', overflowWrap: 'anywhere', fontSize: 18, lineHeight: `${TILE_NAME_LINE}px`, fontWeight: 800, color: A.INK }}>{title}</b>
      </div>
      <div className="scrollbar-hide" data-tile-row="" style={{ display: 'flex', gap: TILE_ROW_GAP, overflowX: 'auto', scrollbarWidth: 'none', margin: `${TILE_ROW_TOP}px -16px 0`, padding: '0 16px' }}>
        {group.rows.length > 0 ? (
        <button type="button" data-best-lately="" onClick={openLately}
          style={{ flex: 'none', width: BEST_CARD_W, height: TILE_ROW_H, boxSizing: 'border-box', borderRadius: TILE_RADIUS, background: BEST_BG, padding: TILE_CARD_PAD, border: 0, display: 'flex', flexDirection: 'column', gap: 9, textAlign: 'left', cursor: 'pointer', color: A.INK }}>
          <span data-best-kicker="" style={{ fontSize: 8.5, fontWeight: 800, letterSpacing: '.14em', color: A.INK, lineHeight: '10px' }}>ROUNDS LATELY</span>
          {latest.map((r) => {
            const par = r.gross_score != null ? toParText(r.gross_score, r.course_par) : null;
            const under = par != null && par.startsWith('\u2212');
            return (
              <span key={r.whs_score_id} data-best-entry="" style={{ display: 'block', minWidth: 0 }}>
                <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <MemberFace face={{ userId: r.user_id, photo: r.profile_photo_url, name: r.display_name }} size={20} />
                  <span style={{ display: 'flex', alignItems: 'baseline', gap: 4 }}>
                    {r.gross_score != null ? <b style={{ fontSize: 18, lineHeight: '20px', fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{r.gross_score}</b> : null}
                    {par != null ? <span data-to-par="" style={{ fontSize: 10.5, fontWeight: 700, fontVariantNumeric: 'tabular-nums', color: under ? UNDER_RED : A.DIM }}>{par}</span> : null}
                  </span>
                </span>
                <span style={{ ...ell, marginTop: 5, fontSize: 11.5, lineHeight: '14px', fontWeight: 600 }}>
                  <InlineProMemberName userId={r.user_id}>{r.display_name ?? ''}</InlineProMemberName>
                </span>
                <span style={{ ...ell, marginTop: 1, fontSize: 9.5, lineHeight: '12px', color: A.DIM }}>
                  {dayLabel(r.play_date)}
                </span>
              </span>
            );
          })}
          <span style={{ marginTop: 'auto', fontSize: 10.5, lineHeight: '13px', color: A.MUTE }}>
            {group.rows.length === 1 ? '1 round lately \u203A' : `${fmtCount(group.rows.length)} rounds lately \u203A`}
          </span>
        </button>
        ) : null}
        {review ? (
          <button type="button" data-latest-review="" onClick={openReview}
            style={{ flex: 'none', width: BEST_CARD_W, height: TILE_ROW_H, boxSizing: 'border-box', borderRadius: TILE_RADIUS, background: BEST_BG, padding: TILE_CARD_PAD, border: 0, display: 'flex', flexDirection: 'column', gap: 9, textAlign: 'left', cursor: 'pointer', color: A.INK, overflow: 'hidden' }}>
            <span style={{ fontSize: 8.5, fontWeight: 800, letterSpacing: '.14em', color: A.INK, lineHeight: '10px' }}>LATEST REVIEW</span>
            <span style={{ display: 'block', minWidth: 0 }}>
              <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <MemberFace face={reviewer ?? { userId: review.user_id ?? '', photo: null, name: null }} size={20} />
                {review.rating != null ? <b data-review-rating="" style={{ fontSize: 18, lineHeight: '20px', fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{formatRatingValue(Number(review.rating))}</b> : null}
              </span>
              <span style={{ ...ell, marginTop: 5, fontSize: 11.5, lineHeight: '14px', fontWeight: 600 }}>
                {review.user_id ? <InlineProMemberName userId={review.user_id}>{reviewer?.name ?? ''}</InlineProMemberName> : null}
              </span>
              <span style={{ ...ell, marginTop: 1, fontSize: 9.5, lineHeight: '12px', color: A.DIM }}>{dayLabel(review.created_at)}</span>
            </span>
            <span data-review-text="" style={{ display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 3, overflow: 'hidden', fontSize: 10.5, lineHeight: 1.35, color: 'rgba(248,250,252,.78)' }}>{review.review}</span>
            <span style={{ marginTop: 'auto', fontSize: 10.5, lineHeight: '13px', color: A.MUTE }}>
              {group.reviews.length === 1 ? '1 review lately \u203A' : `${fmtCount(group.reviews.length)} reviews lately \u203A`}
            </span>
          </button>
        ) : null}
        {!tile.ready ? (
          [0, 1].map((i) => <span key={i} data-tile-pending="" style={{ flex: 'none', display: 'block', width: PHOTO_TILE_W, height: TILE_ROW_H }}><Bar style={{ width: '100%', height: '100%', borderRadius: TILE_RADIUS }} /></span>)
        ) : photos.length === 0 ? (
          <button type="button" data-tile-add="" onClick={open}
            style={{ flex: 'none', width: ADD_TILE_W, height: TILE_ROW_H, boxSizing: 'border-box', borderRadius: TILE_RADIUS, background: ADD_TILE_BG, border: 0, padding: 16, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', cursor: 'pointer' }}>
            <span aria-hidden="true" style={{ width: 44, height: 44, borderRadius: '34%', background: ADD_PLUS_BG, color: A.AMBER, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 26, fontWeight: 600, lineHeight: 1 }}>+</span>
            <b data-tile-add-text="" style={{ marginTop: 12, fontSize: 13, fontWeight: 700, lineHeight: 1.3, color: A.AMBER, display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 2, overflow: 'hidden', overflowWrap: 'anywhere' }}>{`Add a photo or video of ${short}`}</b>
          </button>
        ) : photos.map((p, pi) => (
          <button key={p.key} type="button" data-tile-photo={p.kind} onClick={() => { openTilePhoto(photos, pi, course, tile.coursePosts ?? [], inSheet); }}
            style={{ flex: 'none', width: railTileWidth(p.width, p.height), height: TILE_ROW_H, borderRadius: TILE_RADIUS, overflow: 'hidden', position: 'relative', padding: 0, border: 0, cursor: 'pointer', textAlign: 'left', color: '#FFFFFF', backgroundColor: A.CANVAS, backgroundImage: `url("${p.imageUrl}")`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
            {p.video ? <span data-tile-video="" style={{ position: 'absolute', inset: 0 }}><HoleInlineVideo media={p.video} alt="" fit="cover" autoplayGroup="courses-played-tile" maxPlaying={2} active /></span> : null}
            <span style={{ transform: 'translateZ(0)', position: 'absolute', inset: 0, background: PLAYED_SCRIM }} />
            {p.kind === 'hole' ? (
              <>
                <span style={{ transform: 'translateZ(0)', position: 'absolute', top: 8, left: 10, fontSize: 28, fontWeight: 800, letterSpacing: '-.04em', lineHeight: 1 }}>{p.holeNo}</span>
                {tile.hardestHole === p.holeNo ? <span data-hardest="" style={{ transform: 'translateZ(0)', position: 'absolute', top: 10, right: 8, padding: '3px 6px', borderRadius: 6, background: 'rgba(10,10,12,.6)', color: A.AMBER, fontSize: 8, fontWeight: 800, letterSpacing: '.1em', lineHeight: '10px' }}>HARDEST</span> : null}
                <span style={capBase}>
                  <b style={{ ...ell, fontSize: 11.5, fontWeight: 700 }}>{[p.par != null ? `Par ${p.par}` : null, p.yards != null ? `${p.yards} yds` : null].filter(Boolean).join(' \u00B7 ')}</b>
                  <Credit id={p.memberId} name={p.memberName} photo={p.memberPhoto} faces={faces} />
                </span>
              </>
            ) : (
              <>
                <span style={{ ...GLASS, boxShadow: undefined, backdropFilter: 'blur(8px)', WebkitBackdropFilter: 'blur(8px)', transform: 'translateZ(0)', position: 'absolute', top: 10, left: 10, padding: '3px 7px', borderRadius: 6, fontSize: 8, fontWeight: 800, letterSpacing: '.12em', lineHeight: '10px', color: '#FFFFFF' }}>COURSE</span>
                <span style={capBase}>
                  <b style={{ ...ell, fontSize: 11.5, fontWeight: 700 }}>{p.caption || short}</b>
                  <Credit id={p.memberId} name={p.memberName} photo={p.memberPhoto} day={dayLabel(p.createdAt)} faces={faces} />
                </span>
              </>
            )}
          </button>
        ))}
      </div>
      <button type="button" data-tile-faces="" onClick={openLately} style={{ all: 'unset', display: 'flex', alignItems: 'center', gap: 8, marginTop: FACES_TOP, fontSize: 12, color: A.MUTE, cursor: 'pointer', maxWidth: '100%' }}>
        <FaceStack faces={group.faces.slice(0, 4)} size={FACE_SIZE} overlap={6} ring={A.CANVAS} />
        <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', minWidth: 0 }}>
          <b style={{ color: A.INK, fontWeight: 600 }}>{line.bold}</b>{line.rest}
        </span>
      </button>
      <button type="button" data-tile-explore="" onClick={open}
        style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '100%', height: BUTTON_H, marginTop: BUTTON_TOP, borderRadius: 14, background: BUTTON_BG, border: 0, fontSize: 13.5, fontWeight: 700, color: A.INK, cursor: 'pointer', overflow: 'hidden', whiteSpace: 'nowrap', textOverflow: 'ellipsis', padding: '0 12px' }}>
        {`Explore ${short} \u203A`}
      </button>
    </div>
  );
}

src/components/courses/browse/RegionRail:
/**
 * Region rails under the tile (BRIEF_WHATS_BEEN_PLAYED §4, signed-off
 * region-rails mock, revised by BRIEF_WHATS_BEEN_PLAYED_V3: home nation, one
 * rest-of-grouping rail, Abroad; no top-ups). Rail plans come from playedRings.buildRails. Since BRIEF_WHATS_BEEN_PLAYED_V2 rails hold every active
 * course outside the first tab, so a course may sit in a tab and a rail. Since
 * BRIEF_WHATS_BEEN_PLAYED_V4 §4 a card opens that course's tile in a sheet
 * (onOpen, owned by WhoPlayingSection) and never navigates itself; "See all ›" opens section 08 on the Played board scoped to the
 * nation, the way ByRegionSection's tiles write the country param.
 */
import { useSearchParams } from 'react-router-dom';
import type React from 'react';
import { HoleInlineVideo } from '@/components/course-media-tab/HoleInlineVideo';
import { useSupabaseSession } from '@/hooks/useSupabaseSession';
import { useNearViewport, useNewestCourseMedia } from './useNewestCourseMedia';
import { CourseImageFallback } from '@/components/explore-tab-new/courseled/CourseImageFallback';
import { useCourseMediaCounts } from '@/hooks/useCourseMediaCounts';
import { shortCoursePart } from '@/lib/courseMedia/memberShotPosts';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import { ALL_COURSES_ANCHOR } from './ByRegionSection';
import { fmtCount } from './format';
import { bestLately, railShowsSeeAll, type RailPlan } from './playedRings';
import type { PlayedCourse } from './usePlayedRounds';
import { GLASS, MemberFace, PLAYED_SCRIM, PlayedHead } from './playedParts';
import type { CourseGroup } from './WhoPlayingSection';
import { railTileWidth } from './railTileHeights';

export const RAIL_CARD_W = 156;
export const RAIL_CARD_H = 216;
export const RAILS_TOP = 30;
export const RAIL_GAP_Y = 30;

const LAYER: React.CSSProperties = { transform: 'translateZ(0)' };
const glassTop: React.CSSProperties = { ...GLASS, ...LAYER, position: 'absolute', top: 8, right: 8, padding: '3px 7px', borderRadius: 7, lineHeight: '12px' };
const cardStyle: React.CSSProperties = { flex: 'none', width: RAIL_CARD_W, height: RAIL_CARD_H, borderRadius: 16, overflow: 'hidden', position: 'relative', padding: 0, border: 0, cursor: 'pointer', textAlign: 'left', color: '#FFFFFF', background: 'none' };
const bottom: React.CSSProperties = { ...LAYER, position: 'absolute', left: 10, right: 10, bottom: 10 };
const nameStyle: React.CSSProperties = { display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 2, overflow: 'hidden', fontSize: 14, fontWeight: 800, lineHeight: 1.15 };
const countyStyle: React.CSSProperties = { display: 'block', marginTop: 2, fontSize: 10.5, color: 'rgba(255,255,255,.75)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' };

function PlayedCard({ group, course, onOpen, autoplayGroup }: { group: CourseGroup; course: PlayedCourse; onOpen: () => void; autoplayGroup: string }) {
  const best = bestLately(group.rows, 1)[0] ?? null;
  const { user } = useSupabaseSession();
  const [ref, near] = useNearViewport<HTMLButtonElement>();
  // §1: newest member media over the course image; the fallback stays drawn beneath while pending or absent.
  const media = useNewestCourseMedia(course.id, user?.id ?? null, near).data ?? null;
  return (
    <button ref={ref} type="button" data-rail-card="played" onClick={onOpen} style={{ ...cardStyle, width: media ? railTileWidth(media.width, media.height) : RAIL_CARD_W }}>
      <CourseImageFallback courseId={course.id} courseName={course.name} imageUrl={course.imageUrl} style={{ position: 'absolute', inset: 0 }}>
        {media ? (
          <span data-rail-media={media.media_type} style={{ position: 'absolute', inset: 0 }}>
            {media.media_type === 'video'
              ? <HoleInlineVideo media={media} alt="" fit="cover" autoplayGroup={autoplayGroup} maxPlaying={2} active />
              : <img src={media.media_url} alt="" loading="lazy" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} onError={(e) => { e.currentTarget.hidden = true; }} />}
          </span>
        ) : null}
        <span style={{ ...LAYER, position: 'absolute', inset: 0, background: PLAYED_SCRIM }} />
        <span data-rail-count="" style={{ ...glassTop, fontSize: 10, fontWeight: 800, fontVariantNumeric: 'tabular-nums', color: '#FFFFFF' }}>{fmtCount(group.activity)}</span>
        <span style={bottom}>
          <b style={nameStyle}>{shortCoursePart(course.name)}</b>
          {course.region ? <span style={countyStyle}>{course.region}</span> : null}
          {best ? (
            <>
              <span data-best-golfer="" style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 7, fontSize: 11, fontWeight: 600, lineHeight: '16px', color: '#FFFFFF', whiteSpace: 'nowrap', overflow: 'hidden' }}>
                <MemberFace face={{ userId: best.user_id, photo: best.profile_photo_url, name: best.display_name }} size={16} />
                <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}>{best.display_name ?? ''}</span>
              </span>
              <span data-played-stat="" style={{ display: 'block', marginTop: 3, fontSize: 10.5, color: 'rgba(255,255,255,.85)', whiteSpace: 'nowrap' }}>
                Best round <b data-best-gross="" style={{ color: '#FFFFFF', fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>{best.gross_score}</b>
              </span>
            </>
          ) : group.rows.length === 0 ? <ActivityStat courseId={course.id} /> : null}
        </span>
      </CourseImageFallback>
    </button>
  );
}

/** §3 "{v} video(s) & {p} photo(s)"; either part drops at 0, both 0 → nothing. */
export function mediaLine(videos: number, photos: number): string | null {
  const v = videos > 0 ? `${fmtCount(videos)} ${videos === 1 ? 'video' : 'videos'}` : null;
  const p = photos > 0 ? `${fmtCount(photos)} ${photos === 1 ? 'photo' : 'photos'}` : null;
  return v && p ? `${v} & ${p}` : v ?? p;
}

/** Posts or reviews, no round: the course's media counts (get_course_media_counts). */
function ActivityStat({ courseId }: { courseId: string }) {
  const counts = useCourseMediaCounts(courseId);
  const text = mediaLine(counts.data?.videos ?? 0, counts.data?.photos ?? 0);
  return text ? <span data-activity-stat="" style={{ display: 'block', marginTop: 7, fontSize: 10.5, color: 'rgba(255,255,255,.85)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{text}</span> : null;
}

export function RegionRails({ rails, groups, courseMap, onOpen }: {
  rails: RailPlan[]; groups: CourseGroup[]; courseMap: Map<string, PlayedCourse> | undefined; onOpen: (courseId: string) => void;
}) {
  const [searchParams, setSearchParams] = useSearchParams();
  if (!rails.length || !courseMap) return null;
  const byGroup = new Map(groups.map((g) => [g.courseId, g]));
  const seeAll = (nation: string) => {
    const params = new URLSearchParams(searchParams);
    params.set('country', nation);
    params.delete('region');
    params.set('lens', 'played');
    setSearchParams(params, { replace: true });
    requestAnimationFrame(() => document.getElementById(ALL_COURSES_ANCHOR)?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
  };
  return (
    <div data-region-rails="" style={{ marginTop: RAILS_TOP, display: 'flex', flexDirection: 'column', gap: RAIL_GAP_Y }}>
      {rails.map((rail) => (
        <div key={rail.key} data-region-rail={rail.kind}>
          <PlayedHead kicker={rail.kicker} title={rail.title} right={railShowsSeeAll(rail) ? (
            <button type="button" data-rail-see-all="" onClick={() => seeAll(rail.nations[0])}
              style={{ flex: 'none', background: 'none', border: 0, padding: 0, fontSize: 12, fontWeight: 600, lineHeight: '25px', color: A.MUTE, cursor: 'pointer' }}>See all {'\u203A'}</button>
          ) : null} />
          <div className="scrollbar-hide" style={{ display: 'flex', gap: 8, overflowX: 'auto', scrollbarWidth: 'none', marginTop: 12, padding: '0 16px' }}>
            {rail.courseIds.map((id) => {
              const g = byGroup.get(id); const c = courseMap.get(id);
              return g && c ? <PlayedCard key={id} group={g} course={c} onOpen={() => onOpen(id)} autoplayGroup={`courses-region-${rail.key}`} /> : null;
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

src/components/courses/browse/latestHole:
/* H1 tile geometry; colours, shadows and local scrims live in global style tokens. */
.latest-hole-card { flex: none; position: relative; isolation: isolate; overflow: hidden; border-radius: 16px; padding: 0; border: none; text-align: left; cursor: pointer; color: var(--latest-hole-ink); }
/* The local media stack contains the shared player; its overlays never compete with video descendants. */
.latest-hole-media > div { z-index: 0; }
.latest-hole-media > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.latest-hole-scrim { position: absolute; inset: 0; z-index: 1; }
/* The bottom stack, bottom-anchored: course name, credit. */
.latest-hole-name { position: absolute; left: 16px; right: 16px; bottom: 15px; }
.latest-hole-figure { position: absolute; top: 14px; right: 16px; text-align: right; }
.latest-hole-number { font-size: 40px; font-weight: 700; letter-spacing: -0.05em; line-height: 1; font-variant-numeric: tabular-nums; color: var(--latest-hole-ink); text-shadow: var(--latest-hole-number-shadow); }
.latest-hole-label { margin-top: 6px; font-size: 8.5px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--latest-hole-label-ink); text-shadow: var(--latest-hole-label-shadow); }
.latest-hole-course { font-size: 17px; font-weight: 700; letter-spacing: -0.03em; line-height: 1.08; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.latest-hole-credit { margin-top: 5px; font-size: 11.5px; font-weight: 500; color: var(--latest-hole-credit); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.latest-hole-video { position: absolute; top: 16px; left: 16px; display: flex; align-items: center; gap: 5px; height: 24px; padding: 0 9px 0 7px; border-radius: 999px; color: var(--latest-hole-ink); font-size: 11px; font-weight: 700; font-variant-numeric: tabular-nums; }

src/components/courses/course-detail/Cat:
/**
 * BRIEF_ONE_CATEGORY_SCORE_BLOCK — the ONE category score block and the ONE
 * overall line. Mounted on the courses list card, the Course tab and the
 * Reviews tab. Same numbers, one treatment.
 *
 *   grid4   no bar; centred figure then label (pairs keeps its 8px bars)
 *   figure  16 / 700 / -0.02em, courseSubScoreTone(value)
 *   label   9 / 700 / 0.09em / uppercase / A.DIM, lineHeight 1, 4px beneath the figure
 *   columns four equal, 12px gap
 *
 * An absent category renders an EMPTY column — never a zero, never a dash.
 * Course list cards opt into split; their overall lead is supplied by the card
 * so headline tone stays separate from category tone. grid4/pairs stay independent.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { A, SANS, FIGS, courseSubScoreTone } from '@/features/courses/components/holes/analytical/tokens';
import { getRatingTierLabel } from '@/lib/ratingTier';

export interface CategoryScoreValues {
  design?: number | null;
  condition?: number | null;
  clubhouse?: number | null;
  facilities?: number | null;
}

const ORDER: { key: keyof CategoryScoreValues; label: string }[] = [
  { key: 'design', label: 'Design' },
  { key: 'condition', label: 'Condition' },
  { key: 'clubhouse', label: 'Clubhouse' },
  { key: 'facilities', label: 'Facilities' },
];

/** The only copy of the fill arithmetic. */
export const categoryFillPercent = (value: number) => Math.max(0, Math.min(100, (value / 10) * 100));

/**
 * BRIEF_REVIEWS_CATEGORY_PAIRS — the 'pairs' layout, used ONLY by the Reviews
 * tab (WhatTheyScored). Two columns, readable 13/700 INK labels, an 8px bar and
 * figure on one row.
 *
 * THE 0–10 SCALE IS DELIBERATE. Rescaling the bar to start at 5.0 was built,
 * measured and declined: at 0–10 the four bars differ only slightly and read as
 * near-identical — that is accepted. The bar gives weight and familiarity; the
 * figures carry the comparison. Changing the scale is a product decision, not a
 * bug fix. The fill arithmetic stays in categoryFillPercent.
 */
const CategoryScorePairs: React.FC<{ scores: CategoryScoreValues; marginTop: number }> = ({ scores, marginTop }) => (
  <div
    data-category-scores
    style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px 16px', marginTop, fontFamily: SANS }}
  >
    {ORDER.map(({ key, label }) => {
      const value = scores[key];
      if (value == null) return <div key={key} data-category={key} aria-hidden style={{ minWidth: 0 }} />;
      const tone = courseSubScoreTone(value);
      return (
        <div key={key} data-category={key} style={{ minWidth: 0 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: A.INK, marginBottom: 9 }}>{label}</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ flex: 1, height: 8, borderRadius: 4, background: A.TRACK, overflow: 'hidden' }}>
              <div
                data-category-score={value.toFixed(1)}
                style={{ height: '100%', width: `${categoryFillPercent(value)}%`, borderRadius: 4, background: tone }}
              />
            </div>
            <div data-category-figure style={{ ...FIGS, flex: '0 0 30px', textAlign: 'right', fontSize: 15, fontWeight: 700, color: tone }}>
              {value.toFixed(1)}
            </div>
          </div>
        </div>
      );
    })}
  </div>
);

export const CategoryScores: React.FC<{ scores: CategoryScoreValues; marginTop?: number; layout?: 'grid4' | 'pairs' | 'split' | 'strip'; lead?: React.ReactNode }> = ({ scores, marginTop = 0, layout = 'grid4', lead }) => {
  const hasScores = ORDER.some(({ key }) => scores[key] != null);
  const hasLead = lead != null && lead !== false;
  if (!hasScores && !(layout === 'split' && hasLead)) return null;
  /* BRIEF_COURSE_CARD_V3 §3: the course list card's breakdown — four centred
     columns, value over label, no lead. Tone stays with this one helper. */
  if (layout === 'strip') return (
    <div data-course-breakdown style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 4, marginTop }}>
      {ORDER.map(({ key, label }) => {
        const value = scores[key];
        if (value == null) return <div key={key} data-category={key} aria-hidden style={{ minWidth: 0 }} />;
        const tone = courseSubScoreTone(value);
        return (
          <div key={key} data-category={key} style={{ minWidth: 0, textAlign: 'center' }}>
            <div data-category-figure data-category-score={value.toFixed(1)} style={{ ...FIGS, fontSize: 13, fontWeight: 700, lineHeight: 1, color: tone }}>{value.toFixed(1)}</div>
            <div style={{ marginTop: 3, fontSize: 8, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase', color: A.DIM, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{label}</div>
          </div>
        );
      })}
    </div>
  );
  if (layout === 'split') return (
    <div
      data-category-scores
      style={{ display: 'flex', alignItems: 'center', gap: 14, marginTop, fontFamily: SANS }}
    >
      {hasLead ? (
        <div style={{ flex: '0 0 auto', ...(hasScores ? { paddingRight: 14, borderRight: `1px solid ${A.TRACK}` } : {}), textAlign: 'center' }}>
          {lead}
        </div>
      ) : null}
      {hasScores ? (
        <div style={{ flex: 1, minWidth: 0, display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', columnGap: 16, rowGap: 8 }}>
          {ORDER.map(({ key, label }) => {
            const value = scores[key];
            if (value == null) return <div key={key} data-category={key} aria-hidden style={{ minWidth: 0 }} />;
            const tone = courseSubScoreTone(value);
            return (
              <div key={key} data-category={key} style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', minWidth: 0 }}>
                <span style={{ fontSize: 11, color: A.MUTE, whiteSpace: 'nowrap' }}>{label}</span>
                <span data-category-figure data-category-score={value.toFixed(1)} style={{ ...FIGS, fontSize: 13, fontWeight: 700, color: tone }}>
                  {value.toFixed(1)}
                </span>
              </div>
            );
          })}
        </div>
      ) : null}
    </div>
  );
  if (layout === 'pairs') return <CategoryScorePairs scores={scores} marginTop={marginTop} />;
  return (
    <div
      data-category-scores
      style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 12, marginTop, fontFamily: SANS }}
    >
      {ORDER.map(({ key, label }) => {
        const value = scores[key];
        if (value == null) return <div key={key} data-category={key} aria-hidden style={{ minWidth: 0 }} />;
        const tone = courseSubScoreTone(value);
        return (
          <div key={key} data-category={key} style={{ minWidth: 0, textAlign: 'center' }}>
            <div
              data-category-figure
              data-category-score={value.toFixed(1)}
              style={{ ...FIGS, fontSize: 16, fontWeight: 700, letterSpacing: '-0.02em', lineHeight: 1, color: tone }}
            >
              {value.toFixed(1)}
            </div>
            <div
              style={{
                marginTop: 4, lineHeight: 1, fontSize: 9, fontWeight: 700, letterSpacing: '0.09em', textTransform: 'uppercase',
                color: A.DIM, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
              }}
            >
              {label}
            </div>
          </div>
        );
      })}
    </div>
  );
};

/** Below this the tier word is withheld — a verdict needs a sample. The score and its rating count still show. */
export const SETTLED_MIN_RATINGS = 5;

/**
 * §3.1 — the overall, 38px, with its tier word on one baseline: "7.9 overall".
 * The rating count no longer sits beside it — the count lives in the right-hand
 * slot of the Course tab's score row, where "Your rating" used to sit.
 */
export const OverallScoreLine: React.FC<{ score: number; ratingCount: number }> = ({ score, ratingCount }) => {
  const { t } = useTranslation('courses');
  const settled = ratingCount >= SETTLED_MIN_RATINGS;
  const tone = courseSubScoreTone(score);
  return (
    <div data-overall-score style={{ display: 'flex', alignItems: 'baseline', gap: 10, minWidth: 0, fontFamily: SANS }}>
      <span style={{ ...FIGS, flexShrink: 0, fontSize: 38, fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1, color: tone }}>
        {score.toFixed(1)}
      </span>
      {/* Always shown, at every rating count — a label, not a verdict. */}
      <span style={{ flexShrink: 0, fontSize: 9, fontWeight: 700, letterSpacing: '0.09em', textTransform: 'uppercase', color: A.DIM }}>
        {t('courseDetail.communityScore.overall')}
      </span>
      {settled ? (
        <span style={{ minWidth: 0, fontSize: 11.5, fontWeight: 600, lineHeight: 1.35, color: tone }}>
          {getRatingTierLabel(score)}
        </span>
      ) : null}
    </div>
  );
};

export default CategoryScores;

src/components/courses/course-detail/Cla:
/**
 * CLAIM SHEET REBUILD — presentation follows claim-sheet-signed-off.html
 * exactly; the claim LOGIC is unchanged (same memberships, same
 * request-course-claim body, same create URL, same states).
 *
 * Figures are for sourceCourseId and reuse the shared hooks so nothing is
 * fetched twice: useCourseStatsDetail (rounds), useCourseHoleAnalysis (hole
 * strip), useCourseReviewSample + reviewsCommunitySample (rating), and
 * useCourseMediaCounts (photos). useUnansweredReviewCount is the sheet's own
 * open-gated read. Every section drops out when its data is missing.
 *
 * The hole strip reuses ClubHowItPlays' pickHardestHole/holeBarHeights so the
 * club page and this sheet name the same hardest hole. Stroke index is never
 * mentioned in copy — that comparison was removed from the product.
 */
import React, { useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { fetchGolfClub } from '@/features/business/claimClub';
import {
  Loader2, Check, ArrowRight, X, MessageSquare, BarChart3, Eye, Calendar,
} from 'lucide-react';
import { toast } from '@/lib/toast';
import { BottomSheet } from '@/components/ui/BottomSheet';
import { supabase } from '@/integrations/supabase/client';
import { useSupabaseSession } from '@/hooks/useSupabaseSession';
import { useMyBusinesses, type BusinessMembership } from '@/hooks/useMyBusinesses';
import { useCourseStatsDetail } from '@/hooks/feed/useCourseStatsDetail';
import { useCourseHoleAnalysis } from '@/hooks/gam/useCourseHoleAnalysis';
import { useCourseReviewSample } from '@/hooks/useCourseReviewSample';
import { useCourseMediaCounts } from '@/hooks/useCourseMediaCounts';
import { useUnansweredReviewCount } from '@/hooks/useUnansweredReviewCount';
import { reviewsCommunitySample } from '@/lib/reviews/communitySample';
import { hasCommunityAverage } from '@/lib/reviews/sampleRules';
import { pickHardestHole, holeBarHeights } from '@/components/business/ClubHowItPlays';
import { ordinal } from '@/lib/text/numbers';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { AppLog } from '@/lib/logger';
import { useGuestSheetGate } from '@/features/guest/useGuestActionGate';

interface ClaimCourseSheetProps {
  open: boolean;
  onClose: () => void;
  clubId: string;
  sourceCourseId?: string;
}

/* Mock tokens (claim-sheet-signed-off.html). */
const SHEET = '#16161A';
const INKC = '#F8FAFC';
const ON_INK = '#0A0A0C';
const MUTE = 'rgba(248,250,252,0.62)';
const DIM = 'rgba(248,250,252,0.42)';
const TRACK = 'rgba(255,255,255,0.08)';
const LABEL: React.CSSProperties = {
  fontSize: 9.5, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: DIM,
};
const NUM: React.CSSProperties = { fontVariantNumeric: 'tabular-nums', fontFeatureSettings: '"zero" 0' };

// The club id is the only club fact carried in the URL; the editor reads the
// name (and geography) from golf_clubs by id.
const createUrl = (clubId: string, sourceCourseId?: string) => {
  const p = new URLSearchParams({ category: 'golf_club', clubId });
  if (sourceCourseId) p.set('sourceCourseId', sourceCourseId);
  return `/business/create?${p.toString()}`;
};

const businessLocation = (b: BusinessMembership['business']) =>
  [b.city, b.region, b.country].filter(Boolean).join(', ') || b.location || '';

const initialsOf = (name: string) =>
  name.split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]?.toUpperCase() ?? '').join('') || '?';

const LogoTile: React.FC<{ name: string; logoUrl: string | null }> = ({ name, logoUrl }) => (
  <div
    style={{
      width: 40, height: 40, borderRadius: 10, background: '#23262E', overflow: 'hidden',
      display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
      fontSize: 13, fontWeight: 700, color: INKC,
    }}
  >
    {logoUrl ? (
      <img src={logoUrl} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
    ) : (
      initialsOf(name)
    )}
  </div>
);

const PrimaryButton: React.FC<{
  onClick: () => void;
  disabled?: boolean;
  loading?: boolean;
  children: React.ReactNode;
}> = ({ onClick, disabled, loading, children }) => (
  <button
    type="button"
    data-claim-primary=""
    onClick={onClick}
    disabled={disabled || loading}
    className="w-full flex items-center justify-center transition-all active:scale-[0.98]"
    style={{
      height: 52,
      borderRadius: 14,
      background: disabled ? 'rgba(255,255,255,0.06)' : INKC,
      color: disabled ? DIM : ON_INK,
      fontSize: 16,
      fontWeight: 650,
      gap: 8,
      border: 'none',
      cursor: disabled || loading ? 'not-allowed' : 'pointer',
    }}
  >
    {loading ? <Loader2 size={18} className="animate-spin" /> : (
      <>
        {children}
        <ArrowRight size={17} color={disabled ? DIM : ON_INK} strokeWidth={2.2} />
      </>
    )}
  </button>
);

const Footnote: React.FC<{ text: string }> = ({ text }) => (
  <div style={{ fontSize: 12, lineHeight: 1.5, color: DIM, textAlign: 'center', marginTop: 14 }}>
    {text}
  </div>
);

const ClaimCourseSheet: React.FC<ClaimCourseSheetProps> = ({
  open: openProp,
  onClose,
  clubId,
  sourceCourseId,
}) => {
  // GUEST §5: a guest never reaches the claim sheet; the action card opens.
  const open = useGuestSheetGate(openProp, onClose, 'claim_course');
  const { t } = useTranslation('courses');
  const navigate = useNavigate();
  const { user } = useSupabaseSession();
  const { data: memberships, isLoading } = useMyBusinesses(user?.id);
  const { data: club } = useQuery({
    queryKey: ['golf-club', clubId],
    enabled: open && !!clubId,
    staleTime: 10 * 60 * 1000,
    queryFn: () => fetchGolfClub(clubId),
  });
  const clubName = club?.name ?? '';

  /* §1 — figures for sourceCourseId, all shared cache entries. */
  const { data: stats } = useCourseStatsDetail(sourceCourseId, open);
  const { data: analysis } = useCourseHoleAnalysis(sourceCourseId);
  const { data: sampleRows } = useCourseReviewSample(sourceCourseId ?? '', user?.id);
  const { data: media } = useCourseMediaCounts(sourceCourseId);
  const { data: unanswered } = useUnansweredReviewCount(sourceCourseId, open);

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const { claimable, linkedGolf } = useMemo(() => {
    const list = memberships ?? [];
    const golf = list.filter(
      (m) =>
        m.business.category === 'Golf Club' &&
        !m.business.is_deleted &&
        (m.role === 'owner' || m.role === 'admin'),
    );
    return {
      claimable: golf.filter((m) => m.business.club_id == null),
      linkedGolf: golf.filter((m) => m.business.club_id != null),
    };
  }, [memberships]);

  /* The linked state's card names the club that profile already runs. */
  const linkedClubId = claimable.length === 0 && linkedGolf.length > 0
    ? linkedGolf[0].business.club_id
    : null;
  const { data: linkedClub } = useQuery({
    queryKey: ['golf-club', linkedClubId],
    enabled: open && !!linkedClubId,
    staleTime: 10 * 60 * 1000,
    queryFn: () => fetchGolfClub(linkedClubId as string),
  });

  // Auto-select first claimable when list resolves
  React.useEffect(() => {
    if (!selectedId && claimable.length > 0) {
      setSelectedId(claimable[0].business.id);
    }
  }, [claimable, selectedId]);

  // Reset on close
  React.useEffect(() => {
    if (!open) {
      setSelectedId(null);
      setSubmitting(false);
      setErrorMessage(null);
    }
  }, [open]);

  /* §9 — analytics. Open is tracked once per opening, with the settled state. */
  const state: 'signed_out' | 'claimable' | 'linked' | 'no_profile' = !user
    ? 'signed_out'
    : claimable.length > 0
      ? 'claimable'
      : linkedGolf.length > 0
        ? 'linked'
        : 'no_profile';
  const trackedOpen = useRef(false);
  React.useEffect(() => {
    if (!open) { trackedOpen.current = false; return; }
    if (trackedOpen.current) return;
    if (user && isLoading) return;
    trackedOpen.current = true;
    analyticsEvents.track('claim_sheet_open', {
      state, club_id: clubId, course_id: sourceCourseId ?? null,
    });
  }, [open, user, isLoading, state, clubId, sourceCourseId]);

  const goToCreate = () => {
    analyticsEvents.track('claim_sheet_setup_profile', {
      club_id: clubId, course_id: sourceCourseId ?? null,
    });
    onClose();
    navigate(createUrl(clubId, sourceCourseId));
  };

  const handleSubmitClaim = async () => {
    if (!selectedId || submitting) return;
    analyticsEvents.track('claim_sheet_submit', {
      club_id: clubId, course_id: sourceCourseId ?? null,
    });
    setSubmitting(true);
    setErrorMessage(null);
    try {
      const { data, error } = await supabase.functions.invoke('request-course-claim', {
        body: {
          business_id: selectedId,
          club_id: clubId,
          club_key: null,
          source_course_id: sourceCourseId ?? null,
          proof_note: null,
        },
      });
      if (error || (data && data.ok === false)) {
        const msg =
          (data && data.error) ||
          error?.message ||
          t('courseDetail.claim.sheet.submitError');
        setErrorMessage(String(msg));
        setSubmitting(false);
        return;
      }
      toast.success(t('courseDetail.claim.sheet.submitted'));
      onClose();
    } catch (err) {
      AppLog.error('[ClaimCourseSheet]', 'submit failed', err);
      setErrorMessage(t('courseDetail.claim.sheet.submitError'));
      setSubmitting(false);
    }
  };

  /* ---- §4 Already on clbhouz panel ---- */
  const rounds = stats?.rounds_tracked ?? 0;
  const community = useMemo(
    () => (sampleRows ? reviewsCommunitySample(sampleRows, user?.id) : null),
    [sampleRows, user?.id],
  );
  const showRounds = rounds > 0;
  const showRating = !!community && community.score != null && hasCommunityAverage(community.ratingCount);
  const photos = media?.photos ?? 0;
  const showPhotos = photos > 0;
  const holes = useMemo(() => analysis?.holes ?? [], [analysis]);
  const showHoles = holes.length >= 9;
  const unansweredCount = unanswered ?? 0;
  const showUnanswered = unansweredCount > 0;
  const showPanel = showRounds || showRating || showPhotos || showHoles || showUnanswered;

  const hardestNo = showHoles ? pickHardestHole(holes) : null;
  const hardestIdx = hardestNo != null ? holes.findIndex((h) => h.hole_no === hardestNo) : -1;
  const hardestHole = hardestIdx >= 0 ? holes[hardestIdx] : null;
  const barHeights = showHoles ? holeBarHeights(holes) : [];

  const renderPanel = () => {
    if (!showPanel) return null;
    return (
      <div
        data-claim-panel=""
        style={{
          marginTop: 20, padding: 16, borderRadius: 16,
          background: 'rgba(255,255,255,0.03)', border: `1px solid ${TRACK}`,
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
          <div style={LABEL}>{t('courseDetail.claim.sheet.panelKicker')}</div>
          <div
            style={{ ...LABEL, fontSize: 8.5 }}
            data-claim-panel-state={rounds < 10 ? 'early' : 'live'}
          >
            {t(rounds < 10 ? 'courseDetail.claim.sheet.earlyData' : 'courseDetail.claim.sheet.live')}
          </div>
        </div>

        {(showRounds || showRating || showPhotos) && (
          <div style={{ display: 'flex', gap: 12, marginTop: 16 }}>
            {showRounds && (
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: INKC, lineHeight: 1, ...NUM }}>
                  {rounds}
                </div>
                <div style={{ ...LABEL, fontSize: 8.5, marginTop: 8 }}>
                  {t('courseDetail.claim.sheet.roundsMeasured')}
                </div>
              </div>
            )}
            {showRating && community && (
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: INKC, lineHeight: 1, ...NUM }}>
                  {community.score?.toFixed(1)}
                </div>
                <div style={{ ...LABEL, fontSize: 8.5, marginTop: 8 }}>
                  {t('courseDetail.claim.sheet.rated')}
                </div>
                <div style={{ fontSize: 11.5, color: MUTE, marginTop: 4, ...NUM }}>
                  {t('courseDetail.claim.sheet.reviewsCount', { count: community.ratingCount })}
                </div>
              </div>
            )}
            {showPhotos && (
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: INKC, lineHeight: 1, ...NUM }}>
                  {photos}
                </div>
                <div style={{ ...LABEL, fontSize: 8.5, marginTop: 8 }}>
                  {t('courseDetail.claim.sheet.photos')}
                </div>
              </div>
            )}
          </div>
        )}

        {showHoles && hardestHole && (
          <>
            <div style={{ height: 1, background: TRACK, margin: '16px 0 14px' }} />
            <div style={{ ...LABEL, fontSize: 8.5, marginBottom: 12 }}>
              {t('courseDetail.claim.sheet.holeByHole')}
            </div>
            <div data-claim-hole-strip="" style={{ display: 'flex', alignItems: 'flex-end', gap: 3, height: 56 }}>
              {holes.map((h, i) => (
                <div
                  key={h.hole_no}
                  data-claim-bar={h.hole_no === hardestNo ? 'hardest' : undefined}
                  style={{
                    flex: 1,
                    height: `${barHeights[i]}%`,
                    borderRadius: 3,
                    background: h.hole_no === hardestNo ? INKC : 'rgba(255,255,255,0.22)',
                  }}
                />
              ))}
            </div>
            <div style={{ display: 'flex', gap: 3, marginTop: 6 }}>
              {holes.map((h, i) => {
                const isHardest = i === hardestIdx;
                const showNo = isHardest
                  || ((i === 0 || i === holes.length - 1 || (i + 1) % 3 === 0) && Math.abs(i - hardestIdx) > 1);
                return (
                  <div
                    key={h.hole_no}
                    style={{
                      flex: 1, textAlign: 'center', fontSize: 8.5,
                      fontWeight: isHardest ? 700 : 500,
                      color: isHardest ? INKC : DIM,
                      ...NUM,
                    }}
                  >
                    {showNo ? String(h.hole_no) : ''}
                  </div>
                );
              })}
            </div>
            <div style={{ fontSize: 13, lineHeight: 1.45, color: MUTE, marginTop: 12 }}>
              {t('courseDetail.claim.sheet.hardestPre')}
              <span style={{ color: INKC, fontWeight: 600 }}>{ordinal(hardestHole.hole_no)}</span>
              {t('courseDetail.claim.sheet.hardestMid')}
              <span style={{ color: INKC, fontWeight: 600, ...NUM }}>
                +{hardestHole.avg_to_par.toFixed(2)}
              </span>
              {t('courseDetail.claim.sheet.hardestPost')}
            </div>
          </>
        )}

        {showUnanswered && (
          <div
            data-claim-unanswered=""
            style={{
              display: 'flex', alignItems: 'center', gap: 10, marginTop: 14,
              padding: '11px 12px', borderRadius: 12, background: 'rgba(255,255,255,0.04)',
            }}
          >
            <MessageSquare size={16} color={INKC} style={{ flexShrink: 0 }} />
            <div style={{ flex: 1, fontSize: 13, color: MUTE }}>
              <span style={{ color: INKC, fontWeight: 600, ...NUM }}>
                {t('courseDetail.claim.sheet.unansweredCount', { count: unansweredCount })}
              </span>
              {t('courseDetail.claim.sheet.unansweredTail')}
            </div>
          </div>
        )}
      </div>
    );
  };

  /* ---- §5 When it's yours ---- */
  const gains: { icon: React.ReactNode; title: string; sub: string }[] = [
    {
      icon: <MessageSquare size={18} color={INKC} />,
      title: t('courseDetail.claim.sheet.gainReplyTitle'),
      sub: t('courseDetail.claim.sheet.gainReplySub'),
    },
    {
      icon: <BarChart3 size={18} color={INKC} />,
      title: t('courseDetail.claim.sheet.gainMeasuredTitle'),
      sub: t('courseDetail.claim.sheet.gainMeasuredSub'),
    },
    {
      icon: <Eye size={18} color={INKC} />,
      title: t('courseDetail.claim.sheet.gainInterestedTitle'),
      sub: t('courseDetail.claim.sheet.gainInterestedSub'),
    },
    {
      icon: <Calendar size={18} color={INKC} />,
      title: t('courseDetail.claim.sheet.gainTeeTimesTitle'),
      sub: t('courseDetail.claim.sheet.gainTeeTimesSub'),
    },
  ];

  const renderGains = () => (
    <div data-claim-gains="">
      <div style={{ ...LABEL, margin: '24px 0 4px' }}>{t('courseDetail.claim.sheet.gainsTitle')}</div>
      {gains.map((g, i) => (
        <div key={i} style={{ display: 'flex', gap: 14, padding: '14px 0', borderTop: `1px solid ${TRACK}` }}>
          <div
            style={{
              width: 36, height: 36, borderRadius: 10, background: 'rgba(255,255,255,0.06)',
              display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
            }}
          >
            {g.icon}
          </div>
          <div style={{ minWidth: 0 }}>
            <div style={{ fontSize: 15, fontWeight: 600, color: INKC }}>{g.title}</div>
            <div style={{ fontSize: 13, lineHeight: 1.45, color: MUTE, marginTop: 3 }}>{g.sub}</div>
          </div>
        </div>
      ))}
    </div>
  );

  /* ---- §6 How it works ---- */
  const renderSteps = () => {
    const step1Done = claimable.length > 0;
    const steps = [
      t('courseDetail.claim.sheet.stepProfile'),
      t('courseDetail.claim.sheet.stepClaim'),
      t('courseDetail.claim.sheet.stepHandover'),
    ];
    return (
      <>
        <div style={{ height: 1, background: TRACK, margin: '6px 0 20px' }} />
        <div style={{ ...LABEL, marginBottom: 14 }}>{t('courseDetail.claim.sheet.stepsTitle')}</div>
        <div data-claim-steps="" style={{ display: 'flex', alignItems: 'flex-start' }}>
          {steps.map((label, i) => {
            const done = i === 0 && step1Done;
            return (
              <div
                key={i}
                data-claim-step={done ? 'done' : 'todo'}
                style={{
                  flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center',
                  textAlign: 'center', position: 'relative',
                }}
              >
                {i > 0 && (
                  <div
                    aria-hidden
                    style={{
                      position: 'absolute', top: 13, right: '50%', width: '100%', height: 1,
                      background: TRACK,
                    }}
                  />
                )}
                <div
                  style={{
                    position: 'relative', width: 26, height: 26, borderRadius: 13,
                    border: `1px solid ${done ? INKC : 'rgba(255,255,255,0.18)'}`,
                    background: done ? INKC : SHEET,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 12, fontWeight: 700, color: done ? ON_INK : MUTE, ...NUM,
                  }}
                >
                  {done ? <Check size={14} color={ON_INK} strokeWidth={2.6} /> : String(i + 1)}
                </div>
                <div
                  style={{
                    fontSize: 11.5, fontWeight: 600, color: done ? MUTE : INKC,
                    marginTop: 8, lineHeight: 1.35, padding: '0 4px',
                  }}
                >
                  {label}
                </div>
              </div>
            );
          })}
        </div>
        <div style={{ height: 1, background: TRACK, margin: '22px 0 18px' }} />
      </>
    );
  };

  /* ---- §7 button area, by the existing states ---- */
  const renderActions = () => {
    if (!user) {
      return (
        <div data-claim-actions="">
          <p style={{ fontSize: 13.5, lineHeight: 1.5, color: MUTE, marginBottom: 14 }}>
            {t('courseDetail.claim.sheet.signInBody')}
          </p>
          <PrimaryButton onClick={() => { onClose(); navigate('/auth'); }}>
            {t('courseDetail.claim.sheet.signIn')}
          </PrimaryButton>
          <Footnote text={t('courseDetail.claim.sheet.footnote')} />
        </div>
      );
    }

    if (isLoading) {
      return (
        <div data-claim-actions="" style={{ padding: '4px 0' }}>
          <div style={{ height: 14, width: '70%', background: TRACK, borderRadius: 6, marginBottom: 12 }} />
          <div style={{ height: 60, background: 'rgba(255,255,255,0.06)', borderRadius: 14, marginBottom: 12 }} />
          <div style={{ height: 52, background: 'rgba(255,255,255,0.06)', borderRadius: 14 }} />
        </div>
      );
    }

    if (claimable.length > 0) {
      return (
        <div data-claim-actions="">
          <div style={{ ...LABEL, marginBottom: 10 }}>{t('courseDetail.claim.sheet.claimAsLabel')}</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {claimable.map((m) => {
              const selected = selectedId === m.business.id;
              return (
                <button
                  key={m.business.id}
                  type="button"
                  data-claim-profile-card=""
                  data-claim-selected={selected ? 'true' : undefined}
                  onClick={() => setSelectedId(m.business.id)}
                  className="w-full flex items-center text-left transition-all active:scale-[0.99]"
                  style={{
                    padding: 12,
                    borderRadius: 14,
                    gap: 12,
                    background: selected ? 'rgba(255,255,255,0.04)' : 'transparent',
                    border: `1px solid ${selected ? INKC : TRACK}`,
                  }}
                >
                  <LogoTile name={m.business.name} logoUrl={m.business.logo_url} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 15, fontWeight: 600, color: INKC }}>{m.business.name}</div>
                    <div style={{ fontSize: 12.5, color: MUTE, marginTop: 2 }}>
                      {t('courseDetail.claim.sheet.golfClubProfile')}
                      {businessLocation(m.business) ? ` · ${businessLocation(m.business)}` : ''}
                    </div>
                  </div>
                  {selected && (
                    <div
                      style={{
                        width: 22, height: 22, borderRadius: 11, background: INKC,
                        display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
                      }}
                    >
                      <Check size={13} color={ON_INK} strokeWidth={3} />
                    </div>
                  )}
                </button>
              );
            })}
          </div>

          {errorMessage && (
            <p style={{ fontSize: 13, color: '#E24B3F', marginTop: 12, textAlign: 'center' }}>
              {errorMessage}
            </p>
          )}

          <div style={{ height: 14 }} />
          <PrimaryButton
            onClick={handleSubmitClaim}
            disabled={!selectedId}
            loading={submitting}
          >
            {t('courseDetail.claim.sheet.claimButton', { clubName })}
          </PrimaryButton>

          <button
            type="button"
            onClick={goToCreate}
            className="w-full mt-3 text-[13px] font-semibold"
            style={{ color: MUTE, padding: '8px 0' }}
          >
            {t('courseDetail.claim.sheet.setupInstead')}
          </button>
          <Footnote text={t('courseDetail.claim.sheet.footnote')} />
        </div>
      );
    }

    if (linkedGolf.length > 0) {
      const first = linkedGolf[0].business;
      return (
        <div data-claim-actions="">
          <div
            data-claim-profile-card=""
            className="flex items-center"
            style={{
              padding: 12, borderRadius: 14, gap: 12,
              border: `1px solid ${TRACK}`, background: 'rgba(255,255,255,0.03)',
            }}
          >
            <LogoTile name={first.name} logoUrl={first.logo_url} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 15, fontWeight: 600, color: INKC }}>{first.name}</div>
              <div style={{ fontSize: 12.5, color: MUTE, marginTop: 2 }}>
                {t('courseDetail.claim.sheet.alreadyRuns', { name: linkedClub?.name ?? first.name })}
              </div>
            </div>
          </div>
          <p style={{ fontSize: 13.5, lineHeight: 1.5, color: MUTE, margin: '12px 0 14px' }}>
            {t('courseDetail.claim.sheet.linkedBody', { clubName })}
          </p>
          <PrimaryButton onClick={goToCreate}>
            {t('courseDetail.claim.sheet.setupForClub')}
          </PrimaryButton>
          <Footnote text={t('courseDetail.claim.sheet.footnote')} />
        </div>
      );
    }

    /* No Golf Club profile, or profiles only in other categories. */
    return (
      <div data-claim-actions="">
        <p style={{ fontSize: 13.5, lineHeight: 1.5, color: MUTE, marginBottom: 14 }}>
          {t('courseDetail.claim.sheet.noProfileBody')}
        </p>
        <PrimaryButton onClick={goToCreate}>
          {t('courseDetail.claim.sheet.setupGolfClub')}
        </PrimaryButton>
        <Footnote text={t('courseDetail.claim.sheet.footnote')} />
      </div>
    );
  };

  return (
    <BottomSheet
      open={open}
      onClose={onClose}
      topRadius={28}
      grabberPadding="8px 0 0"
      scrollBody
      style={{ paddingBottom: 0 }}
    >
      <div
        style={{
          position: 'relative',
          padding: '28px 20px 0',
          paddingBottom: 'calc(34px + env(safe-area-inset-bottom, 0px))',
        }}
      >
        <button
          type="button"
          aria-label={t('courseDetail.claim.sheet.close')}
          onClick={onClose}
          style={{
            position: 'absolute', top: 4, right: 16, width: 32, height: 32, borderRadius: 16,
            background: 'rgba(255,255,255,0.06)', border: 'none',
            display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
          }}
        >
          <X size={16} color={INKC} />
        </button>

        <div data-claim-header="">
          <div style={LABEL}>{t('courseDetail.claim.sheet.kicker')}</div>
          <h2
            style={{
              fontSize: 21, fontWeight: 700, color: INKC, lineHeight: 1.25,
              marginTop: 7, paddingRight: 36,
            }}
          >
            {t('courseDetail.claim.sheet.title', { clubName })}
          </h2>
          <p style={{ fontSize: 14, lineHeight: 1.5, color: MUTE, marginTop: 8 }}>
            {t('courseDetail.claim.sheet.subline')}
          </p>
        </div>

        {renderPanel()}
        {renderGains()}
        {renderSteps()}
        {renderActions()}
      </div>
    </BottomSheet>
  );
};

export default ClaimCourseSheet;

src/components/courses/course-detail/Cou:
/**
 * BEFORE_YOU_GO — the course website sheet, replacing ExternalLinkSheet on
 * the course About tab (ExternalLinkSheet.tsx itself is untouched on disk).
 *
 * Every piece drops out on its own when its data is missing: no photo band
 * without a thumbnail, no figures without measured rounds, no band sentence
 * without an index and a big-enough sample, no "you" panel when it would only
 * say "You haven't played it yet", no tiles without their data.
 *
 * DATA: every read reuses a hook the course page already calls (same query
 * keys, so nothing is fetched twice); the only new read is
 * useCourseBandAverage, which fires only for a signed-in member with an index.
 *
 * NO NEGATIVE LETTER-SPACING anywhere in this sheet.
 */
import React, { useEffect, useMemo, useState } from 'react';
import { getInitialsFromName } from '@/lib/avatarFallback';
import { useTranslation } from 'react-i18next';
import {
  ArrowUpRight, Bookmark, Calendar, Check, ChevronRight, Link as LinkIcon,
  MapPin, Phone, Share, X,
} from 'lucide-react';
import { Sheet, SheetContent, SheetTitle } from '@/components/ui/sheet';
import { toast } from '@/lib/toast';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { openExternalUrl } from '@/utils/median/openExternalUrl';
import { openMapsUrl } from '@/utils/median/openMapsUrl';
import { isIOS } from '@/utils/env';
import { ensureProtocol } from '@/lib/business/socialLinks';
import { withShareSource } from '@/lib/business/shareBusinessProfile';
import { trackBusinessAction } from '@/lib/businessAnalyticsTracking';
import { useSupabaseSession } from '@/hooks/useSupabaseSession';
import { useCourseStatsDetail } from '@/hooks/feed/useCourseStatsDetail';
import { useCourseHoleAnalysis, type CourseHole } from '@/hooks/gam/useCourseHoleAnalysis';
import { useCourseReviewSample } from '@/hooks/useCourseReviewSample';
import { reviewsCommunitySample } from '@/lib/reviews/communitySample';
import { hasCommunityAverage } from '@/lib/reviews/sampleRules';
import { useCourseClaimStatus } from '@/hooks/useCourseClaim';
import { useBoardCoursePlayers } from '@/components/explore-tab-new/courseled/hooks/useBoardCoursePlayers';
import { DEFAULT_FILTERS } from '@/components/explore-tab-new/courseled/boardFilters';
import { CIRCLE_PLAYERS_LIMIT, circleNamesLine } from './you/circleNamesLine';
import { useViewerHandicapIndex } from '@/components/explore-tab-new/courseled/hooks/useGolfThisWeek';
import { useCoursePersonalStatus } from '@/hooks/useCoursePersonalStatus';
import { useCourseBandAverage } from '@/hooks/useCourseBandAverage';
import { pickHardestHole } from '@/components/business/ClubHowItPlays';
import { toParParts } from '@/features/courses/components/holes/analytical/tokens';
import { ordinal } from '@/lib/text/numbers';

const BG = '#16161A';
const INK = '#F8FAFC';
const ON_INK = '#0A0A0C';
const MUTE = 'rgba(248,250,252,0.62)';
const DIM = 'rgba(248,250,252,0.42)';
const HAIR = 'rgba(255,255,255,0.08)';
const AMBER = '#F7931E';

const LABEL: React.CSSProperties = {
  fontSize: 9.5,
  fontWeight: 700,
  letterSpacing: '0.14em',
  textTransform: 'uppercase',
  color: DIM,
};

/** Same logic as ExternalLinkSheet's extractDomain (that file is untouched). */
const extractDomain = (url: string): string => {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url.replace(/^https?:\/\//, '').replace(/^www\./, '');
  }
};

export interface CourseWebsiteSheetCourse {
  id: string;
  name: string;
  website_url?: string | null;
  thumbnail_image?: string;
  latitude?: number | null;
  longitude?: number | null;
  club_id?: string | null;
}

interface CourseWebsiteSheetProps {
  open: boolean;
  onClose: () => void;
  course: CourseWebsiteSheetCourse;
  coords: { lat: number; lng: number } | null;
  onTabChange?: (tab: string) => void;
}

const CourseWebsiteSheet: React.FC<CourseWebsiteSheetProps> = ({
  open,
  onClose,
  course,
  coords,
  onTabChange,
}) => {
  const { t } = useTranslation('common');
  const { user } = useSupabaseSession();
  const [copied, setCopied] = useState(false);

  const { data: stats } = useCourseStatsDetail(course.id, true);
  const { data: analysis } = useCourseHoleAnalysis(course.id);
  const { data: reviewRows } = useCourseReviewSample(course.id, user?.id);
  const { data: claimStatus } = useCourseClaimStatus(course.id);
  const circlePlayers = useBoardCoursePlayers(
    user?.id,
    course.id,
    { ...DEFAULT_FILTERS, scope: 'circle', window: 'all' },
    { limit: CIRCLE_PLAYERS_LIMIT },
  );
  const { index } = useViewerHandicapIndex(user?.id);
  const personalStatus = useCoursePersonalStatus(course.id);
  const { data: bandAverage } = useCourseBandAverage(course.id, index);

  const business = claimStatus?.state === 'claimed' ? claimStatus.business : null;
  const rounds = stats?.rounds_tracked ?? null;
  const yourRounds = stats?.your_rounds ?? 0;

  const holes: CourseHole[] | null =
    analysis?.available && (analysis.holes?.length ?? 0) >= 9
      ? [...analysis.holes].sort((a, b) => a.hole_no - b.hole_no)
      : null;

  const sample = useMemo(
    () => (reviewRows ? reviewsCommunitySample(reviewRows, user?.id) : null),
    [reviewRows, user?.id],
  );
  const showRating = sample != null && hasCommunityAverage(sample.ratingCount) && sample.score != null;

  const circle = useMemo(() => circleNamesLine(circlePlayers.data), [circlePlayers.data]);

  useEffect(() => {
    if (open) analyticsEvents.track('course_website_sheet_open', { course_id: course.id });
  }, [open, course.id]);

  const track = (event: string) => analyticsEvents.track(event, { course_id: course.id });

  const handleVisitWebsite = () => {
    if (!course.website_url) return;
    track('course_website_open');
    if (business) trackBusinessAction(business.id, 'website', user?.id);
    openExternalUrl(course.website_url);
    onClose();
  };

  const handleTeeTimes = () => {
    if (!business?.booking_url) return;
    track('course_tee_times');
    trackBusinessAction(business.id, 'website', user?.id);
    openExternalUrl(ensureProtocol(business.booking_url));
  };

  const handleCall = () => {
    if (!business?.phone) return;
    track('course_call');
    trackBusinessAction(business.id, 'call', user?.id);
    window.location.href = `tel:${business.phone}`;
  };

  const handleDirections = () => {
    if (!coords) return;
    track('course_directions');
    if (business) trackBusinessAction(business.id, 'directions', user?.id);
    if (isIOS) {
      openMapsUrl(
        `https://maps.apple.com/?q=${encodeURIComponent(course.name)}&ll=${coords.lat},${coords.lng}`,
      );
    } else {
      openMapsUrl(
        `https://www.google.com/maps/search/?api=1&query=${coords.lat},${coords.lng}`,
      );
    }
  };

  const handleCopyLink = async () => {
    if (!course.website_url) return;
    track('course_copy_link');
    try {
      await navigator.clipboard.writeText(course.website_url);
      setCopied(true);
      toast.success(t('courseDetail.websiteSheet.copiedToast', { defaultValue: 'Copied to clipboard' }));
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error(t('courseDetail.websiteSheet.copyFailed', { defaultValue: 'Failed to copy link' }));
    }
  };

  const handleShare = async () => {
    track('course_share');
    const url = withShareSource(`${window.location.origin}/courses/${course.id}`);
    if (navigator.share) {
      try {
        await navigator.share({ title: course.name, url });
      } catch {
        /* user cancelled the native sheet */
      }
    } else {
      try {
        await navigator.clipboard.writeText(url);
        toast.success(t('courseDetail.websiteSheet.copiedToast', { defaultValue: 'Copied to clipboard' }));
      } catch {
        toast.error(t('courseDetail.websiteSheet.copyFailed', { defaultValue: 'Failed to copy link' }));
      }
    }
  };

  const handleSaveToList = () => {
    track('course_save_to_list');
    personalStatus.setWantToPlay(true);
  };

  /* ── Quick action tiles, in order, each only when its data exists ── */
  const tiles: { key: string; label: string; icon: React.ReactNode; onTap: () => void }[] = [];
  if (business?.booking_url) {
    tiles.push({
      key: 'tee-times',
      label: t('courseDetail.websiteSheet.teeTimes', { defaultValue: 'Tee times' }),
      icon: <Calendar style={{ width: 19, height: 19 }} strokeWidth={1.9} />,
      onTap: handleTeeTimes,
    });
  }
  if (business?.phone) {
    tiles.push({
      key: 'call',
      label: t('courseDetail.websiteSheet.call', { defaultValue: 'Call' }),
      icon: <Phone style={{ width: 19, height: 19 }} strokeWidth={1.9} />,
      onTap: handleCall,
    });
  }
  if (coords) {
    tiles.push({
      key: 'directions',
      label: t('courseDetail.websiteSheet.directions', { defaultValue: 'Directions' }),
      icon: <MapPin style={{ width: 19, height: 19 }} strokeWidth={1.9} />,
      onTap: handleDirections,
    });
  }
  tiles.push({
    key: 'copy',
    label: copied
      ? t('courseDetail.websiteSheet.copied', { defaultValue: 'Copied' })
      : t('courseDetail.websiteSheet.copyLink', { defaultValue: 'Copy link' }),
    icon: copied ? (
      <Check style={{ width: 19, height: 19 }} strokeWidth={1.9} />
    ) : (
      <LinkIcon style={{ width: 19, height: 19 }} strokeWidth={1.9} />
    ),
    onTap: handleCopyLink,
  });
  const hasTeeTimes = Boolean(business?.booking_url);
  if (!hasTeeTimes) {
    tiles.push({
      key: 'share',
      label: t('courseDetail.websiteSheet.share', { defaultValue: 'Share' }),
      icon: <Share style={{ width: 19, height: 19 }} strokeWidth={1.9} />,
      onTap: handleShare,
    });
  }
  const shownTiles = tiles.slice(0, 4);
  const shareTileShown = shownTiles.some((tile) => tile.key === 'share');

  /* ── Figures ── */
  const hasRounds = (rounds ?? 0) > 0;
  const toPar = hasRounds ? toParParts(stats?.avg_over_par, 1) : null;
  const totalPar =
    analysis?.available && analysis.holes?.length === 18
      ? analysis.holes.reduce((sum, hole) => sum + hole.par, 0)
      : null;
  const hardestNo = hasRounds
    ? holes
      ? pickHardestHole(holes)
      : stats?.hardest_hole_no ?? null
    : null;
  const hardestHole = hardestNo != null && holes ? holes.find((h) => h.hole_no === hardestNo) : null;
  const hardestOver =
    hardestHole != null
      ? hardestHole.avg_to_par
      : stats?.hardest_hole_plays != null && stats?.hardest_hole_par != null
        ? stats.hardest_hole_plays - stats.hardest_hole_par
        : null;

  /* ── The "you" panel ── */
  const bandSentence =
    user && index != null && bandAverage && bandAverage.rounds >= 5 && bandAverage.golfers >= 3
      ? Math.round(bandAverage.avg_gross)
      : null;
  const showYouPanel = Boolean(user) && (bandSentence != null || yourRounds > 0);

  /* ── People you follow ── */
  const circleText = (() => {
    if (circle.count <= 0) return null;
    const [a, b, c] = circle.shown.map((p) => p.display_name as string);
    if (circle.count === 1) {
      return t('courseDetail.websiteSheet.circleOne', { defaultValue: '{{a}} has played here', a });
    }
    if (circle.count === 2) {
      return t('courseDetail.websiteSheet.circleTwo', { defaultValue: '{{a}} and {{b}} have played here', a, b });
    }
    if (circle.count === 3) {
      return t('courseDetail.websiteSheet.circleThree', { defaultValue: '{{a}}, {{b}} and {{c}} have played here', a, b, c });
    }
    const others = circle.capped ? '500+' : String(circle.count - 2);
    return t('courseDetail.websiteSheet.circleMany', { defaultValue: '{{a}}, {{b}} and {{others}} others you follow have played here', a, b, others });
  })();

  const onList = personalStatus.status?.status === 'want_to_play';
  const showSaveButton = !personalStatus.hasTrackedRounds;

  const hasPhoto = Boolean(course.thumbnail_image);
  const domain = course.website_url ? extractDomain(course.website_url) : '';

  return (
    <Sheet open={open} onOpenChange={(next) => !next && onClose()}>
      <SheetContent
        side="bottom"
        hideCloseButton
        aria-describedby={undefined}
        className="gap-0 border-t-0 p-0"
        style={{
          background: BG,
          borderRadius: '28px 28px 0 0',
          overflow: 'hidden',
          maxHeight: '92vh',
        }}
      >
        <SheetTitle className="sr-only">{course.name}</SheetTitle>
        <div
          data-course-website-sheet
          style={{
            position: 'relative',
            maxHeight: '92vh',
            overflowY: 'auto',
            paddingBottom: 'calc(34px + env(safe-area-inset-bottom, 0px))',
          }}
        >
          {hasPhoto && (
            <div style={{ position: 'relative', height: 132 }}>
              <img
                src={course.thumbnail_image}
                alt=""
                style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
              />
              <div
                aria-hidden="true"
                style={{
                  position: 'absolute',
                  inset: 0,
                  background: 'linear-gradient(to bottom, rgba(22,22,26,0) 40%, #16161A 100%)',
                }}
              />
            </div>
          )}

          {/* Grabber */}
          <div
            aria-hidden="true"
            style={{
              position: 'absolute',
              top: 8,
              left: '50%',
              transform: 'translateX(-50%)',
              width: 36,
              height: 4,
              borderRadius: 2,
              background: hasPhoto ? 'rgba(255,255,255,0.55)' : 'rgba(255,255,255,0.18)',
              zIndex: 2,
            }}
          />

          {/* Close */}
          <button
            type="button"
            aria-label={t('courseDetail.websiteSheet.close', { defaultValue: 'Close' })}
            onClick={onClose}
            style={{
              position: 'absolute',
              top: 16,
              right: 16,
              width: 32,
              height: 32,
