                    'No rounds measured here yet. Play it with your handicap connected and yours is the first.',
                })}
              </div>
            )}

            {/* The "you" panel */}
            {showYouPanel && (
              <div
                style={{
                  marginTop: 18,
                  padding: '12px 14px',
                  borderRadius: 12,
                  background: 'rgba(247,147,30,0.08)',
                  border: '1px solid rgba(247,147,30,0.22)',
                  display: 'flex',
                  gap: 10,
                }}
              >
                <div
                  aria-hidden="true"
                  style={{
                    width: 7,
                    height: 7,
                    borderRadius: '50%',
                    background: AMBER,
