                    flexShrink: 0,
                  }}
                />
                <div style={{ fontSize: 13.5, lineHeight: 1.45, color: MUTE }}>
                  {bandSentence != null && (
                    <span>
                      {t('courseDetail.websiteSheet.bandAverageLead', { defaultValue: 'Golfers off your handicap average' })}{' '}
                      <strong style={{ color: INK, fontWeight: 700 }}>{bandSentence}</strong>{' '}
                      {t('courseDetail.websiteSheet.bandAverageTail', { defaultValue: 'here.' })}{' '}
                    </span>
                  )}
                  {yourRounds > 0 && stats?.your_best != null ? (
                    <span>
                      {t('courseDetail.websiteSheet.yourBestLead', { defaultValue: 'Your best here is' })}{' '}
                      <strong style={{ color: INK, fontWeight: 700 }}>{stats.your_best}</strong>
                      {t('courseDetail.websiteSheet.sentenceEnd', { defaultValue: '.' })}
                    </span>
                  ) : bandSentence != null ? (
                    <span>{t('courseDetail.websiteSheet.notPlayedYet', { defaultValue: "You haven't played it yet." })}</span>
                  ) : null}
                </div>
              </div>
            )}

            {/* People you follow */}
            {circleText && (
              <button
                type="button"
                onClick={() => {
                  onClose();
                  onTabChange?.('you');
                }}
                style={{
                  marginTop: 14,
                  paddingLeft: 7,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 10,
                  width: '100%',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  textAlign: 'left',
                }}
              >
                <div style={{ display: 'flex', flexShrink: 0 }}>
                  {circle.shown.map((player, i) => (
                    <div
                      key={player.user_id}
                      style={{
                        width: 24,
                        height: 24,
                        borderRadius: '50%',
                        border: `2px solid ${BG}`,
                        marginLeft: i === 0 ? 0 : -7,
                        overflow: 'hidden',
                        background: 'rgba(255,255,255,0.10)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: 9,
                        fontWeight: 700,
                        color: INK,
                        flexShrink: 0,
                      }}
                    >
                      {player.profile_photo_url ? (
                        <img
                          src={player.profile_photo_url}
                          alt=""
                          style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                        />
                      ) : (
                        getInitialsFromName(player.display_name) || '?'
                      )}
                    </div>
                  ))}
                </div>
                <span style={{ flex: 1, fontSize: 13, color: MUTE }}>{circleText}</span>
                <ChevronRight style={{ width: 16, height: 16, color: DIM, flexShrink: 0 }} />
              </button>
            )}

            {/* Bottom buttons */}
            {(showSaveButton || !shareTileShown) && (
              <div style={{ marginTop: 20, display: 'flex', gap: 8 }}>
                {showSaveButton && (
                  <button
                    type="button"
                    disabled={onList}
                    onClick={handleSaveToList}
                    style={{
                      flex: 1,
                      height: 46,
                      borderRadius: 14,
                      border: '1px solid rgba(255,255,255,0.14)',
                      background: 'none',
                      color: INK,
                      fontSize: 14,
                      fontWeight: 600,
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 8,
                      cursor: onList ? 'default' : 'pointer',
                      opacity: onList ? 0.7 : 1,
                    }}
                  >
                    <Bookmark
                      style={{ width: 16, height: 16 }}
                      fill={onList ? INK : 'none'}
                    />
                    {onList
                      ? t('courseDetail.websiteSheet.onYourList', { defaultValue: 'On your list' })
                      : t('courseDetail.websiteSheet.saveToList', { defaultValue: 'Save to your list' })}
                  </button>
                )}
                {!shareTileShown && (
                  <button
                    type="button"
                    onClick={handleShare}
                    style={{
                      flex: 1,
                      height: 46,
                      borderRadius: 14,
                      border: '1px solid rgba(255,255,255,0.14)',
                      background: 'none',
                      color: INK,
                      fontSize: 14,
                      fontWeight: 600,
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 8,
                      cursor: 'pointer',
                    }}
                  >
                    <Share style={{ width: 16, height: 16 }} />
                    {t('courseDetail.websiteSheet.shareCourse', { defaultValue: 'Share course' })}
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
};

export default CourseWebsiteSheet;

src/components/courses/course-detail/abo:
/**
 * BRIEF_COURSE_TAB_1A Phase 2 — HOW IT DEFENDS PAR.
 *
 * ONE source: get_course_hole_analysis. F1: the lede states total_rounds
 * (rounds logged with hole-by-hole detail), never rounds_tracked; with
 * total_rounds 0 or no holes the whole section is absent, with no fallback.
 * The red/green bars, the Worst hole cell and the observation all read
 * deriveCourseVerdict, the same computation as the verdict's fact tiles.
 * D4: no cross-course par-type comparison exists, so none is drawn.
 * Replaces HowItPlays on this tab (HowItPlays.tsx is left on disk).
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';
import { formatNumber } from '@/i18n/format';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { A, FIGS, RAMP_TOPAR, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { useCourseHoleAnalysis } from '@/hooks/gam/useCourseHoleAnalysis';
import AboutSection from './AboutSection';
import AllHolesSheet from './AllHolesSheet';
import { deriveCourseVerdict, sharePct, signed } from './courseVerdict';
import { B, BAR_NEUTRAL, Said, SMALL_LABEL } from './verdictBits';

const CHART_H = 56;

/* PTR1.1 — the par-type rows share ONE FIXED scale, −0.20 to +1.20 shots over
   par. It is a constant, never derived from the data: a dot in the same place
   means the same thing on every course, which the old normalise-to-maximum
   bars could never claim. Out-of-range values clamp the DOT to the track end;
   the printed figure always shows the true value. */
export const PAR_SCALE_MIN = -0.2;
export const PAR_SCALE_MAX = 1.2;

/* PTR1.5 (corrected) — the minimum lead before the block may call one par
   type the hardest and paint it red. It governs TWO FIELD AVERAGES being
   close to each other. It deliberately does NOT share LEVEL_EDGE from
   youDerivations (a player's edge against the field on one hole) even though
   both are 0.05 today: tuning the You tab's edge chart must never change when
   the Course tab claims a hardest par type. */
export const HARDEST_MIN_GAP = 0.05;

export interface ParTypeRowInput {
  par: number;
  holes: number;
  perHole: number;
}

/** PTR1.1/PTR1.3 — clamped 0–100 position of a value on the fixed scale. */
export const parTypeTrackPct = (value: number): number =>
  Math.min(100, Math.max(0, ((value - PAR_SCALE_MIN) / (PAR_SCALE_MAX - PAR_SCALE_MIN)) * 100));

/** The level tick's position: where zero sits on the fixed scale. */
export const LEVEL_TICK_PCT = parTypeTrackPct(0);

/** PTR1.4 — hardest first; an exact tie goes to the type with more holes,
 *  then to the lower par number. */
export function orderParTypes(rows: ParTypeRowInput[]): ParTypeRowInput[] {
  return [...rows].sort((a, b) => b.perHole - a.perHole || b.holes - a.holes || a.par - b.par);
}

/** PTR1.5 — the par type that may take red, or null when the leader's gap
 *  over the second is under HARDEST_MIN_GAP (a near-tie claims no hardest). */
export function hardestParType(ordered: ParTypeRowInput[]): ParTypeRowInput | null {
  const [top, second] = ordered;
  if (!top) return null;
  if (second && top.perHole - second.perHole < HARDEST_MIN_GAP) return null;
  return top;
}

const DefendsPar: React.FC<{ courseId: string; courseName?: string | null }> = ({ courseId, courseName }) => {
  const { t } = useTranslation('courses');
  const [searchParams, setSearchParams] = useSearchParams();
  const { data } = useCourseHoleAnalysis(courseId);
  const sample = Number(data?.total_rounds ?? 0);
  const v = React.useMemo(() => (sample > 0 ? deriveCourseVerdict(data?.holes) : null), [data?.holes, sample]);
  const open = searchParams.get('sheet') === 'holes';

  const setSheet = (on: boolean) => {
    const next = new URLSearchParams(searchParams);
    if (on) next.set('sheet', 'holes');
    else next.delete('sheet');
    setSearchParams(next, { replace: true });
  };

  if (!v) return null;

  const max = Math.max(0.01, ...v.holes.map((h) => Math.max(0, h.avg_to_par)));
  const parRows = orderParTypes(v.parTypes);
  const hardestPar = hardestParType(parRows)?.par ?? null;
  const labelled = new Set([v.holes[0].hole_no, 9, v.easiest.hole_no, v.hardest.hole_no]);

  let nineLine: React.ReactNode = null;
  if (v.front != null && v.back != null) {
    const d = v.back - v.front;
    const hardestClause =
      v.hardest.hole_no === v.holes[v.holes.length - 1].hole_no
        ? t('courseDetail.defends.lastHardest', { hole: v.hardest.hole_no })
        : t('courseDetail.defends.hardest', { hole: v.hardest.hole_no });
    nineLine =
      Math.abs(d) < 0.05 ? (
        <>
          {t('courseDetail.defends.ninesLevel')}
          <B>{hardestClause}</B>.
        </>
      ) : (
        <>
          {t(d > 0 ? 'courseDetail.defends.backCosts' : 'courseDetail.defends.frontCosts')}
          <B>{t('courseDetail.defends.shotsMore', { shots: Math.abs(d).toFixed(1) })}</B>
          {t(d > 0 ? 'courseDetail.defends.thanFront' : 'courseDetail.defends.thanBack')}
          <B>{hardestClause}</B>.
        </>
      );
  }

  const o = v.outcomes;
  const bands = o
    ? [
        { key: 'birdie', n: o.birdie, color: RAMP_TOPAR.birdie, label: t('holes.preview.legendBirdie') },
        { key: 'par', n: o.par, color: RAMP_TOPAR.par, label: t('holes.preview.legendPar') },
        { key: 'bogey', n: o.bogey, color: RAMP_TOPAR.bogey, label: t('holes.preview.legendBogey') },
        { key: 'double', n: o.double, color: RAMP_TOPAR.double, label: t('holes.preview.legendDouble') },
      ]
    : [];

  return (
    <AboutSection kicker={t('courseDetail.defends.kicker')} title={t('courseDetail.defends.title')}>
      <p style={{ margin: 0, fontSize: 12.5, lineHeight: 1.5, color: A.MUTE, fontFamily: SANS, ...FIGS }}>
        {t('courseDetail.defends.lede', { count: sample, rounds: formatNumber(sample) })}
      </p>

      <div style={{ marginTop: 14 }} aria-hidden="true">
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: `repeat(${v.holes.length}, minmax(0, 1fr))`,
            gap: 4,
            alignItems: 'end',
            height: CHART_H,
            borderBottom: `1px solid ${A.HAIRLINE}`,
          }}
        >
          {v.holes.map((h) => (
            <span
              key={h.hole_no}
              data-testid={`defends-bar-${h.hole_no}`}
              style={{
                display: 'block',
                height: Math.max(2, (Math.max(0, h.avg_to_par) / max) * CHART_H),
                borderRadius: 1.5,
                background:
                  h.hole_no === v.hardest.hole_no ? A.RED : h.hole_no === v.easiest.hole_no ? A.GREEN : BAR_NEUTRAL,
              }}
            />
          ))}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: `repeat(${v.holes.length}, minmax(0, 1fr))`, gap: 4, marginTop: 6 }}>
          {v.holes.map((h) => {
            const hi = h.hole_no === v.hardest.hole_no ? A.RED : h.hole_no === v.easiest.hole_no ? A.GREEN : null;
            return (
              <span
                key={h.hole_no}
                style={{ textAlign: 'center', fontSize: 8.5, fontWeight: hi ? 800 : 700, color: hi ?? A.FAINT, ...FIGS }}
              >
                {labelled.has(h.hole_no) ? h.hole_no : ''}
              </span>
            );
          })}
        </div>
      </div>

      <div style={{ display: 'flex', gap: 10, marginTop: 13 }}>
        {[
          ...(v.front != null && v.back != null
            ? [
                { v: signed(v.front), l: t('courseDetail.defends.front') },
                { v: signed(v.back), l: t('courseDetail.defends.back') },
              ]
            : []),
          { v: signed(v.hardest.avg_to_par), l: t('courseDetail.defends.worst') },
        ].map((c) => (
          <div key={c.l} style={{ flex: 1, border: `1px solid ${A.HAIRLINE}`, borderRadius: 10, padding: 10 }}>
            <div style={{ fontSize: 19, fontWeight: 800, letterSpacing: '-0.03em', color: A.INK, ...FIGS }}>{c.v}</div>
            <div style={{ ...SMALL_LABEL, lineHeight: 1, marginTop: 4 }}>{c.l}</div>
          </div>
        ))}
      </div>
      {nineLine ? <Said>{nineLine}</Said> : null}

      <div style={{ ...SMALL_LABEL, marginTop: 18 }}>{t('courseDetail.defends.parScaleLabel')}</div>
      <div style={{ marginTop: 10 }}>
        {parRows.map((p) => {
          const amber = p.par === hardestPar;
          return (
            <div
              key={p.par}
              data-testid={`par-type-row-${p.par}`}
              style={{
                display: 'grid',
                gridTemplateColumns: '74px minmax(0, 1fr) 58px',
                alignItems: 'center',
                gap: 11,
                padding: '7px 0',
                fontFamily: SANS,
              }}
            >
              <div>
                <div style={{ fontSize: 12, fontWeight: 700, color: A.INK, lineHeight: 1.2 }}>
                  {t('courseDetail.verdict.parType', { par: p.par })}
                </div>
                <div style={{ fontSize: 9.5, fontWeight: 400, color: A.DIM, marginTop: 2, ...FIGS }}>
                  {t('courseDetail.defends.parHoles', { count: p.holes, holes: formatNumber(p.holes) })}
                </div>
              </div>
              <div style={{ position: 'relative', height: 3, borderRadius: 2, background: A.TRACK }}>
                <span
                  aria-hidden="true"
                  style={{
                    position: 'absolute',
                    left: `${LEVEL_TICK_PCT}%`,
                    top: -4,
                    width: 1,
                    height: 11,
                    background: 'rgba(255,255,255,0.22)',
                  }}
                />
                <span
                  data-testid={`par-type-dot-${p.par}`}
                  style={{
                    position: 'absolute',
                    left: `${parTypeTrackPct(p.perHole)}%`,
                    top: '50%',
                    width: 9,
                    height: 9,
                    borderRadius: '50%',
                    transform: 'translate(-50%, -50%)',
                    background: amber ? A.RED : 'rgba(248,250,252,0.62)',
                  }}
                />
              </div>
              <div
                data-testid={`par-type-figure-${p.par}`}
                style={{
                  textAlign: 'right',
                  fontSize: 15,
                  fontWeight: 800,
                  letterSpacing: '-0.03em',
                  color: amber ? A.RED : A.INK,
                  ...FIGS,
                }}
              >
                {signed(p.perHole, 2)}
              </div>
            </div>
          );
        })}
      </div>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginTop: 3,
          paddingLeft: 85,
          paddingRight: 69,
          fontSize: 9.5,
          color: A.FAINT,
          fontFamily: SANS,
          ...FIGS,
        }}
      >
        <span>{signed(PAR_SCALE_MIN, 2)}</span>
        <span>{t('courseDetail.defends.parScaleLevel')}</span>
        <span>{signed(PAR_SCALE_MAX, 2)}</span>
      </div>

      {o ? (
        <>
          <div style={{ display: 'flex', height: 7, borderRadius: 999, overflow: 'hidden', marginTop: 16 }} aria-hidden="true">
            {bands.map((b) => (
              <div key={b.key} style={{ width: `${(b.n / o.total) * 100}%`, background: b.color }} />
            ))}
          </div>
          <div style={{ display: 'flex', marginTop: 9 }}>
            {bands.map((b, i) => (
              <div key={b.key} style={{ flex: 1, textAlign: i >= 2 ? 'right' : 'left' }}>
                <div style={{ fontSize: 15, fontWeight: 800, color: b.key === 'par' ? A.INK : b.color, ...FIGS }}>
                  {sharePct(b.n, o.total)}%
                </div>
                <div style={{ ...SMALL_LABEL, lineHeight: 1, marginTop: 2 }}>{b.label}</div>
              </div>
            ))}
          </div>
        </>
      ) : null}

      <button
        type="button"
        onClick={() => {
          analyticsEvents.track('course_all_18_holes', { course_id: courseId, holes: v.holes.length });
          setSheet(true);
        }}
        style={{ display: 'block', marginTop: 9, padding: 0, background: 'transparent', border: 0, cursor: 'pointer', fontFamily: SANS, fontSize: 12, fontWeight: 700, color: A.AMBER }}
      >
        {t('courseDetail.plays.allHoles', { count: v.holes.length, holes: formatNumber(v.holes.length) })} ›
      </button>
      <AllHolesSheet open={open} onClose={() => setSheet(false)} courseId={courseId} courseName={courseName ?? ''} />
    </AboutSection>
  );
};

export default DefendsPar;

/**
 * HeroCourseRecord — BRIEF_COURSE_HERO_1 / 1A (hero-option-a.html).
 *
 * The course record row under the hero reference line. LOWEST GROSS ONLY —
 * it never carries stableford, net or differential holders.
 *
 * Holders come from useCourseRecordSummary (get_course_legends via
 * useCourseLegends), the same read the record boards use, so the hero and the
 * boards can never name different holders. No second fetch, no re-derivation.
 *
 * Absent cases: no record, or any holder without a showable name → null.
 * Not tappable by brief.
 */
import React from 'react';
import { SURFACE } from '@/lib/tokens/surface';
import { MEDAL_GOLD } from '@/lib/tokens/medals';
import type { CourseLegendRow } from '@/lib/gam/types';
import { displayName } from '@/lib/whs/utils/initials';
import { SquircleAvatar } from '@/components/ui/SquircleAvatar';

const INK = SURFACE.dark.ink;
const AVATAR = 24;
const OVERLAP = 7;
const MAX_AVATARS = 3;

export function heroRecordNames(holders: CourseLegendRow[]): string | null {
  const names = holders.map((h) => displayName(h.user_display_name).trim());
  if (!names.length || names.some((n) => !n)) return null;
  if (names.length === 1) return names[0];
  if (names.length === 2) return `${names[0]} & ${names[1]}`;
  return `${names[0]} & ${names.length - 1} others`;
}

/** True when the hero renders the row; height remains fixed even with a record. */
export function heroRecordVisible(holders: CourseLegendRow[]): boolean {
  return heroRecordNames(holders) != null;
}

/* BRIEF_COURSE_HERO_1B K2 — the app-wide avatar rule wins over the mock's
 *  circles: standard squircle geometry with the canonical 1px hairline ring. */
function Avatar({ row, index }: { row: CourseLegendRow; index: number }) {
  return (
    <span
      style={{
        marginLeft: index === 0 ? 0 : -OVERLAP, flex: '0 0 auto',
        display: 'inline-flex', position: 'relative', zIndex: MAX_AVATARS - index,
      }}
    >
      <SquircleAvatar
        src={row.user_photo_url}
        alt={row.user_display_name ?? ''}
        userId={row.user_id}
        size={AVATAR}
        hairlineRing
      />
    </span>
  );
}

export function HeroCourseRecord({ holders }: { holders: CourseLegendRow[] }) {
  const names = heroRecordNames(holders);
  if (!names) return null;
  const score = holders[0].value;
  return (
    <div style={{ marginTop: 10, display: 'flex', alignItems: 'center', gap: 10 }}>
      <span style={{ display: 'inline-flex', flex: '0 0 auto' }}>
        {holders.slice(0, MAX_AVATARS).map((h, i) => <Avatar key={h.user_id} row={h} index={i} />)}
      </span>
      <div style={{ minWidth: 0, flex: 1 }}>
        <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.13em', textTransform: 'uppercase', color: MEDAL_GOLD, lineHeight: 1.2 }}>
          Course record
        </div>
        <div style={{ fontSize: 13.5, fontWeight: 700, color: INK, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', lineHeight: 1.3 }}>
          {names}
        </div>
      </div>
      <div style={{ flex: '0 0 auto', display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
        <span className="tabular-nums lining-nums" style={{ fontSize: 21, fontWeight: 800, color: MEDAL_GOLD, lineHeight: 1 }}>
          {Math.round(Number(score))}
        </span>
        <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: '0.13em', textTransform: 'uppercase', color: 'var(--course-record-gross-ink)', marginTop: 4 }}>
          Gross
        </span>
      </div>
    </div>
  );
}

/**
 * BRIEF_COURSE_TAB_1A Phase 1 — THE VERDICT, the first section under the tabs.
 *
 * Figure and caption: get_course_stats_detail.avg_over_par over rounds_tracked
 * (every member, all time, 18 holes — D1). Placing bar: harder_than_pct, which
 * is NOT regional (D2) — never print a geography beside it.
 * Fact tiles and observation: deriveCourseVerdict over get_course_hole_analysis
 * ONLY (F2/F3); hardest_hole_* from the stats RPC is never read here.
 * Nothing here is about the viewer (V1): no viewer columns, no viewer RPCs.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { formatNumber } from '@/i18n/format';
import { A, FIGS, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { useCourseStatsDetail } from '@/hooks/feed/useCourseStatsDetail';
import { useCourseHoleAnalysis } from '@/hooks/gam/useCourseHoleAnalysis';
import AboutSection from './AboutSection';
import { deriveCourseVerdict, shotsInWords, signed } from './courseVerdict';
import { B, FactTile, Said, SMALL_LABEL } from './verdictBits';

const TRACK = A.TRACK;

/** VERDICT_COPY_1 VC4: at or above this percentile the right end claims "Harder than". */
export const VERDICT_HARDER_CLAIM_MIN = 80;
/** VERDICT_COPY_1 VC4: at or below this percentile the left end claims "Easier than". */
export const VERDICT_EASIER_CLAIM_MAX = 20;

const Fact = FactTile;

const TheVerdict: React.FC<{ courseId: string; courseName: string }> = ({ courseId, courseName }) => {
  const { t } = useTranslation('courses');
  const { data: stats } = useCourseStatsDetail(courseId, true);
  const { data: analysis } = useCourseHoleAnalysis(courseId);

  const avg = stats?.avg_over_par;
  const rounds = Number(stats?.rounds_tracked ?? 0);
  const verdict = React.useMemo(
    () => (analysis && Number(analysis.total_rounds ?? 0) > 0 ? deriveCourseVerdict(analysis.holes) : null),
    [analysis],
  );
  if (avg == null || !Number.isFinite(avg) || rounds <= 0) return null;

  const r = Math.round(avg);
  const title =
    r >= 1
      ? t('courseDetail.verdict.titleOver', { count: r, words: shotsInWords(r), courseName })
      : r <= -1
        ? t('courseDetail.verdict.titleUnder', { courseName })
        : t('courseDetail.verdict.titleLevel', { courseName });

  const harder = stats?.harder_than_pct;
  const pct = harder != null && Number.isFinite(harder) ? Math.max(0, Math.min(100, harder)) : null;
  const parLabel = (p: number) => t('courseDetail.verdict.parType', { par: p });

  return (
    <AboutSection first kicker={t('courseDetail.verdict.kicker')} title={title}>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 13, fontFamily: SANS }}>
        <div style={{ fontSize: 62, fontWeight: 800, letterSpacing: '-0.055em', lineHeight: 0.82, color: A.INK, ...FIGS }}>
          {signed(avg)}
        </div>
        <div style={{ paddingBottom: 5 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: A.BODY }}>{t('courseDetail.verdict.overPar')}</div>
          <div style={{ fontSize: 12, color: A.DIM, marginTop: 3, ...FIGS }}>
            {t('courseDetail.verdict.across', { count: rounds, rounds: formatNumber(rounds) })}
          </div>
        </div>
      </div>

      {pct != null ? (
        <div style={{ marginTop: 15 }} data-testid="verdict-placing">
          <div style={{ position: 'relative', height: 24 }} aria-hidden="true">
            <div style={{ position: 'absolute', left: 0, right: 0, top: 10, height: 4, borderRadius: 2, background: TRACK }} />
            <div style={{ position: 'absolute', left: 0, top: 10, height: 4, width: `${pct}%`, borderRadius: 2, background: A.AMBER, opacity: 0.8 }} />
            <div
              style={{
                position: 'absolute',
                top: 5.5,
                left: `calc(${pct}% - 6.5px)`,
                width: 13,
                height: 13,
                borderRadius: '50%',
                background: A.INK,
              }}
            />
          </div>
          <div style={{ ...SMALL_LABEL, lineHeight: 1, display: 'flex', justifyContent: 'space-between', gap: 12, marginTop: 7 }}>
            {Math.round(pct) <= VERDICT_EASIER_CLAIM_MAX ? (
              <span style={{ color: A.MUTE }}>{t('courseDetail.verdict.easierThan', { pct: 100 - Math.round(pct) })}</span>
            ) : (
              <span>{t('courseDetail.verdict.easiest')}</span>
            )}
            {Math.round(pct) >= VERDICT_HARDER_CLAIM_MIN ? (
              <span style={{ color: A.MUTE }}>{t('courseDetail.verdict.harderThan', { pct: Math.round(pct) })}</span>
            ) : (
              <span>{t('courseDetail.verdict.hardest')}</span>
            )}
          </div>
        </div>
      ) : null}

      {verdict ? (
        <>
          <div style={{ display: 'flex', gap: 10, marginTop: 15 }}>
            <Fact value={String(verdict.hardest.hole_no)} label={t('courseDetail.verdict.hardestHole')} />
            <Fact value={String(verdict.easiest.hole_no)} label={t('courseDetail.verdict.letOff')} />
            {verdict.defender ? (
              <Fact value={parLabel(verdict.defender.par)} label={t('courseDetail.verdict.defends')} />
            ) : null}
          </div>
          <Said>
            <B>{t('courseDetail.verdict.saidHardest', { hole: verdict.hardest.hole_no })}</B>
            {verdict.defender ? (
              <>
                {t('courseDetail.verdict.saidJoin')}
                <B>{t('courseDetail.verdict.saidDefender', { par: verdict.defender.par })}</B>
                {t('courseDetail.verdict.saidEnd')}
              </>
            ) : (
              t('courseDetail.verdict.saidEndOnly')
            )}
          </Said>
        </>
      ) : null}
    </AboutSection>
  );
};

export default TheVerdict;

/**
 * CRM1 — WHAT PEOPLE SAY reads the Reviews tab's source.
 *
 * Every figure comes from the SAME community sample the Reviews tab uses:
 * useCourseReviewSample + reviewsCommunitySample, wired exactly as
 * CourseReviewsTab wires it. The sample EXCLUDES the viewer, whose own score
 * appears separately as the amber YOU pill — so both tabs print the same
 * numbers for the same course. useCourseRatingAggregates and
 * useUserCourseRating are no longer read here.
 *
 * FIGURE BLOCK (CRM1.3/1.4, gated by CRM2.1): the Reviews tab's arrangement —
 * 48px ink score, tier word over the numeral rating count beside it, both ink
 * (no courseSubScoreTone), and the amber YOU pill at the right-hand end when
 * the viewer has rated and a delta exists. The tier word renders only at two
 * or more community ratings (hasCommunityAverage, the same gate the Reviews
 * tab enforces); at one community rating its slot collapses entirely.
 *
 * ERROR (CRM2.2): a failed fetch renders NOTHING, exactly like loading — the
 * "No one's scored yet" invitation may only run on a successful empty fetch.
 *
 * CATEGORY BARS (CRM1.5/1.6, 2×2 grid): the shared CategoryBarGrid renders
 * directly beneath the figure block whenever there are at least two community
 * ratings, at every count above; below two, nothing takes its place. The
 * CategoryScores "pairs" block is removed from this component only.
 *
 * ONLY-RATER STATE (CRM1.7b): when the single rating is the viewer's own,
 * there is no community figure — the section says so and shows the viewer's
 * score in amber instead.
 */
import React, { useMemo } from 'react';
import { useTranslation } from 'react-i18next';

import { useSupabaseSession } from '@/hooks/useSupabaseSession';
import { useCourseReviewSample } from '@/hooks/useCourseReviewSample';
import { reviewsCommunitySample } from '@/lib/reviews/communitySample';
import { fewReviewFacts } from '@/lib/reviews/fewReviews';
import { hasCommunityAverage } from '@/lib/reviews/sampleRules';
import { getRatingTierLabel } from '@/lib/ratingTier';
import { SURFACE } from '@/lib/tokens/surface';
import { inkWithAlpha } from '@/lib/tokens/surfaces';
import { A, SANS, FIGS } from '@/features/courses/components/holes/analytical/tokens';
import { CategoryBarGrid } from '@/components/shared/CategoryBarGrid';
import AboutSection, { AboutHairline } from './AboutSection';
import { shotsInWords } from './courseVerdict';

interface WhatPeopleSayProps {
  courseId: string;
  courseName: string;
  onRateClick: () => void;
  /** Opens the Reviews tab, where the same community figures live beside reviews. */
  onSeeAllReviews?: () => void;
}

const WhatPeopleSay: React.FC<WhatPeopleSayProps> = ({
  courseId,
  courseName,
  onRateClick,
  onSeeAllReviews,
}) => {
  const { t } = useTranslation('courses');
  const { user } = useSupabaseSession();
  const { data: sampleRows, isLoading, isError } = useCourseReviewSample(courseId, user?.id);
  const community = useMemo(() => reviewsCommunitySample(sampleRows ?? [], user?.id), [sampleRows, user?.id]);

  const heading = t('courseDetail.sections.whatPeopleSay');
  const total = community.totalRatingCount;
  const count = community.ratingCount;
  const score = community.score;
  const yours = community.viewerScore;

  const rateAction = (
    <button
      type="button"
      onClick={onRateClick}
      style={{
        display: 'inline-block',
        marginTop: 14,
        background: 'rgba(255,255,255,0.06)',
        border: `1px solid ${A.BORDER}`,
        borderRadius: 11,
        padding: '8px 14px',
        cursor: 'pointer',
        fontFamily: SANS,
        fontSize: 13,
        fontWeight: 700,
        color: A.INK,
        textAlign: 'left',
      }}
    >
      {yours != null ? t('courseDetail.place.editRating') : t('courseDetail.communityScore.rateThis')}
    </button>
  );

  const seeAll = onSeeAllReviews ? (
    <>
      <AboutHairline style={{ marginTop: 18 }} />
      <button
        type="button"
        onClick={onSeeAllReviews}
        style={{
          display: 'block',
          width: '100%',
          textAlign: 'left',
          background: 'transparent',
          border: 0,
          padding: '14px 0 0',
          cursor: 'pointer',
          fontFamily: SANS,
        }}
      >
        <span style={{ display: 'block', fontSize: 13, fontWeight: 600, color: A.INK }}>
          {t('courseDetail.communityScore.seeAllReviews')} ›
        </span>
        <span style={{ display: 'block', marginTop: 5, fontSize: 11, lineHeight: 1.5, color: A.DIM }}>
          {t('courseDetail.rating.allReviewsSub')}
        </span>
      </button>
    </>
  ) : null;

  // The sample is in flight: 0 would state something untrue.
  if (isLoading) return null;

  // CRM2.2 — an error is not an absence: a failed fetch renders nothing, so
  // the "No one's scored yet" invitation below can only mean a genuinely
  // empty, successfully fetched sample.
  if (isError) return null;

  // NOBODY HAS SCORED IT — a sentence and an invitation, not a card. (CRM1.8: untouched.)
  if (total === 0) {
    return (
      <AboutSection heading={heading}>
        <p style={{ margin: 0, fontSize: 13, lineHeight: 1.55, fontWeight: 600, color: A.MUTE, fontFamily: SANS }}>
          {t('courseDetail.communityScore.noOneRated', { courseName })}
        </p>
        {rateAction}
      </AboutSection>
    );
  }

  /* CRM1.7b — THE ONLY RATING IS THE VIEWER'S. The community count is zero and
     there is no community score, so nothing community-flavoured prints: no
     figure, no tier word, no bands, no YOU pill. */
  if (total === 1 && yours != null) {
    return (
      <AboutSection kicker={t('courseDetail.reviewsHead.kicker')} title={t('courseDetail.reviewsHead.youFirst')}>
        <p style={{ margin: '14px 0 0', fontSize: 12.5, lineHeight: 1.55, color: SURFACE.dark.body, fontFamily: SANS }}>
          {t('courseDetail.reviewsHead.youFirstBody', { score: yours.toFixed(1) })}
        </p>
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 13, marginTop: 15 }}>
          <strong style={{ color: A.INK, fontSize: 48, lineHeight: 0.9, fontWeight: 800, ...FIGS }}>{yours.toFixed(1)}</strong>
          <div style={{ minWidth: 0 }}>
            <div style={{ color: SURFACE.dark.ink, fontSize: 13, fontWeight: 700, lineHeight: 1.2 }}>Yours</div>
            <div style={{ color: SURFACE.dark.dim, fontSize: 11.5, lineHeight: 1.45, marginTop: 2, ...FIGS }}>1 rating</div>
          </div>
        </div>
        {rateAction}
        {seeAll}
      </AboutSection>
    );
  }

  /* CRM1.2 — the unchanged headline key, now fed the viewer-excluding pair:
     nine ratings of which one is the viewer's reads "9.3 from eight golfers". */
  const title = t('courseDetail.reviewsHead.title', {
    count,
    score: (score ?? 0).toFixed(1),
    golfers: shotsInWords(count),
  });

  const facts = fewReviewFacts(community);
  const ratedViewer = yours != null;

  return (
    <AboutSection kicker={t('courseDetail.reviewsHead.kicker')} title={title}>
      {/* CRM1.3/1.4 — the Reviews tab's figure row: ink score, tier over count, YOU pill at the end. */}
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 12, marginTop: 15 }}>
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 13, minWidth: 0 }}>
          <strong data-community-score style={{ color: SURFACE.dark.ink, fontSize: 48, lineHeight: 0.9, fontWeight: 800, ...FIGS }}>{score?.toFixed(1)}</strong>
          <div style={{ minWidth: 0 }}>
            {/* CRM2.1 — the tier word needs two community ratings; below that its slot collapses. */}
            {hasCommunityAverage(count) && <div style={{ color: SURFACE.dark.ink, fontSize: 13, fontWeight: 700, lineHeight: 1.2 }}>{getRatingTierLabel(score)}</div>}
            <div data-community-rater-count={count} style={{ color: SURFACE.dark.dim, fontSize: 11.5, lineHeight: 1.45, marginTop: 2, overflowWrap: 'anywhere', ...FIGS }}>{count} {count === 1 ? 'rating' : 'ratings'}</div>
          </div>
        </div>
        {ratedViewer && community.delta != null && <div data-viewer-delta style={{ display: 'inline-flex', alignItems: 'baseline', gap: 6, padding: '5px 10px', whiteSpace: 'nowrap', flex: '0 0 auto', borderRadius: 999, border: `1px solid ${inkWithAlpha(A.AMBER, 0.35)}`, background: inkWithAlpha(A.AMBER, 0.07) }}><span style={{ color: SURFACE.dark.mute, fontSize: 10, fontWeight: 700, textTransform: 'uppercase' }}>You</span><b style={{ color: A.INK, fontSize: 14, ...FIGS }}>{yours?.toFixed(1)}</b><span style={{ color: A.INK, fontSize: 10, fontWeight: 800, ...FIGS }}>{community.delta > 0 ? '▲' : community.delta < 0 ? '▼' : ''} {Math.abs(community.delta).toFixed(1)}</span></div>}
      </div>

      {/* CRM1.6 — the shared 2×2 category bars, no kicker, heading or prose; two community ratings and up. */}
      {facts && facts.bands.length > 0 && (
        <div style={{ marginTop: 16 }}>
          <CategoryBarGrid items={facts.bands.map(b => ({ key: b.key, label: b.label, value: b.mean }))} />
        </div>
      )}

      {rateAction}

      {seeAll}
    </AboutSection>
  );
};

export default WhatPeopleSay;

/** BRIEF_COURSE_TAB_1A — shared pieces for the verdict and defends-par sections. */
import React from 'react';
import { A, FIGS, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { inkWithAlpha } from '@/lib/tokens/surfaces';
import { SURFACE } from '@/lib/tokens/surface';

export const TILE_FILL = inkWithAlpha(SURFACE.dark.ink, 0.05);
export const BAR_NEUTRAL = inkWithAlpha(SURFACE.dark.ink, 0.28);
export const PAR_FILL = inkWithAlpha(SURFACE.dark.ink, 0.4);

export const SMALL_LABEL: React.CSSProperties = {
  fontSize: 9,
  fontWeight: 700,
  letterSpacing: '0.1em',
  textTransform: 'uppercase',
  color: A.DIM,
  fontFamily: SANS,
  lineHeight: 1.3,
};

/** A figure tile: value over SMALL_LABEL on TILE_FILL. Shared by TheVerdict and
 * the Tees selected-set strip (TEE_SELECTED_STRIP_1) so the two cannot drift. */
export const FactTile: React.FC<{ value: string; label: string }> = ({ value, label }) => (
  <div style={{ flex: 1, minWidth: 0, background: TILE_FILL, borderRadius: 10, padding: '10px 9px' }}>
    <div style={{ fontSize: 18, fontWeight: 800, letterSpacing: '-0.03em', color: A.INK, ...FIGS }}>{value}</div>
    <div style={{ ...SMALL_LABEL, marginTop: 4 }}>{label}</div>
  </div>
);

/** The derived observation line: rule on the left, bold for the findings. */
export const Said: React.FC<{ quiet?: boolean; children: React.ReactNode }> = ({ quiet, children }) => (
  <p
    style={{
      margin: '14px 0 0',
      fontSize: 12.5,
      lineHeight: 1.55,
      color: quiet ? A.MUTE : A.BODY,
      borderLeft: `2px solid ${quiet ? A.HAIRLINE : A.AMBER}`,
      paddingLeft: 11,
      fontFamily: SANS,
      ...FIGS,
    }}
  >
    {children}
  </p>
);

export const B: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <b style={{ color: A.INK, fontWeight: 700 }}>{children}</b>
);

