import { InlineProMemberName } from '@/features/pro-verification/InlineProMemberName';
/** REVIEWS_STATE_3/4: total selects this shared screen; complete excluding community
 * owns every aggregate figure. The existing course circle means
 * outgoing follows; it marks only already-visible, blocked-filtered prose rows.
 * State 2's row/context and panel are reused, never a second review row.
 * All sections are unframed and page-scrolled; missing identities stay unnamed.
 * State 4 adds the existing distribution at the shared excluding threshold.
 * REVIEWS_HEADER_1 owns the shared figure row and fixed category heading.
 * Tier/count share one stack wherever this screen already shows an average;
 * the below-five tier prohibition was deliberately reversed by RH11.
 * Reviews States 3/4 share FewReviews and RatingTierDistribution to prevent population drift. */
import React from 'react';
import type { CourseReview } from '@/hooks/useCourseReviews';
import { useMembersWhoPlayedCourse } from '@/hooks/useMembersWhoPlayedCourse';
import { hasCommunityAverage, hasRatingDistribution, isFewReviews, isFiveToNineReviews } from '@/lib/reviews/sampleRules';
import { RatingTierDistribution } from '@/components/courses/review/RatingTierDistribution';
import { getRatingTier, getRatingTierLabel } from '@/lib/ratingTier';
import { capitalizedRatings, fewReviewFacts, partitionKnownReviews, type ReviewsCommunity } from '@/lib/reviews/fewReviews';
import { SURFACE } from '@/lib/tokens/surface';
import { inkWithAlpha } from '@/lib/tokens/surfaces';
import { MEDAL_GOLD } from '@/lib/tokens/medals';
import { A, FIGS } from '@/features/courses/components/holes/analytical/tokens';
import { Button } from '@/components/ui/button';
import { GUTTER, VERDICT_KICKER, TAB_TITLE } from '../about/AboutSection';
import { CategoryBarGrid } from '@/components/shared/CategoryBarGrid';
import { RaterReviewRow } from './SingleReview';

interface FewReviewsProps {
  community: ReviewsCommunity;
  reviews: CourseReview[];
  viewerId?: string;
  courseId: string;
  courseName: string;
  highlightedReviewId?: string | null;
  onMediaClick: (review: CourseReview, index: number, el: HTMLElement | null) => void;
  ownReview: React.ReactNode;
  afterReview?: (review: CourseReview) => React.ReactNode;
  onWrite: () => void;
}
const section: React.CSSProperties = { padding: `20px ${GUTTER}px`, borderBottom: `1px solid ${inkWithAlpha(SURFACE.dark.ink, 0.06)}` };
const kicker = VERDICT_KICKER;
const heading = TAB_TITLE;
const prose: React.CSSProperties = { color: SURFACE.dark.body, fontSize: 12.5, lineHeight: 1.55, margin: '14px 0 0' };

export function FewReviews({ community, reviews, viewerId, courseId, courseName, highlightedReviewId, onMediaClick, ownReview, afterReview, onWrite }: FewReviewsProps) {
  const { data: members } = useMembersWhoPlayedCourse(viewerId ? courseId : undefined, viewerId);
  const stateFour = isFiveToNineReviews(community.totalRatingCount);
  if (!isFewReviews(community.totalRatingCount) && !stateFour) return null;
  const showDistribution = stateFour && hasRatingDistribution(community.ratingCount);
  const ids = new Set(community.communityRows.map(row => row.id));
  const visible = reviews.filter(review => ids.has(review.id));
  const { known, others } = partitionKnownReviews(visible, new Set(members?.members.filter(member => member.in_circle).map(member => member.user_id) ?? []));
  const facts = fewReviewFacts(community);
  const ratedViewer = community.viewerScore != null;
  const renderPerson = (review: CourseReview, flat: boolean) => <React.Fragment key={review.id}><RaterReviewRow review={review} flat={flat} isHighlighted={review.id === highlightedReviewId} onMediaClick={(index, el) => onMediaClick(review, index, el)} />{afterReview?.(review)}</React.Fragment>;
  const identities = community.communityRows.map(row => {
    const review = visible.find(review => review.id === row.id);
    const profile = review?.user_profiles;
    const fullName = profile?.display_name?.trim() || profile?.username?.trim();
    return { name: fullName?.split(/\s+/)[0], userId: review?.user_id, rating: row.rating };
  });
  return <div data-reviews-state={stateFour ? 'five-to-nine' : 'few'} data-community-count={facts?.count} data-community-spread={facts?.spread}>
    <section style={{ ...section, paddingTop: 0 }}>
      <div style={kicker}>{capitalizedRatings(community.totalRatingCount)} golfers have rated it</div>
      {facts ? <>
        <h2 data-community-headline style={heading}>{courseName} sits at {community.score?.toFixed(1)}</h2>
        <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 12, marginTop: 15 }}>
          <div style={{ display: 'flex', alignItems: 'flex-end', gap: 13, minWidth: 0 }}>
          <strong data-community-score style={{ color: SURFACE.dark.ink, fontSize: 48, lineHeight: 0.9, fontWeight: 800, ...FIGS }}>{community.score?.toFixed(1)}</strong>
          <div style={{ minWidth: 0 }}>
              <div style={{ color: SURFACE.dark.ink, fontSize: 13, fontWeight: 700, lineHeight: 1.2 }}>{getRatingTierLabel(community.score)}</div>
              <div data-community-rater-count={facts.count} style={{ color: SURFACE.dark.dim, fontSize: 11.5, lineHeight: 1.45, marginTop: 2, overflowWrap: 'anywhere', ...FIGS }}>{facts.count} {facts.count === 1 ? 'rating' : 'ratings'}</div>
          </div>
          </div>
          {ratedViewer && community.delta != null && <div data-viewer-delta style={{ display: 'inline-flex', alignItems: 'baseline', gap: 6, padding: '5px 10px', whiteSpace: 'nowrap', flex: '0 0 auto', borderRadius: 999, border: `1px solid ${inkWithAlpha(A.AMBER, 0.35)}`, background: inkWithAlpha(A.AMBER, 0.07) }}><span style={{ color: SURFACE.dark.mute, fontSize: 10, fontWeight: 700, textTransform: 'uppercase' }}>You</span><b style={{ color: A.AMBER, fontSize: 14, ...FIGS }}>{community.viewerScore?.toFixed(1)}</b><span style={{ color: A.IMPROVED, fontSize: 10, fontWeight: 800, ...FIGS }}>{community.delta > 0 ? '▲' : community.delta < 0 ? '▼' : ''} {Math.abs(community.delta).toFixed(1)}</span></div>}
        </div>
        {!stateFour && <div style={{ color: SURFACE.dark.dim, fontSize: 11.5, lineHeight: 1.45, marginTop: 11, overflowWrap: 'anywhere', ...FIGS }}>
          {identities.every(person => person.name) && <>{new Intl.ListFormat('en-GB').formatToParts(identities.map(person => person.name ?? '')).map((part, index, parts) => part.type === 'element' ? <InlineProMemberName key={index} userId={identities[parts.slice(0, index).filter(previous => previous.type === 'element').length]?.userId}>{part.value}</InlineProMemberName> : part.value)} · </>}
          <span data-individual-scores>{new Intl.ListFormat('en-GB').format(identities.map(person => person.rating?.toFixed(1) ?? ''))}</span>
        </div>}
        {showDistribution ? <div style={{ marginTop: 15 }}>
          <RatingTierDistribution distribution={community.distribution} activeTier={getRatingTier(community.score)} appearance="sample" />
        </div> : null}
      </> : <>
        <h2 style={heading}>The score builds from here</h2>
        <p style={prose}>Here they are — the golfers, and what they said.</p>
        {visible.map(review => renderPerson(review, false))}
      </>}
    </section>
    {hasCommunityAverage(community.ratingCount) && facts && facts.bands.length > 0 && <section style={section}>
      <div style={kicker}>What they scored</div>
      <h2 style={heading}>Where the score comes from</h2>
      <div style={{ marginTop: 16 }}>
        <CategoryBarGrid items={facts.bands.map(b => ({ key: b.key, label: b.label, value: b.mean }))} />
      </div>
    </section>}
    {facts && known.length > 0 && <section style={section}><span style={{ display: 'inline-block', color: MEDAL_GOLD, background: inkWithAlpha(MEDAL_GOLD, 0.10), border: `1px solid ${inkWithAlpha(MEDAL_GOLD, 0.28)}`, borderRadius: 999, padding: '3px 9px', fontSize: 10, fontWeight: 800, textTransform: 'uppercase', marginBottom: 11 }}>People you know</span>{known.map(review => renderPerson(review, true))}</section>}
    {facts && others.length > 0 && <section style={section}><div style={kicker}>Everyone else</div>{others.map(review => renderPerson(review, true))}</section>}
    {ownReview}
    {!ratedViewer && <section style={section}><Button variant="ghost" onClick={onWrite}>Add yours</Button></section>}
  </div>;
}

// Architecture note (moved from AGENTS.md): Small-sample Reviews reuse SingleReview's RaterReviewRow, so context and media cannot drift.
import { InlineProMemberName } from '@/features/pro-verification/InlineProMemberName';
/** REVIEWS_STATE_2 signed-off person-led exception to the flat multi-review row.
 * A review owns its overall score; calibration refers to that same source.
 * REVIEWS_FIRST_RATING_1: shows the Course tab aggregate with its count beside it
 * (courseRatingFloor display rule); still no bars, distribution or categories.
 * playedMonth is a review-owned input only: current stored reviews omit it.
 * This component owns its gutter; the existing tab owns the top seam.
 * Rater-context reads are isolated to person rows, never used as community data.
 * Reviews state-local rater context stays isolated from communitySample; module headers own each state contract to prevent context from becoming aggregate data. */
import React from 'react';
import { Button } from '@/components/ui/button';
import { SquircleAvatar } from '@/components/ui/SquircleAvatar';
import { MentionText } from '@/components/mentions/MentionText';
import { ReviewMediaStrip } from '@/components/courses/review/ReviewMediaStrip';
import type { CourseReview } from '@/hooks/useCourseReviews';
import { useSingleReviewContext } from '@/hooks/useSingleReviewContext';
import { calibrationFacts, isSingleReview, reviewPlayedMonth, type RaterContext } from '@/lib/reviews/singleReview';
import { SURFACE } from '@/lib/tokens/surface';
import { MEMBER_PANEL, INK_ON_LIGHT, inkWithAlpha } from '@/lib/tokens/surfaces';
import { SC_BOGEY_DARK } from '@/features/courses/components/holes/_constants';
import { A, SANS, FIGS } from '@/features/courses/components/holes/analytical/tokens';
import { GUTTER, VERDICT_KICKER, TAB_TITLE } from '../about/AboutSection';
import { CategoryLine } from './reviewFlatBits';

interface SingleReviewProps {
  totalRatings: number;
  review?: CourseReview;
  isHighlighted?: boolean;
  /** Only the review's own known played month; no derived date is accepted. */
  playedMonth?: number | null;
  context?: RaterContext | null;
  onMediaClick: (index: number, el: HTMLElement | null) => void;
  onAddYours: () => void;
  /** RF3R: Course tab aggregate (course_rating_aggregates); shown with its count beside it. */
  communityScore?: number | null;
  communityCount?: number | null;
  /** RF5: the single rating is the viewer's own. */
  isViewerOwn?: boolean;
  courseName?: string;
}

export function SingleReview({ totalRatings, review, isHighlighted, playedMonth, context, onMediaClick, onAddYours, communityScore = null, communityCount = null, isViewerOwn = false, courseName = '' }: SingleReviewProps) {
  const { data: fetchedContext } = useSingleReviewContext(context === undefined ? review?.user_id : undefined, review?.course_id ?? '');
  if (!isSingleReview(totalRatings)) return null;
  const facts = context === undefined ? fetchedContext : context;
  const calibration = review ? calibrationFacts(review, facts) : null;
  const gender = facts?.gender?.toLowerCase();
  const subject = gender === 'male' ? 'He' : gender === 'female' ? 'She' : 'They';
  const verb = subject === 'They' ? 'have' : 'has';
  const person = subject === 'He' ? 'a man' : subject === 'She' ? 'a woman' : 'someone';
  // RF6: first word of the same resolved name the rater row shows; pronoun from the calibration source.
  const object = subject === 'He' ? 'him' : subject === 'She' ? 'her' : 'them';
  const resolvedName = review?.user_profiles?.display_name || review?.user_profiles?.username || null;
  const firstName = resolvedName?.trim().split(/\s+/)[0] || null;
  const lede = isViewerOwn
    ? 'You got here first. Every golfer who rates it from now moves the number with you.'
    : firstName
      ? `${firstName} got here first. Every golfer who rates it from now moves the number with ${object}.`
      : `A golfer got here first. Every golfer who rates it from now moves the number with ${object}.`;
  return <section data-reviews-state="one" aria-labelledby="reviews-one-title" style={{ padding: `0 ${GUTTER}px 20px`, fontFamily: SANS }}>
    <div style={VERDICT_KICKER}>The first rating</div>
    <h2 id="reviews-one-title" style={TAB_TITLE}>{courseName} is on the board</h2>
    {communityScore != null && communityCount != null && <div style={{ display: 'flex', alignItems: 'flex-end', gap: 11, marginTop: 15 }}>
      <div data-community-score style={{ fontSize: 48, fontWeight: 800, letterSpacing: '-0.035em', lineHeight: 0.9, color: A.INK, ...FIGS }}>{Number(communityScore).toFixed(1)}</div>
      <div style={{ paddingBottom: 5 }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: A.INK, lineHeight: 1.2 }}>The community score</div>
        <div style={{ fontSize: 11.5, color: A.DIM, lineHeight: 1.45, marginTop: 2, ...FIGS }}>{communityCount} {communityCount === 1 ? 'rating' : 'ratings'}</div>
      </div>
    </div>}
    <p style={{ color: SURFACE.dark.mute, fontSize: 12.5, lineHeight: 1.5, margin: '8px 0 0' }}>{firstName && !isViewerOwn ? <><InlineProMemberName userId={review?.user_id}>{firstName}</InlineProMemberName>{lede.slice(firstName.length)}</> : isViewerOwn ? <><InlineProMemberName userId={review?.user_id}>You</InlineProMemberName>{lede.slice(3)}</> : lede}</p>
    {review && <RaterReviewRow review={review} isHighlighted={isHighlighted} context={facts} playedMonth={playedMonth} onMediaClick={onMediaClick} />}
    {calibration && <p data-review-calibration style={{ borderLeft: `2px solid ${A.AMBER}`, paddingLeft: 11, color: SURFACE.dark.body, fontSize: 13, lineHeight: 1.5, margin: '14px 0 0' }}>
      {calibration.everyCategory && <>{subject} gave it <b style={{ color: SURFACE.dark.ink, ...FIGS }}>{review?.rating?.toFixed(1)}</b> on every category. </>}
      <b style={{ color: SURFACE.dark.ink, fontWeight: 700, ...FIGS }}>{subject} {verb} rated {calibration.coursesRated} courses and given {calibration.perfectTens} of them a ten</b> — so this is not {person} who hands them out.
    </p>}
    <p data-first-rating-close style={{ borderLeft: `2px solid ${A.AMBER}`, paddingLeft: 11, color: SURFACE.dark.mute, fontSize: 13, lineHeight: 1.5, margin: '14px 0 0' }}>{isViewerOwn
      ? <>The next golfer to rate it makes <b style={{ color: A.INK, fontWeight: 700 }}>the score an average of two</b>.</>
      : <>Add yours and <b style={{ color: A.INK, fontWeight: 700 }}>the score becomes an average of two</b>.</>}</p>
    <Button variant="ghost" onClick={onAddYours} style={{ background: SURFACE.dark.ink, color: INK_ON_LIGHT, borderRadius: 999, marginTop: 15, height: 'auto', minHeight: 42, padding: '11px 22px', fontSize: 14, fontWeight: 700, lineHeight: 1.4 }}>{isViewerOwn ? 'Edit yours' : 'Add yours'}</Button>
  </section>;
}
/** Existing State 2 person row shared with State 3; context never feeds aggregates. */
export function RaterReviewRow({ review, context, playedMonth, onMediaClick, flat = false, isHighlighted = false }: {
  review: CourseReview; context?: RaterContext | null; playedMonth?: number | null;
  isHighlighted?: boolean;
  onMediaClick: (index: number, el: HTMLElement | null) => void; flat?: boolean;
}) {
  const { data: fetchedContext } = useSingleReviewContext(context === undefined ? review.user_id : undefined, review.course_id);
  const facts = context === undefined ? fetchedContext : context;
  const month = reviewPlayedMonth(playedMonth);
  const name = review.user_profiles?.display_name || review.user_profiles?.username || 'Anonymous';
  const contextItems: React.ReactNode[] = [];
  if (facts?.handicap != null) contextItems.push(`${facts.handicap} handicap`);
  if (facts?.roundsHere != null && facts.roundsHere > 0) contextItems.push(<em key="played" data-tracked-play style={{ color: A.IMPROVED, fontStyle: 'normal', fontWeight: 700 }}>Played here {facts.roundsHere === 1 ? 'once' : facts.roundsHere === 2 ? 'twice' : `${facts.roundsHere} times`}</em>);
  if (facts?.coursesRated != null) contextItems.push(`${facts.coursesRated} courses rated`);
  return (
    <article data-testid="review-row" data-review-id={review.id} className={isHighlighted ? 'animate-soft-pulse' : undefined} style={flat ? { padding: '14px 0', borderBottom: `1px solid ${inkWithAlpha(SURFACE.dark.ink, 0.06)}` } : { marginTop: 15, background: MEMBER_PANEL, border: `1px solid ${inkWithAlpha(SURFACE.dark.ink, 0.07)}`, borderRadius: 13, padding: 15 }}>
      <div data-rater-row style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>
        <SquircleAvatar src={review.user_profiles?.profile_photo_url} alt={name} userId={review.user_id} size={34} hairlineRing />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ color: SURFACE.dark.ink, fontSize: 14, fontWeight: 700, overflowWrap: 'anywhere', lineHeight: 1.2 }}><InlineProMemberName userId={review.user_id}>{name}</InlineProMemberName></div>
          {contextItems.length > 0 && <div data-rater-context style={{ color: SURFACE.dark.dim, fontSize: 11, lineHeight: 1.45, marginTop: 3, ...FIGS }}>
            {contextItems.map((item, index) => <React.Fragment key={index}>{index > 0 && ' · '}{item}</React.Fragment>)}
          </div>}
        </div>
      </div>
      <CategoryLine review={review} />
      {review.review?.trim() && <MentionText as="p" text={review.review} style={{ color: SURFACE.dark.body, fontSize: 13, lineHeight: 1.5, margin: '10px 0 0', overflowWrap: 'anywhere' }} />}
      {month && <span data-played-season style={{ display: 'inline-block', marginTop: 9, padding: '3px 9px', borderRadius: 999, color: SC_BOGEY_DARK, background: inkWithAlpha(SC_BOGEY_DARK, 0.10), border: `1px solid ${inkWithAlpha(SC_BOGEY_DARK, 0.22)}`, fontSize: 10, fontWeight: 800, letterSpacing: '0.09em', textTransform: 'uppercase' }}>Played {month}</span>}
      {!!review.media?.length && <div style={{ marginTop: 11 }}><ReviewMediaStrip media={review.media} onMediaClick={onMediaClick} tileMode="equal" tileHeight={72} tileRadius={9} tileGap={4} maxItems={4} /></div>}
    </article>
  );
}

/**
 * BRIEF_REVIEWS_HEADER_PAIR_AND_DISTRIBUTION — THE SCORE. No heading, directly
 * under the tab strip.
 *
 * COMMUNITY AND YOU, RULED. Left: the community score. Right (only when the
 * viewer has rated): the viewer's score in amber and its signed difference
 * from the community EXCLUDING the viewer (REVIEWS_SAMPLE_1), in DELTA_TONE.
 * No other raters means no community figure or comparison, never a fake zero.
 * Inside |delta| < 0.05 it reads "Level"
 * with a muted dash (same dead zone as HcpTrendChart). With no viewer rating
 * the right column and rule do not render and the left column does not move.
 *
 * THE FIVE-BAND HISTOGRAM IS RESTORED beneath the pair. With nine ratings as
 * the maximum on any course most bands are sparse or empty; that emptiness is
 * accepted as the honest picture. Empty bands render, never hide.
 *
 * THE "/10" IS DROPPED. The tier word already fixes the scale.
 */
import React from 'react';
import { A, SANS, FIGS, courseSubScoreTone } from '@/features/courses/components/holes/analytical/tokens';
import { getRatingTierLabel } from '@/lib/ratingTier';
import { DELTA_TONE } from '@/lib/tokens/indexDelta';
import { GUTTER } from '../about/AboutSection';
import {
  RatingTierDistribution,
  type RatingTierDistributionData,
} from '@/components/courses/review/RatingTierDistribution';

interface TheScoreProps {
  score: number | null;
  ratingCount: number;
  /** The viewer's own overall rating, or null when they have not rated. */
  viewerScore?: number | null;
  /** Five-band counts; omitted when they cannot be shown to agree with ratingCount. */
  distribution?: RatingTierDistributionData | null;
  /** Render this same markup with text swapped for skeleton bars. Height matches
   *  the resolved state by construction: each bar is the placeholder text itself,
   *  transparent, in the real line's own type. */
  loading?: boolean;
}

const ZERO: RatingTierDistributionData = { exceptional: 0, excellent: 0, good: 0, fair: 0, poor: 0 };

/** Inline skeleton occupying exactly the line box of `children` in the parent's type. */
const Bar: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <span aria-hidden className="rounded-sq-sm bg-surface-alt clb-shimmer-dark" style={{ color: 'transparent' }}>
    {children}
  </span>
);

const EYEBROW: React.CSSProperties = {
  fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', lineHeight: 1,
};
const FIGURE: React.CSSProperties = {
  ...FIGS, fontSize: 28, fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1, marginTop: 8,
};
const SUPPORT: React.CSSProperties = { fontSize: 11.5, color: A.MUTE, marginTop: 6, lineHeight: 1.3 };

const Triangle: React.FC<{ up: boolean }> = ({ up }) => (
  <span
    aria-hidden
    style={{
      display: 'inline-block', width: 0, height: 0,
      borderLeft: '4px solid transparent', borderRight: '4px solid transparent',
      ...(up ? { borderBottom: '6px solid currentColor' } : { borderTop: '6px solid currentColor' }),
    }}
  />
);

const DeltaLine: React.FC<{ delta: number }> = ({ delta }) => {
  if (Math.abs(delta) < 0.05) {
    return (
      <div style={{ ...SUPPORT, display: 'flex', alignItems: 'center', gap: 6 }}>
        <span aria-hidden style={{ display: 'inline-block', width: 8, height: 1.5, background: A.MUTE }} />
        Level
      </div>
    );
  }
  const up = delta > 0;
  return (
    <div style={{ ...SUPPORT, display: 'flex', alignItems: 'center', gap: 5 }}>
      <span style={{ ...FIGS, display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 12, fontWeight: 700, color: up ? DELTA_TONE.dark.up : DELTA_TONE.dark.down }}>
        <Triangle up={up} />
        {Math.abs(delta).toFixed(1)}
      </span>
      {up ? 'above' : 'below'}
    </div>
  );
};

export const TheScore: React.FC<TheScoreProps> = ({ score, ratingCount, viewerScore, distribution, loading }) => {
  const hasYou = !loading && viewerScore != null;
  const dist = loading ? ZERO : distribution;
  return (
    <section style={{ padding: `0 ${GUTTER}px`, fontFamily: SANS }} aria-busy={loading || undefined}>
      <div style={{ display: 'flex', alignItems: 'stretch' }}>
        {(loading || score != null) && <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ ...EYEBROW, color: A.DIM }}>Community</div>
          <div style={{ ...FIGURE, color: courseSubScoreTone(score) }}>{loading ? <Bar>0.0</Bar> : score?.toFixed(1)}</div>
          <div style={SUPPORT}>
            {loading ? <Bar>0 ratings · Excellent</Bar> : (
              <>
                {ratingCount} {ratingCount === 1 ? 'rating' : 'ratings'}
                {` · ${getRatingTierLabel(score)}`}
              </>
            )}
          </div>
        </div>}
        {hasYou && (
          <>
            {score != null && <div aria-hidden style={{ width: 1, background: A.HAIRLINE, margin: '0 20px' }} />}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ ...EYEBROW, color: A.AMBER }}>You</div>
              <div style={{ ...FIGURE, color: A.AMBER }}>{viewerScore?.toFixed(1)}</div>
              {score != null && viewerScore != null && <DeltaLine delta={Math.round((viewerScore - score) * 10) / 10} />}
            </div>
          </>
        )}
      </div>
      {dist && (loading || ratingCount > 0) && (
        <div style={{ marginTop: 20 }}>
          <RatingTierDistribution distribution={dist} />
        </div>
      )}
    </section>
  );
};

export default TheScore;

src/components/courses/course-detail/you:
/**
 * YOU_TAB_BOARD_LIST_1 AC4 — THE one board list for the You tab's states 1, 2
 * and 3. YOU_TAB_BOARD_LIST_2 AD1 — OPEN BOARDS ONLY: no held row, not even
 * the course record (the hero already carries it; held boards live behind
 * ALL BOARDS and on Champions). Every open all-time board in "Open" medal
 * gold. AD2 — callers take their count from openBoardCategories, so the
 * heading and the rows cannot drift. The open set is the SAME holder map, over the SAME
 * order, that useCourseRecordSummary.unclaimedCount counts, so the open rows
 * always equal the count (AC1). Do not fork this per branch.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { A, FIGS, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { MEDAL_GOLD } from '@/lib/tokens/medals';
import type { CourseLegendRow, LegendCategory } from '@/lib/gam/types';
import { CHAMPIONS_ORDER_ALL_TIME } from '@/components/profile/handicap/whs/sections/course-legends/_shared/championsOrder';

/** Board names from the state-1 vocabulary (courseDetail.youTab.unclaimed.boards). */
export const BOARD_KEY: Record<string, string> = {
  lowest_gross_all_time: 'lowestGross',
  lowest_net_all_time: 'lowestNet',
  best_stableford_all_time: 'bestStableford',
  most_aces_all_time: 'mostAces',
  most_albatrosses_all_time: 'mostAlbatrosses',
  most_eagles_all_time: 'mostEagles',
  most_birdies_all_time: 'mostBirdies',
  most_rounds_all_time: 'mostRounds',
  best_score_diff_all_time: 'bestDifferential',
};

/** The open boards: identical predicate to unclaimedCount. */
export function openBoardCategories(holders: Map<LegendCategory, CourseLegendRow>): LegendCategory[] {
  return CHAMPIONS_ORDER_ALL_TIME.filter((c) => !holders.has(c));
}

interface Props {
  holders: Map<LegendCategory, CourseLegendRow>;
  marginTop?: number;
}

export const BoardList: React.FC<Props> = ({ holders, marginTop = 14 }) => {
  const { t } = useTranslation('courses');
  const rows: { key: string; label: string; held: boolean }[] = [];
  openBoardCategories(holders).forEach((c) =>
    rows.push({ key: c, label: t(`courseDetail.youTab.unclaimed.boards.${BOARD_KEY[c] ?? c}`), held: false }),
  );
  return (
    <div style={{ marginTop }}>
      {rows.map((r, i) => (
        <div
          key={r.key}
          data-board-row={r.held ? 'held' : 'open'}
          style={{
            display: 'flex', alignItems: 'center', gap: 11, padding: '11px 0',
            borderBottom: i < rows.length - 1 ? `1px solid ${A.SOFT}` : undefined, fontFamily: SANS,
          }}
        >
          <div style={{ flex: 1, fontSize: 13, fontWeight: 600, color: A.BODY, ...FIGS }}>{r.label}</div>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase', color: r.held ? A.DIM : MEDAL_GOLD }}>
            {r.held ? t('courseDetail.youTab.grabs.heldTag') : t('courseDetail.youTab.unclaimed.open')}
          </div>
        </div>
      ))}
    </div>
  );
};

/**
 * YOU_TAB_STATE_AUDIT_1 W3 — ZERO TRACKED ROUNDS, one framing for both
 * branches. Kicker, title, lede, the open-board count tile, and — per
 * YOU_TAB_STATE_1 X2, drawn to state-1-no-handicap-course-empty.html — the
 * four boards a single round claims outright, each against "Open" in medal
 * gold, then the ALL BOARDS link. On state 1 this section ABSORBS Up for
 * grabs (X1): the count and the link live here and Up for grabs does not
 * separately render. On courses WITH rounds Up for grabs is unchanged.
 *
 * W4 — the other two tiles ("What you would face", "your course handicap
 * here") are NOT built: they need CR, slope and par, which a course with no
 * tracked rounds does not have, and no value is ever substituted or
 * defaulted.
 *
 * X6 — if the open-board count is unavailable the tile does not render;
 * never a zero, never a dash.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { A, FIGS, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { MEDAL_GOLD } from '@/lib/tokens/medals';
import { formatNumber } from '@/i18n/format';
import { CHAMPIONS_ORDER_ALL_TIME } from '@/components/profile/handicap/whs/sections/course-legends/_shared/championsOrder';
import { Sec, Lede } from './many/manyBits';
import { BoardList } from './BoardList';
import type { CourseLegendRow, LegendCategory } from '@/lib/gam/types';

/* YOU_TAB_BOARD_LIST_1 AC2 — every open board renders (all nine on a
   zero-round course), from the shared BoardList. */

interface Props {
  /** Null when the count is unavailable — the tile stands down (X6). */
  openBoards: number | null;
  onAllBoards: () => void;
  /** The same holder map the open count is taken from. */
  holders: Map<LegendCategory, CourseLegendRow>;
}

export const UnclaimedCourseSection: React.FC<Props> = ({ openBoards, onAllBoards, holders }) => {
  const { t } = useTranslation('courses');
  const boardTotal = CHAMPIONS_ORDER_ALL_TIME.length;
