}

/** 15.1 — THE ONE SIGNED INDEX-MOVEMENT FORMATTER: one decimal, true minus for
 *  a cut, plus for a rise. The board-row index chip, the slab's "since" clause
 *  and the improved board's figure all read it. */
export function fmtIndexMove(n: number): string {
  const v = Math.abs(n).toFixed(1);
  return n < 0 ? `\u2212${v}` : `+${v}`;
}

/* ARCHITECTURE RULE (moved from AGENTS.md): The Explore Scores lead board renders every row through BoardRowView, whose grammar (ranked or feed) is chosen by boardColumns(board).ranked; figures come only from boardValue/boardSecondary, so the page cannot disagree with the see-all sheet. There is no podium and no column header on the lead board. ALSO: every row on the Explore leaderboards screen carries a 1px hairline beneath it; a hairline also separates column labels from data and a sheet's controls from its list; the pinned self row is marked by a 12px gap above it and the amber self tint, not by the absence of a rule. */
export function BoardRowView({
  row,
  board,
  isSelf,
  gap,
  pinned,
  onPress,
  flush,
}: {
  row: Row;
  board: BoardKey;
  isSelf: boolean;
  /** Only the PINNED copy of the member's row carries this (S5.4). */
  gap?: string | null;
  /** The pinned self row: a 12px break above it (9.13). */
  pinned?: boolean;
  onPress?: (row: Row) => void;
  /** CB20 — no horizontal padding: the parent Section owns the gutter. */
  flush?: boolean;
}) {
  const { t, i18n } = useTranslation('courses');
  const value = boardValue(row, board, t as never);
  const second = boardSecondary(row, board);
  const { ranked } = boardColumns(board);
  // CB27: ranking choices carry no feat chip; Rare air sheet scoping is unchanged.
  const feat = isFeatBoard(board) || board === 'gross' ? boardFeatMarker(row, board, t) : null;
  const course = row.course_name ?? t('discover.unknownCourse');
  /* Feed rows sit under day-ladder groups that state the year; a ranked board has no groups. */
  const date = ranked
    ? playDateStandalone(row.play_date, i18n?.language)
    : playDateUnderYearHeader(row.play_date, i18n?.language);
  /* 12.1 — WHAT delta_index MEANS, proved against 4,067 live rounds: hcp_at_time
     is the index a member carried INTO the round, and delta_index is the
     movement THAT round caused — it appears as the NEXT round's hcp_at_time.
     3,020 of those rounds match that next-round test directly; 99.3% of all
     non-null rounds agree with the model; only 19 rounds in the whole table
     match neither direction. 12.2 — THE CONSEQUENCE: a member's MOST RECENT
     round always carries a NULL delta_index, because the movement it caused is
     recorded against the round that follows it. The chip is therefore absent
     on the newest row from every member, and that absence does NOT mean the
     index held. Deliberately no fallback, no placeholder and no dash — this is
     a recorded note, not a rendering change. */
  const chip = !ranked && row.delta_index != null && Number(row.delta_index) !== 0 ? Number(row.delta_index) : null;

  return (
    <button
      type="button"
      onClick={() => onPress?.(row)}
      data-board-row=""
      data-board-self={isSelf ? '' : undefined}
      style={{
        width: '100%',
        display: 'grid',
        gridTemplateColumns: gridFor(ranked),
        columnGap: M.colGap,
        alignItems: 'center',
        padding: `${M.padY}px ${flush ? 0 : M.padX}px`,
        marginTop: pinned ? M.pinnedGap : 0,
        background: isSelf ? SELF_ROW_TINT : 'transparent',
        border: 'none',
        /* 9.13 — every row carries a hairline beneath it, the last included. */
        borderBottom: `1px solid ${A.SOFT}`,
        textAlign: 'left',
        fontFamily: SANS,
        cursor: onPress ? 'pointer' : 'default',
      }}
    >
      {ranked && (
        <span
          className="tabular-nums"
          style={{
            textAlign: 'center',
            fontSize: M.posSize,
            fontWeight: M.posWeight,
            /* CB32: two halves, both binding. No position is ever amber (or gold)
               for rank — CB27. The viewer's own position is always amber for
               identity — S5.4 (line 27): amber on this surface means YOU. */
            color: isSelf ? A.AMBER : A.FAINT,
          }}
        >
          {/* A TIE STATES ITSELF: T4, never a silent second 4. */}
          {row.is_tie ? `T${row.pos}` : row.pos}
        </span>
      )}
      <span style={{ display: 'flex' }}>
        <MemberAvatar userId={row.user_id} name={row.display_name} photoUrl={row.profile_photo_url} size={M.avatar} />
      </span>
      <span style={{ minWidth: 0 }}>
        <span data-board-name-row style={{ display: 'flex', alignItems: 'center', gap: 6, minWidth: 0 }}>
          <span
          style={{
            display: 'block',
            minWidth: 0,
            fontSize: M.nameSize,
            fontWeight: M.nameWeight,
            letterSpacing: '-0.01em',
            lineHeight: M.nameLine,
            color: isSelf ? A.AMBER : A.INK,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}
        >
          <InlineProMemberName userId={row.user_id}>{row.display_name ?? t('discover.aMember')}</InlineProMemberName>
        </span>
          {feat ? (
            <span
              data-board-feat
              style={{
                flexShrink: 0,
                fontSize: 8.5,
                fontWeight: 800,
                letterSpacing: '0.1em',
                textTransform: 'uppercase',
                color: A.DIM,
                border: `1px solid ${A.BORDER}`,
                borderRadius: 999,
                padding: '1px 5px',
                lineHeight: 1.2,
                whiteSpace: 'nowrap',
              }}
            >
              {feat}
            </span>
          ) : null}
          {/* CHIP1 — only an explicit true; null is not evidence of a social round. Follows the feat.
              CB6.1 — THE RULE: a pill is for a rare achievement (the feat chips keep theirs);
              a plain coloured word is for a category, which is what a competition is. A bare
              word next to a feat pill is correct, not an oversight — do not re-add the border
              for consistency with the chip beside it. */}
          {row.is_competition === true ? <CompetitionMark data-board-competition /> : null}
          {/* 18.3 — the chip is a fact about the member's handicap, not the
              figure, so it sits in the name row: name, feat badge, chip. Only
              the name shrinks. */}
          {chip != null ? (
            <span
              data-index-chip
          data-gate-blur=""
              className="tabular-nums"
              style={{
                flexShrink: 0,
                whiteSpace: 'nowrap',
                fontSize: 10,
                fontWeight: 700,
                lineHeight: 1.2,
                borderRadius: 999,
                padding: '1px 5px',
                color: chip < 0 ? A.GREEN : A.MUTE,
                border: `1px solid ${chip < 0 ? INDEX_CUT_BORDER : A.BORDER}`,
              }}
            >
              {fmtIndexMove(chip)}
            </span>
          ) : null}
        </span>
        {/* 18.2 — two elements: the club takes the remaining width and
            ellipsises; " · {date}" is pinned and never shrinks. */}
        <span
          data-board-sub
          style={{
            display: 'flex',
            minWidth: 0,
            marginTop: 1,
            fontSize: M.subSize,
            lineHeight: M.subLine,
            color: A.MUTE,
            whiteSpace: 'nowrap',
          }}
        >
          <span data-board-sub-club style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}>
            {gap ?? course}
          </span>
          {!gap && date ? (
            <span data-board-sub-date style={{ flexShrink: 0 }}>
              {` \u00B7 ${date}`}
            </span>
          ) : null}
        </span>
      </span>
      {board === 'recent' ? <span style={{ display: 'flex', alignItems: 'baseline', gap: 12 }}>
        <span style={{ width: RECENT_SCORE_WIDTH, textAlign: 'center' }}><ScoreWithToPar score={row.net_score} par={row.course_par} kind="net" fontSize={M.recentNetSize} fontWeight={M.secondaryWeight} scoreHandle="main" /></span>
        <span style={{ width: RECENT_SCORE_WIDTH, textAlign: 'center' }}><ScoreWithToPar score={row.gross_score} par={row.course_par} kind="gross" fontSize={M.recentGrossSize} fontWeight={M.secondaryWeight} scoreHandle="secondary" /></span>
      </span> : board === 'topar' || board === 'net' ? <span style={{ textAlign: 'right', minWidth: MAIN_FIG_MIN_W }}>
        <ScoreWithToPar score={board === 'topar' ? row.gross_score : row.net_score} par={row.course_par}
          kind={board === 'topar' ? 'gross' : 'net'} tone={A.INK} fontSize={M.figureSize} fontWeight={M.figureWeight} lineHeight={1} scoreHandle="main" />
      </span> : <span style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'flex-end', columnGap: 3 }}>
        {/* S1.3 — THE FIGURE FOLLOWS THE COLOUR LAW, NEVER AMBER.
            18.5 — fixed min-width tracks so right edges align. */}
        <span
          data-board-main
          data-gate-blur=""
          className="tabular-nums"
          style={{ minWidth: MAIN_FIG_MIN_W, textAlign: 'right', fontSize: M.figureSize, fontWeight: M.figureWeight, letterSpacing: M.figureTracking, lineHeight: 1, color: value.tone }}
        >
          {value.text}
        </span>
        {second ? (
          <span
            data-board-secondary
          data-gate-blur=""
            className="tabular-nums"
            style={{ minWidth: SECOND_FIG_MIN_W, textAlign: 'left', fontSize: M.secondarySize, fontWeight: M.secondaryWeight, lineHeight: 1, color: second.tone }}
          >
            {second.text}
          </span>
        ) : null}
      </span>}
    </button>
  );
}

