export function CompetitionBoards({ viewerId, scope, enabled, onRowPress }: { viewerId: string | undefined; scope: BoardFilters['scope']; enabled: boolean; onRowPress: (row: RoundPressTarget) => void }) {
  const { t } = useTranslation('courses');
  const query = useCompetitionBoards(viewerId, scope, enabled);
  const [openKey, setOpenKey] = useState<string | null>(null);
  const data = query.isSuccess ? query.data ?? [] : [];
  // CB28: the rail is one row; hold its measured height between two populated states.
  const frame = useHeldFrame({ active: enabled && query.isSuccess, pending: enabled && query.isPending, count: data.length > 0 ? 1 : 0 });
  if (frame.mode === 'none') return null;
  const cards = groupCompetitionCards(data);
  const open = cards.find((c) => c.key === openKey) ?? null;
  return (
    <div data-competitions-section style={{ ...FIGS }}>
    <Section
      contest
      eyebrow={t('amateur.competitions.eyebrow', { defaultValue: 'Home club golf' })}
      title={t('amateur.competitions.title', { defaultValue: 'Competitions' })}
      meta={t('amateur.competitions.window', { defaultValue: 'Last 30 days' })}
    >
      {frame.mode === 'hold' ? <HeldRows count={frame.heldCount} rowHeight={frame.rowHeight} /> : <div ref={frame.bodyRef}><Rail>
        {cards.map((c) => <Card key={c.key} card={c} viewerId={viewerId} onOpen={() => setOpenKey(c.key)} onRowPress={onRowPress} />)}
      </Rail></div>}
      <FieldSheet card={open} viewerId={viewerId} onClose={() => setOpenKey(null)} onRowPress={onRowPress} />
    </Section>
    </div>
  );
}

import type { CSSProperties } from 'react';
import { useTranslation } from 'react-i18next';
import { COMPETITION } from './tokens';

/** CB8 — the one competition mark for row surfaces (board rows, Standout rounds).
 * CB6.1 stands: a category, so a bare coloured mark, never a pill. Every paint is
 * currentColor so the glyph cannot fork from the token. Uses the short register
 * key (`competitionShort`); CompetitionBoards' sentence keeps `competitionChip`.
 * Only call-site spacing and data handles pass through — never restyle the mark. */
type MarkProps = { style?: Pick<CSSProperties, 'marginLeft'> } & { [k: `data-${string}`]: boolean | string | undefined };

/** CB10 — the trophy glyph, extracted so the field-sheet subtitle can carry it
 * at a second size without copying the path data. One home for the glyph; only
 * width/height pass in. Every paint stays currentColor. */
export function CompetitionTrophy({ width, height }: { width: number; height: number }) {
  return (
    <svg width={width} height={height} viewBox="0 0 10 11" aria-hidden="true" focusable="false" style={{ display: 'block', flex: 'none' }}><path d="M3 2H1.4v1.1a2 2 0 0 0 2 2M7 2h1.6v1.1a2 2 0 0 1-2 2" stroke="currentColor" strokeWidth="1.2" fill="none" strokeLinecap="round" /><path d="M3 1h4v2.6a2 2 0 0 1-4 0V1Z" fill="currentColor" /><rect x="4.35" y="5.4" width="1.3" height="2" fill="currentColor" /><rect x="2.7" y="7.4" width="4.6" height="1.3" rx="0.5" fill="currentColor" /></svg>
  );
}

export function CompetitionMark({ style, ...data }: MarkProps) {
  const { t } = useTranslation('courses');
  return (
    <span {...data} style={{ display: 'inline-flex', alignItems: 'center', gap: 4, flexShrink: 0, whiteSpace: 'nowrap', color: COMPETITION, ...style }}>
      <CompetitionTrophy width={9} height={10} />
      <span style={{ fontSize: 8.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', lineHeight: 1 }}>{t('discover.filterBoard.competitionShort', { defaultValue: 'Comp' })}</span>
    </span>
  );
}

import { useCallback, useState, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronDown, ChevronUp, ArrowDown, ArrowUp } from 'lucide-react';

import { CourseImageFallback } from './CourseImageFallback';
import { A, SANS, FIGS, DISCOVER_FACT, PODIUM_ACCENT } from './tokens';
import { type BoardFilters } from './boardFilters';
/* S3.3 — THE SHEET STATES THE SAME APPLIED LINE AS THE PAGE, from the page's own
   formatter. No second wording lives here. */
import { describeFilterParts } from './describeFilters';
import { SquircleAvatar } from '@/components/ui/SquircleAvatar';
import { r } from '@/lib/radius';
import { useBoardCourses, type BoardCourseRow } from './hooks/useBoardCourses';
import { useBoardCoursePlayers, type BoardCoursePlayer } from './hooks/useBoardCoursePlayers';
import { CoursesPlayedSeeAllSheet } from './CoursesPlayedSeeAllSheet';
import { CourseHolePanel } from './CourseHolePanel';
import { CourseCardPanel } from '@/features/courses/components/holes/analytical/CourseCardPanel';
import { CourseAnalyticsPanels } from '@/features/courses/components/holes/analytical/CourseAnalyticsPanels';
import { useCourseHoleAnalysis } from '@/hooks/gam/useCourseHoleAnalysis';
import { ListTerminalRow } from './ListTerminalRow';

/**
 * COURSES MOSAIC (BRIEF_COURSES_HOW_THEY_PLAYED — AMENDMENT F).
 *
 * IT ANSWERS HOW EACH COURSE PLAYED — that is what each row CONTAINS, not the
 * order they are in. get_board_courses ORDERS BY ROUNDS DESC (AMENDMENT B), so
 * the most-played course leads. THE ROWS RENDER IN THE RPC'S OWN ORDER AND
 * NOTHING IS SORTED CLIENT-SIDE (S1.3): a single round at +12.0 leading a
 * section is a claim the data cannot support.

 *
 * THE PANEL DOES NOT LIST MEMBERS (S3.1). It duplicated the board directly above
 * it and cost a query per open; the course's own analytics stand there instead.
 *
 * It still reads the page's one filter bar, still takes NO board key, and
 * switching Ranked by must leave it completely unchanged.
 */

const ROW_H = 46;
const RANK_W = 14;
const PLAYS_TO_W = 62;
const CHEVRON_W = 22;
/** S2.3 — a rise is GREEN, a fall is A.DIM. Red on this page means UNDER PAR. */
const TREND_UP = PODIUM_ACCENT.green;
const FEATURED_SCRIM = 'linear-gradient(180deg, rgba(0,0,0,0.14), rgba(0,0,0,0.04) 32%, rgba(0,0,0,0.76))';
const TILE_DEPTH_SCRIM = 'linear-gradient(180deg, rgba(0,0,0,0.10), rgba(0,0,0,0) 58%, rgba(0,0,0,0.18))';
const SMALL_TILE_IMAGE_H = 76;
/* Amendment I: two reserved name lines and one aligned data baseline. */
const SMALL_TILE_STRIP_H = 62;
/* M2.1 — the open tile's ring: 1px at 38% ink, the weight of the avatar-stack rings. */
const TILE_RING = 'rgba(248,250,252,0.38)';
const SMALL_TILE_H = SMALL_TILE_IMAGE_H + SMALL_TILE_STRIP_H;

const CAP = {
  fontSize: 9.5,
  fontWeight: 700,
  letterSpacing: '0.13em',
  textTransform: 'uppercase' as const,
  color: A.DIM,
};

export interface CoursesPlayedSectionProps {
  userId: string | undefined;
  /** The page's CURRENT filter state. The board key is deliberately absent. */
  filters: BoardFilters;
  onCoursePress?: (courseId: string) => void;
  onMemberPress?: (userId: string) => void;
}

export function CoursesPlayedSection({
  userId,
  filters,
  onCoursePress,
  onMemberPress,
}: CoursesPlayedSectionProps) {
  const { t } = useTranslation('courses');
  const [expanded, setExpanded] = useState(true);
  /* S2.5 — one row open at a time. */
  const [openId, setOpenId] = useState<string | null>(null);
  const [seeAll, setSeeAll] = useState(false);

  const appliedParts = describeFilterParts(filters, t as never);
  const courses = useBoardCourses(userId, filters, { limit: 5 });
  const rows = courses.data?.rows ?? [];
  const total = courses.data?.total ?? 0;

  const toggle = useCallback((id: string) => {
    setOpenId((cur) => (cur === id ? null : id));
  }, []);

  const toggleSection = useCallback(() => {
    setExpanded((current) => {
      if (current) setOpenId(null);
      return !current;
    });
  }, []);

  /* The member has already said which course they care about. */
  if (filters.courses === 'one') return null;

  if (courses.isPending) {
    return (
      <section aria-hidden style={{ fontFamily: SANS }}>
        <div style={{ height: 19, width: 254, background: A.PANEL, borderRadius: 3 }} />
        <div style={{ height: 10, width: 142, marginTop: 6, background: A.PANEL, borderRadius: 3 }} />
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 8, marginTop: 12 }}>
          <div style={{ gridColumn: '1 / -1', height: 132, background: A.PANEL, borderRadius: 10 }} />
          {[0, 1, 2, 3].map((i) => (
            <div key={i} style={{ height: SMALL_TILE_H, background: A.PANEL, borderRadius: 10 }} />
          ))}
        </div>
      </section>
    );
  }

  if (rows.length === 0) return null;

  const featured = rows[0];
  const pairs: BoardCourseRow[][] = [];
  for (let index = 1; index < rows.length; index += 2) pairs.push(rows.slice(index, index + 2));

  return (
    <section style={{ fontFamily: SANS, ...FIGS }}>
      <ListTerminalRow
        label={t('discover.coursesPlayed.title', 'How the courses played')}
        onPress={toggleSection}
        expanded={expanded}
      />
      {expanded ? (
        <div
          style={{
            marginTop: 8,
            display: 'grid',
            gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
            gap: 8,
          }}
        >
          <FeaturedCourseCard
            row={featured}
            userId={userId}
            filters={filters}
            onCoursePress={onCoursePress}
          />

          {pairs.map((pair) => (
            <CourseMosaicPair
              key={pair.map((row) => row.course_id).join(':')}
              rows={pair}
              openId={openId}
              onToggle={toggle}
              userId={userId}
              filters={filters}
              onCoursePress={onCoursePress}
            />
          ))}
          {total > 5 && (
            <div style={{ gridColumn: '1 / -1' }}>
              <ListTerminalRow
                label={t('discover.coursesPlayed.seeAll', 'See all {{count}} courses', { count: total })}
                onPress={() => setSeeAll(true)}
                borderless
              />
            </div>
          )}
        </div>
      ) : null}

      <CoursesPlayedSeeAllSheet
        open={seeAll}
        onClose={() => setSeeAll(false)}
        userId={userId}
        filters={filters}
        appliedParts={appliedParts}
        board="played"
        onBoardChange={() => {}}
        onCoursePress={onCoursePress}
        onMemberPress={onMemberPress}
      />
    </section>
  );
}

function CourseMosaicPair({
  rows,
  openId,
  onToggle,
  userId,
  filters,
  onCoursePress,
}: {
  rows: BoardCourseRow[];
  openId: string | null;
  onToggle: (id: string) => void;
  userId: string | undefined;
  filters: BoardFilters;
  onCoursePress?: (courseId: string) => void;
}) {
  const openRow = rows.find((row) => row.course_id === openId);
  return (
    <>
      {rows.map((row) => (
        <CourseMosaicTile
          key={row.course_id}
          row={row}
          featured={false}
          open={openId === row.course_id}
          onToggle={() => onToggle(row.course_id)}
          fullWidth={rows.length === 1}
        />
      ))}
      {openRow && (
        <CourseMosaicPanel row={openRow} userId={userId} filters={filters} onCoursePress={onCoursePress} />
      )}
    </>
  );
}

function FeaturedCourseCard({
  row,
  userId,
  filters,
  onCoursePress,
}: {
  row: BoardCourseRow;
  userId: string | undefined;
  filters: BoardFilters;
  onCoursePress?: (courseId: string) => void;
