/**
 * HOW THEY PLAYED, WITH A CATALOGUE SEARCH (BRIEF_SCORES_REFINEMENTS S2/S3).
 *
 * DEFAULT IS UNCHANGED (S2.1): the section shows the course at the top of the
 * selected course board, and the analytics card itself is untouched in every
 * respect — the monotone curve, the par datum, the signed By par scale and both
 * gates all still live inside CourseHolePanel.
 *
 * THE SEARCH IS THE EXISTING ONE (S2.6). useCourseSearch is the full-catalogue
 * ILIKE read the directory and the Legends drilldown already use; nothing new is
 * built here and no second search exists.
 *
 * THE EMPTY STATE IS THE COMMON CASE (S3). Most of the catalogue has never been
 * played by anyone in the circuit, so a searched course has THREE distinct
 * outcomes and they are never collapsed into one message:
 *
 *   NO ROUNDS AT ALL          — stated here, with the photograph and the name.
 *   BELOW THE HOLE-DETAIL GATE — the existing gate wording, from CourseHolePanel,
 *                                unchanged, with the photograph, the round count
 *                                and the low round when there is one.
 *   ONLY THE VIEWER'S ROUNDS  — the field-of-one guard inside the panel fires as
 *                                specified; nothing here interferes.
 *
 * The searched course is COMPONENT STATE and resets on entry (S2.5).
 */

export interface HowTheyPlayedSectionProps {
  /** The top row of the selected course board — the default subject (S2.1). */
  boardRow: BoardCourseRow | null;
  userId: string | undefined;
  filters: BoardFilters;
  onCoursePress?: (courseId: string) => void;
}

export function HowTheyPlayedSection({
  boardRow,
  userId,
  filters,
  onCoursePress,
}: HowTheyPlayedSectionProps) {
  const { t } = useTranslation('courses');

  const [query, setQuery] = useState('');
  const [pickedId, setPickedId] = useState<string | null>(null);
  const [narrowPlaceholder, setNarrowPlaceholder] = useState(false);

  useEffect(() => {
    const update = () => setNarrowPlaceholder(window.innerWidth <= 360);
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);

  const results = useCourseSearch(query);
  const picked = useSearchedCourse(userId, pickedId, filters);

  const searching = query.trim().length >= 2 && pickedId == null;

  /* The subject: the searched course when there is one, else the board's top. */
  const searchedRow = picked.data?.row ?? null;
  const filteredSearchedRow = picked.data?.filteredRow ?? null;
  const subjectRow = pickedId
    ? searchedRow && { ...searchedRow, low_gross: filteredSearchedRow?.low_gross ?? null, low_to_par: filteredSearchedRow?.low_to_par ?? null, low_by: filteredSearchedRow?.low_by ?? null }
    : boardRow;
  const subjectName = pickedId ? picked.data?.name ?? null : boardRow?.name ?? null;
  const subjectThumb = pickedId
    ? picked.data?.thumbnail ?? null
    : boardRow?.thumbnail_image ?? null;
  const subjectId = pickedId ?? boardRow?.course_id ?? null;

  const clear = () => {
    setPickedId(null);
    setQuery('');
  };

  return (
    <div style={{ marginTop: 26, fontFamily: SANS, ...FIGS }}>
      <DiscoverSectionHeading title={t('discover.scores.courseAnalytics', 'Course analytics')} />
      {/* S2.2 — the field, full width, above the card. Shared with the college Yearbook. */}
      <div style={{ position: 'relative', marginBottom: 10 }}>
        <CatalogueSearchField
          value={query}
          onChange={(next) => {
            setQuery(next);
            if (pickedId) setPickedId(null);
          }}
          placeholder={
            narrowPlaceholder
              ? t('discover.scores.searchCourseForAnalytics', 'Search a course for analytics')
              : t('discover.scores.searchAnyCourse', 'Search any course for analytics')
          }
          ariaLabel={t('discover.scores.searchAnyCourse', 'Search any course for analytics')}
          showClear={Boolean(pickedId) || query.length > 0}
          onClear={clear}
          clearAriaLabel={t('discover.scores.clearCourse', 'Back to the board')}
        />


        {searching && (
          <div
            style={{
              marginTop: 6,
              background: A.PANEL,
              border: `1px solid ${A.BORDER}`,
              borderRadius: r.sm,
              overflow: 'hidden',
            }}
          >
            {results.isFetching && (results.data ?? []).length === 0 ? (
              <div style={{ ...KICKER, padding: '12px 12px', color: A.MUTE }}>
                {t('discover.scores.searching', 'Searching')}
              </div>
            ) : (results.data ?? []).length === 0 ? (
              <div style={{ ...KICKER, padding: '12px 12px', color: A.MUTE }}>
                {t('discover.scores.noCourseMatch', 'No course by that name.')}
              </div>
            ) : (
              (results.data ?? []).slice(0, 12).map((c, i) => (
                <button
                  key={c.id}
                  type="button"
                  onClick={() => {
                    setPickedId(c.id);
                    setQuery(c.name);
                  }}
                  style={{
                    display: 'block',
                    width: '100%',
                    padding: '10px 12px',
                    border: 'none',
                    borderTop: i === 0 ? 'none' : `1px solid ${A.BORDER}`,
                    background: 'transparent',
                    color: A.INK,
                    fontFamily: SANS,
                    fontSize: 13.5,
                    fontWeight: 700,
                    textAlign: 'left',
                    cursor: 'pointer',
                  }}
                >
                  {c.name}
                  {(c.region ?? c.country) && (
                    <span style={{ ...KICKER, display: 'block', marginTop: 2, color: A.MUTE }}>
                      {c.region ?? c.country}
                    </span>
                  )}
                </button>
              ))
            )}
          </div>
        )}
      </div>

      {pickedId && picked.isPending ? (
        <div aria-hidden style={{ minHeight: 300 }} />
      ) : subjectId && subjectRow ? (
        /* ROUNDS EXIST. The card is unchanged; the gate and the field-of-one
           guard inside it decide what the member sees. The photograph rides with
           it so a searched course always confirms itself (S3.3). */
        <CourseAnalyticsCard
          row={subjectRow}
          userId={userId}
          filters={filters}
          onCoursePress={onCoursePress}
          courseName={subjectName}
          ctaBorderless
          media={
            pickedId ? (
              <CoursePhoto
                courseId={subjectId}
                name={subjectName}
                thumbnail={subjectThumb}
                area={picked.data?.area ?? null}
              />
            ) : undefined
          }
        />
      ) : subjectId ? (
        /* NO ROUNDS AT ALL. Said plainly, in the present tense (S3.4). */
        <div data-course-analytics-card style={{ background: A.PANEL, borderRadius: r.md, overflow: 'hidden' }}>
          <div style={{ padding: '12px 12px 14px' }}>
            <h3 style={{ margin: '0 0 12px', fontSize: 15, fontWeight: 800, lineHeight: 1.25, color: A.INK }}>
              {subjectName ?? '\u2014'}
            </h3>
            <CoursePhoto
              courseId={subjectId}
              name={subjectName}
              thumbnail={subjectThumb}
              area={picked.data?.area ?? null}
            />
            <CourseCardPanel courseId={subjectId} courseName={subjectName ?? undefined} embedded />
            <p style={{ margin: 0, fontSize: 13.5, fontWeight: 700, color: A.INK }}>
              {t('discover.scores.noOnePlayed', 'No one has played {{course}} yet.', {
                course: subjectName ?? '\u2014',
              })}
            </p>
            <p style={{ ...KICKER, margin: '6px 0 0', color: A.MUTE }}>
              {t('discover.scores.beTheFirst', 'Play it and you will be the first.')}
            </p>
            <ListTerminalRow
              label={t('discover.coursesPlayed.seeFullAnalytics', 'See full course analytics')}
              onPress={() => onCoursePress?.(subjectId)}
              borderless
            />
          </div>
        </div>
      ) : null}
    </div>
  );
}

/** S3.3 — the photograph and the name, in every state. */
function CoursePhoto({
  courseId,
  name,
  thumbnail,
  area,
}: {
  courseId: string;
  name: string | null;
  thumbnail: string | null;
  area: string | null;
}) {
  return (
    <CourseImageFallback
      courseId={courseId}
      courseName={name}
      imageUrl={thumbnail}
      initialsSize={28}
      style={{ display: 'block', width: '100%', height: 132, borderRadius: 0 }}
    >
      <span aria-hidden style={{ position: 'absolute', inset: 0, background: SCRIM_STANDOUT }} />
      <span
        style={{
          position: 'absolute',
          inset: 'auto 11px 9px',
          zIndex: 1,
          minWidth: 0,
          color: DISCOVER_FACT,
        }}
      >
        <span
          style={{
            display: 'block',
            fontSize: 15,
            fontWeight: 800,
            lineHeight: 1.2,
            textShadow: '0 1px 2px rgba(0,0,0,0.72)',
          }}
        >
          {name ?? '\u2014'}
        </span>
        {area && (
          <span
            style={{
              ...KICKER,
              display: 'block',
              marginTop: 3,
              color: DISCOVER_QUIET,
              textShadow: '0 1px 2px rgba(0,0,0,0.72)',
            }}
          >
            {area}
          </span>
        )}
      </span>
    </CourseImageFallback>
  );
}

export default HowTheyPlayedSection;

import React, { useState } from 'react';

import { SquircleAvatar } from '@/components/ui/SquircleAvatar';

import { CourseImageFallback } from './CourseImageFallback';
import { A, CARD_SHELL, LABEL, NEW_CARD_RING, NUMF, SANS } from './tokens';

/**
 * THE STANDOUT TILE — one card, two sections (BRIEF_PERSONAL_BESTS_SECTION §3.3).
 *
 * Extracted VERBATIM from AroundTheWorld's tile markup so Standout Rounds and
 * Personal Bests read as siblings by construction rather than by discipline. No
 * value was changed in the move: photo scrim, 10px glass figure chip top-left,
 * plain age label top-right, course name + region over the image, WHO line in
 * ink (amber when the viewer), quiet detail line beneath.
 *
 * The ONE addition Personal Bests needed is `subline` — the server's
 * reference_line, rendered under the detail in a quieter tone. Standout Rounds
 * passes nothing for it, so its tiles are byte-identical to before.
 */

import { SCRIM_STANDOUT } from '@/styles/photoScrim';

/** The reference line's metrics — the reserve is DERIVED, never typed. */
const SUBLINE_FS = 11;
const SUBLINE_LH = 1.3;
const SUBLINE_RESERVE = Math.round(SUBLINE_FS * SUBLINE_LH); // 14

/** The tile scrim, held once in ./photoScrim and shared with the photo rails. */
export const TILE_SCRIM = SCRIM_STANDOUT;

/** A photo at or above this height gets the larger chip and name sizes. */
export const TALL = 180;

interface Props {
  courseId: string;
  courseName: string | null;
  imageUrl: string | null;
  region: string | null;
  /** Photo height in px — a pure function of rank position in both sections. */
  photo: number;
  /** Figure chip. Rendered only when `figure` is present. */
  figure: string | null;
  /**
   * FIGURE TONE — the glass chip's numeral colour. Defaults to flat white
   * (BRIEF_GLASS_BADGES_DARK). One caller today: CourseShelf passes the green
   * 9+ rating tone. The to-par red is NOT carried here — see `unitTone`.
   */
  figureTone?: string;

  unit?: string;
  /** The to-par unit's colour when the round is UNDER par. Omitted keeps
   *  the white unit, so every non-golf unit (rank scope, rating tier) is
   *  unchanged. Mirrors FigureChip's prop of the same name. */
  unitTone?: string;
  /** Relative age, top-right. */
  whenLabel: string;
  /**
   * CIRCLE RAIL ONLY: put the date on the same glass substrate as the score.
   * Defaults false, preserving the plain age label on every existing surface.
   */
  whenGlass?: boolean;
  /** Member name, already resolved ("You" for the viewer). */
  who: string;
  isOwn: boolean;
  /** Quiet line under the name. Empty string renders nothing. */
  detail?: string;
  onDetailPress?: () => void;
  /**
   * PERSONAL BESTS ONLY: the server's reference_line. Null renders NOTHING —
   * no dash, no placeholder (§3.5).
   */
  subline?: string | null;
  /** Fixed-width trailing slot on the WHO row (the reaction control). */
  trailing?: React.ReactNode;
  /**
   * HORIZONTAL RAILS ONLY (BRIEF_EXPLORE_BOARD_SELECTOR §2): reserve the tallest
   * wording case — two lines of name and two of fact — so every tile in a rail
   * is the same height whatever the course or member name does. Omitted
   * everywhere else, which keeps vertical lists free to size to content.
   */
  reserveTwoLines?: boolean;
  /**
   * Reserve the reference-line row even when this tile has none, so every
   * tile in a rail is one height. OPT-IN: Standout Rounds and the club and
   * standing shelves must not gain a dead row. Same discipline as
   * CircleShelf reserving its HCP row when privacy leaves it empty.
   */
  reserveSubline?: boolean;
  /**
   * STANDING SHELF ONLY: the name is always the one word "You" and the fact
   * line is the one-line "Last change …" — neither can wrap, so reserving two
   * lines of each leaves the caption visibly taller than the club rail's.
   * Passing 1 reserves a single line instead; the rail stays internally
   * uniform because every tile gets the same value. Defaults keep every
   * existing caller byte-identical.
   */
  nameLines?: 1 | 2;
  factLines?: 1 | 2;
  /**
   * Optional compact rail caption. It makes the member name one ellipsized line
   * and reserves one fixed line beneath it, indented past the 20px avatar.
   * Omitted by existing callers, whose caption layout remains unchanged.
   */
  railCaptionLine?: React.ReactNode;
  /** Optional full-width figure row between photo and text panel, with a
   *  1px A.SOFT rule beneath it. Omitted by every existing caller. */
  railFigures?: React.ReactNode;

  /**
   * ADDITIVE. With the rail caption layout, allow the NAME two lines and reserve
   * the height for both, so a long member name wraps instead of truncating and
   * the rail stays uniform (BRIEF_EXPLORE_DEVICE_PASS §2a). Defaults to 1, so
   * every existing caller keeps its single ellipsized line.
   */
  captionNameLines?: 1 | 2;


  /** Anything below the detail line ("+n more here"). */
  footer?: React.ReactNode;
  /**
   * HERO ONLY (BRIEF_FEAT_SECTIONS_HIERARCHY §1.1, §1.3): names the feat kind
   * above the member row, and grows the course name and the figure chip. Every
   * masonry tile leaves all three undefined and is byte-identical to before.
   */
  kicker?: string | null;
  nameSize?: number;
  chipScale?: 'md' | 'lg';
  /**
   * THE MEMBER'S AVATAR (BRIEF_FEAT_SECTIONS_FINISHING §3) — 20px squircle to
   * the left of the name, on EVERY tier. `avatarUserId` must be the member's
   * user id: the deterministic fallback colour hashes it, so a photo-less
   * member matches their own initials tile in the Clubhouse feed and the
   * friends rail. Hashing the display name instead would still be stable but
   * would NOT match, which is the whole point.
   */
  avatarUrl?: string | null;
  avatarUserId?: string | null;
  /**
   * NEW PERSONAL HIGHS ONLY (§5): the improvement over the previous best, drawn
   * INSIDE the one glass chip after a hairline. A figure with an ARROW is a
   * MOVEMENT — green is better, red is worse — which is a different scale from
   * a SCORE, where under par is red. Do not "correct" this to red.
   *
   * There is deliberately NO red branch: these kinds only fire when the
   * previous best is beaten, so the delta is always positive (§5.7).
   */
  delta?: number | null;
  /**
   * A COMPLETE REPLACEMENT for the glass figure chip, not an addition to it
   * (BRIEF_COURSE_TILES_BADGE_AND_SCROLL §2b). One caller: the course rails,
   * which now wear the app's rank badge. Given, `figure`, `unit`,
   * `figureTone`, `delta` and `wait` are all ignored — nesting a glass badge
   * inside the glass chip would stack two blurs.
   */
  figureNode?: React.ReactNode;
  /**
   * THE WAIT (BRIEF_FEAT_SECOND_FIGURE §1.2, §3.3) — the rounds a first-ever
   * feat took, drawn in the same chip slot as a delta but in WHITE, never
   * green: nothing was beaten, so there is no "better" to report. Mutually
   * exclusive with `delta` — a chip holds one second figure.
   */
  wait?: number | null;
  /** The small-caps word before the wait ("After"), already localised. */
  waitLabel?: string | null;

  /** New-since ring. */
  isNew?: boolean;
  onPress?: () => void;
}


export function StandoutTile({
  courseId,
  courseName,
  imageUrl,
  region,
  photo,
  figure,
  figureNode,
  unit,
  unitTone,
  whenLabel,
  whenGlass = false,
  who,
  isOwn,
  detail = '',
  onDetailPress,
  subline = null,
  trailing,
  reserveTwoLines = false,
  reserveSubline = false,
  nameLines = 2,
  factLines = 2,
  railCaptionLine,
  railFigures,
  captionNameLines = 1,


  footer,
  kicker = null,
  avatarUrl = null,
  avatarUserId = null,
  delta = null,
  wait = null,
  waitLabel = null,

  figureTone,
  nameSize,
  chipScale = 'md',
  isNew = false,
  onPress,
}: Props) {
  const [pressed, setPressed] = useState(false);
  const tall = photo >= TALL;
  const large = chipScale === 'lg';

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onPress}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
      onPointerCancel={() => setPressed(false)}
      style={{
        ...CARD_SHELL,
        ...(isNew ? NEW_CARD_RING : null),
        padding: 0,
        textAlign: 'left',
        fontFamily: SANS,
        cursor: onPress ? 'pointer' : 'default',
        opacity: pressed ? 0.72 : 1,
        transition: 'opacity 120ms ease',
      }}
    >
      <CourseImageFallback
        courseId={courseId}
        courseName={courseName}
        imageUrl={imageUrl}
        initialsSize={tall ? 26 : 22}
        style={{ height: photo }}
      >
        <div style={{ position: 'absolute', inset: 0, background: TILE_SCRIM }} />

        {/* THE TOP LANES — COLLISION IS IMPOSSIBLE, NOT UNLIKELY
            (BRIEF_EXPLORE_DEVICE_PASS §2a).

            The score chip and the date used to be two independent absolutely
            positioned children, one pinned left and one pinned right, so at some
            width and some date length they HAD to meet. They are now the two
            children of ONE flex row that spans the photo: the chip owns the left
            lane and never shrinks, the date owns the right lane and shrinks
            first, and a 10px gap sits between them by construction. The date is
            one nowrap line with overflow ellipsis, so a longer date SHORTENS —
            it can never reach the chip, at any tile width, in any locale.
            The row does not take pointer events: taps belong to the tile. */}
        <div
          style={{
            position: 'absolute',
            top: 8,
            left: 8,
            right: 10,
            display: 'flex',
            alignItems: 'flex-start',
            justifyContent: 'space-between',
            gap: 10,
            pointerEvents: 'none',
          }}
        >
        {/* FIGURE CHIP — the reason the tile exists: 10px radius on a GLASS
            substrate, so the age beside it stops competing. The fill, hairline
            and blur live in `.standout-figure-chip` (liquid-glass.css) because
            the blur must be an @supports enhancement over a flat base fill —
            inline styles cannot express that (BRIEF_STANDOUT_TILE_MARGIN §5a). */}
        {figureNode ?? (figure ? (
          <span
            className="standout-figure-chip"
            style={{
              flexShrink: 0,
              display: 'inline-flex',
              alignItems: 'baseline',
              gap: 4,
              padding: large ? '6px 12px' : '5px 10px',
              borderRadius: large ? 12 : 10,
            }}
          >

            <span
              style={{
                ...NUMF,
                fontSize: large ? 22 : 16,
                letterSpacing: '-0.02em',
                lineHeight: 1,
                /* The fill is now DARK glass (BRIEF_GLASS_BADGES_DARK), so the
                   figure carries itself — no shadow floor is needed against a
                   light tint any more. */
                color: figureTone ?? '#FFFFFF',
              }}
            >
              {figure}
            </span>
            {unit && (
              <span
                style={{
                  fontSize: 11,
                  fontWeight: 700,
                  letterSpacing: '0.14em',
                  textTransform: 'uppercase',
                  lineHeight: 1,
                  color: unitTone ?? 'rgba(255,255,255,0.9)',
                }}
              >
                {unit}
              </span>
            )}
            {/* THE SECOND FIGURE (BRIEF_FEAT_SECOND_FIGURE §3). One hairline,
                then EITHER a delta or a wait — never both, and NO HAIRLINE AT
                ALL when there is neither (§3.4), so a single-figure chip looks
                deliberate rather than truncated. */}
            {(delta != null && delta > 0) || (wait != null && wait > 0) ? (
              <>
                <span
                  aria-hidden
                  style={{
                    alignSelf: 'stretch',
                    width: 1,
                    marginLeft: 2,
                    background: 'rgba(255,255,255,0.24)',
                  }}
                />
                <span
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: 3,
                  }}
                >
                  {delta != null && delta > 0 ? (
                    <>
                      {/* A DRAWN TRIANGLE, NOT AN EMOJI (§3.2): an emoji fights
                          the tabular figures and renders differently per
                          platform. */}
                      <svg width="7" height="6" viewBox="0 0 7 6" aria-hidden>
                        <path d="M3.5 0 7 6H0z" fill="#4ADE80" />
                      </svg>
                      <span
                        style={{
                          ...NUMF,
                          fontSize: 13,
                          fontWeight: 800,
                          lineHeight: 1,
                          letterSpacing: '-0.02em',
                          /* #4ADE80 survives a bright sky; BAND_GREEN #047857
                             does not (§5.9) — the review chip's problem. */
                          color: '#4ADE80',
                        }}
                      >
                        {delta}
                      </span>
                    </>
                  ) : (
                    <>
                      {/* A WAIT IS NOT GREEN (§1.4, §3.3): green means BETTER
                          THAN BEFORE, and a wait is neither better nor worse.
                          Colouring it would turn green into "interesting". */}
                      {waitLabel ? (
                        <span
                          style={{
                            fontSize: 11,
                            fontWeight: 700,
                            letterSpacing: '0.14em',
                            textTransform: 'uppercase',
                            lineHeight: 1,
                            color: 'rgba(255,255,255,0.6)',
                          }}
                        >
                          {waitLabel}
                        </span>
                      ) : null}
                      <span
                        style={{
                          ...NUMF,
                          fontSize: 13,
                          fontWeight: 800,
                          lineHeight: 1,
                          letterSpacing: '-0.02em',
                          color: '#FFFFFF',
                        }}
                      >
                        {wait}
                      </span>
                    </>
                  )}
                </span>
              </>
            ) : null}

          </span>
        ) : null)}

        {/* AGE — PLAIN TEXT ON THE PHOTO, EVERYWHERE, NO EXCEPTIONS.
            The glass date badge is RETIRED. Glass is the score chip's material,
            and a date wearing it gave the photo two equal-looking figures at
            either end, so the eye had to work out which was which. The date is
            the least important thing on the tile; it is now the quietest. ONE
            chip on the photo, and it is the score.
            `whenGlass` is kept as an accepted prop so existing callsites stay
            valid, and is deliberately inert. Legibility is now carried entirely
            by the shadow, hence the doubled, tighter stack below.
            IT IS ALSO THE RIGHT LANE and shrinks first: minWidth 0 plus a nowrap
            ellipsis is what makes a long date shorten instead of colliding. */}
          <span
            style={{
              minWidth: 0,
              flexShrink: 1,
              textAlign: 'right',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              fontSize: 11,
              fontWeight: 700,
              letterSpacing: '0.14em',
              textTransform: 'uppercase',
              lineHeight: 1.35,
              color: 'rgba(255,255,255,0.78)',
              textShadow: '0 1px 2px rgba(10,14,10,0.62), 0 0 6px rgba(10,14,10,0.45)',
            }}
          >
            {whenLabel}
          </span>
        </div>


        <div style={{ position: 'absolute', left: 10, right: 10, bottom: 9 }}>
          {/* COURSE NAME — two lines (BRIEF_STANDOUT_TILE_NAME_WRAP). Already
              clamped at two here; the shadow is new, because a second line can
              rise past the scrim's 32% fade on the shorter photo tiers. The
              block is ABSOLUTE over the photo, so a wrap costs no tile height
              and estimatePanelHeight is unaffected. */}
          <div
            style={{
              fontSize: nameSize ?? 14,
              fontWeight: 700,
              color: '#fff',
              letterSpacing: '-0.025em',
              lineHeight: 1.14,
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              textShadow: '0 1px 3px rgba(10,14,10,0.6)',
            }}
          >
            {courseName}
          </div>
          {region && (
            <div
              style={{
                ...LABEL,
                fontSize: 11,
                color: 'rgba(255,255,255,0.60)',
                marginTop: 3,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}
            >
              {region}
            </div>
          )}
        </div>
      </CourseImageFallback>

      {railFigures ? (
        <>
          {railFigures}
          <div style={{ height: 1, background: A.SOFT }} />
        </>
      ) : null}

      {/* TEXT PANEL — no figure here. One figure per tile. */}
      <div style={{ padding: '11px 13px 12px' }}>
        {/* HERO KICKER (§1.3) — the feat kind, so the hero says WHAT it is
            before it says who did it. Ink, not amber: amber means the viewer. */}
        {kicker ? (
          <div
            style={{
              fontSize: 11,
              fontWeight: 700,
              letterSpacing: '0.1em',
              textTransform: 'uppercase',
              lineHeight: 1,
              color: A.MUTE,
              marginBottom: 7,
            }}
          >
            {kicker}
          </div>
        ) : null}
        {/* THE NAME ROW owns the whole width now: the reaction control moved
            DOWN onto the detail line, so a long member name wraps to a second
            line instead of being cut off mid-word.

            RESERVED TWO LINES IN A RAIL (BRIEF_EXPLORE_BOARD_SELECTOR §2).
            Variable heights are fine in a vertical list and never in a
            horizontal rail: a tile whose name wraps used to stand taller than
            its neighbours. With `reserveTwoLines` the row holds the tallest
            case (2 x 13px x 1.2 = 32px) and a one-line name simply leaves the
            second line empty. Every masonry/vertical consumer omits the prop
            and is byte-identical to before. */}
        {railCaptionLine !== undefined ? (
          /* AVATAR LEFT, TEXT BLOCK RIGHT, THE TWO CENTRED AGAINST EACH OTHER
             (BRIEF_EXPLORE_SECOND_PASS §5).

             THE REGRESSION THIS FIXES: with two reserved name lines the NAME BOX
             itself carried the reserved height, so a one-line name sat at the top
             of a 36px box and the HCP line sat at the bottom — a visible gap
             between them, with the avatar centred against the pair and therefore
             stranded beside the gap. The reservation now belongs to the COLUMN,
             not to the name: the column holds the tallest case at a constant
             height and CENTRES its two lines inside it, so name and HCP are
             always tight to one another and the avatar — centred against the
             column — lands level with the gap between them. Constant height
             means the avatar cannot move from tile to tile in the rail, whether a
             name wraps or a private member has no HCP line at all. */
          <div style={{ display: 'flex', gap: 6, alignItems: 'center', minHeight: 35 }}>
            {who ? (
              <div style={{ display: 'flex', alignItems: 'center', flex: 'none' }}>
                <SquircleAvatar
                  src={avatarUrl}
                  userId={avatarUserId}
                  alt={who}
                  size={20}
                  hideRing
                />
              </div>
            ) : null}
            <div
              style={{
                flex: 1,
                minWidth: 0,
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                /* The reserved block: two name lines (2 x 13 x 1.2) plus the
                   caption line and its 2px lead, or one name line where the
                   caller has not opted into two. */
                minHeight: captionNameLines === 2 ? 51 : 35,
              }}
            >
              <div
                style={{
                  display: captionNameLines === 2 ? '-webkit-box' : 'block',
                  WebkitLineClamp: captionNameLines === 2 ? 2 : undefined,
                  WebkitBoxOrient: captionNameLines === 2 ? 'vertical' : undefined,
                  fontSize: 13,
                  fontWeight: 700,
                  letterSpacing: '-0.01em',
                  color: isOwn ? A.AMBER_DEEP : A.INK,
                  lineHeight: 1.2,
                  textOverflow: 'ellipsis',
                  whiteSpace: captionNameLines === 2 ? 'normal' : 'nowrap',
                  overflow: 'hidden',
                }}
              >
                {who || detail}
              </div>

              <div
                style={{
                  minHeight: 13,
                  marginTop: 2,
                  display: 'flex',
                  alignItems: 'baseline',
                  minWidth: 0,
                  overflow: 'hidden',
                  whiteSpace: 'nowrap',
                }}
              >
                {railCaptionLine}
              </div>
            </div>
          </div>
        ) : (

          <div style={{ display: 'flex', alignItems: 'center', gap: 4, ...(reserveTwoLines ? { minHeight: nameLines === 2 ? 32 : 16 } : null) }}>
            {who ? (
              <SquircleAvatar
                src={avatarUrl}
                userId={avatarUserId}
                alt={who}
                size={20}
                hideRing
              />
            ) : null}
            <div
              style={{
                flex: 1,
                minWidth: 0,
                fontSize: 13,
                fontWeight: 700,
                letterSpacing: '-0.01em',
                color: isOwn ? A.AMBER_DEEP : A.INK,
                lineHeight: 1.2,
                display: '-webkit-box',
                WebkitLineClamp: nameLines,
                WebkitBoxOrient: 'vertical',
                overflow: 'hidden',
              }}
            >
              {who || detail}
            </div>
          </div>
        )}

        {/* THE FACT LINE, WITH THE REACTION ON IT. The heart rides the LAST
            wording line the tile renders — the detail ("Bogey-free round") when
            there is one, otherwise the reference line — never a bare row of its
            own between the name and the wording. */}
        {(() => {
          const detailText = who ? detail : '';
          const factText = detailText || subline || '';
          const factIsSubline = !detailText && !!subline;
          const press = factIsSubline ? undefined : onDetailPress;
          return (
            <>
              {(!!factText || !!trailing) && (
                <div
                  style={{
                    display: 'flex',
                    alignItems: reserveTwoLines ? 'flex-start' : 'center',
                    gap: 6,
                    marginTop: factIsSubline ? 3 : 2,
                    /* Two reserved lines in a rail: 11px x 1.3 = 29, 12px x
                       1.32 = 32. factLines=1 (standing shelf) reserves the
                       single line the wording actually takes. One line
                       elsewhere, exactly as before. */
                    minHeight: reserveTwoLines
                      ? factLines === 2
                        ? factIsSubline ? 29 : 32
                        : factIsSubline ? 15 : 16
                      : 20,

                  }}
                >
                  <div
                    role={press ? 'button' : undefined}
                    onClick={
                      press
                        ? (ev) => {
                            ev.stopPropagation();
                            press();
                          }
                        : undefined
                    }
                    style={{
                      flex: 1,
                      minWidth: 0,
                      fontSize: factIsSubline ? 11 : 12,
                      fontWeight: 600,
                      lineHeight: factIsSubline ? 1.3 : 1.32,
                      /* THE SETTLED DARK MUTE, never a light-surface grey. The
                         old literal rgba(104,112,123,0.78) was a slate mid-grey
                         coloured for a light panel: 2.54:1 on A.PANEL. A.MUTE
                         reads 6.86:1 and matches the who-line's tier. */
                      color: A.MUTE,

                      display: '-webkit-box',
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: 'vertical',
                      overflow: 'hidden',
                      cursor: press ? 'pointer' : 'inherit',
                    }}
                  >
                    {factText}
                  </div>
                  {trailing}
                </div>
              )}

              {/* THE REFERENCE LINE (§3.5) — only when it did not already carry
                  the reaction above. No placeholder when absent, UNLESS the
                  rail opted in with reserveSubline (equal tile heights). */}
              {subline && !factIsSubline ? (
                <div
                  style={{
                    fontSize: SUBLINE_FS,
                    fontWeight: 600,
                    lineHeight: SUBLINE_LH,
                    color: A.MUTE,
                    marginTop: 3,
                    display: '-webkit-box',
                    WebkitLineClamp: reserveSubline ? 1 : 2,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden',
                  }}
                >
                  {subline}
                </div>
              ) : reserveSubline ? (
                <div aria-hidden style={{ height: SUBLINE_RESERVE, marginTop: 3 }} />
              ) : null}
            </>
          );
        })()}

        {footer}
      </div>
    </div>
  );
}

export default StandoutTile;

