  isPartWatched,
  isQuickHit,
  photosCaption,
  progressFraction,
  reasonLine,
  remainingLabel,
  spreadByCreator,
} from './watchRules';

/**
 * THE WATCH PAGE (BRIEF_WATCH_PAGE; the signed-off prototype is the spec).
 *
 * ORDER (K.8): chips, then Continue watching (All only, only when populated)
 * -> Quick hits -> long-form, with ER3 community after 3 then alternating
 * Shorts/community every ten cards. This page owns unseen allocation and
 * one extra clips-page attempt per Shorts slot; original coordinators stay shared.
 *
 * THE SHAPE IS THE TYPE. A video under QUICK_HIT_MAX is a portrait Quick Hit in
 * a rail; three minutes or more is full-width 16:9 long-form. Both reads are
 * fetched and split on duration alone, whichever RPC a row came from. No
 * "Quick hit" badge: the shape and the rail title already say it.
 *
 * K.7: every rail card is a top-aligned flex column with a fixed-height poster
 * (flex: none), because a <button> vertically centres its own contents.
 * ER1: own-item exclusion belongs here, before grouping/counts, never in shared
 * read hooks. Search preserves own items. Community owns a separate all-time
 * pool and opens the existing moment viewer in its displayed order.
 */

const INSET = 14;
const CW_W = 184;
const CW_H = 104;
export const QH_W = 156;
export const QH_H = 248;
/** WS5: the Shorts shelf glass badge props, shared with Filmed at your courses. */
export const SHELF_BADGE = { placement: 'top-right', top: 6, right: 6 } as const;
const CT_W = 124;

/* BRIEF_WATCH_SEE_ALL_IN_PLACE values with no shared token yet. */
const COUNT_INK = 'rgba(248,250,252,0.46)';

const cardButton: React.CSSProperties = {
  flex: 'none',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  justifyContent: 'flex-start',
  padding: 0,
  border: 0,
  background: 'transparent',
  textAlign: 'left',
  cursor: 'pointer',
  fontFamily: SANS,
  color: A.INK,
};

const clamp2: React.CSSProperties = {
  display: '-webkit-box',
  WebkitLineClamp: 2,
  WebkitBoxOrient: 'vertical',
  overflow: 'hidden',
};

const oneLine: React.CSSProperties = { whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' };

function Section({ title, kicker, onSeeAll, seeAll }: { title: string; kicker?: string; onSeeAll?: () => void; seeAll?: string }) {
  return (
    <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', padding: `18px ${INSET}px 9px` }}>
      <h2 style={{ margin: 0, fontSize: 17, fontWeight: 800, letterSpacing: '-0.3px', color: A.INK }}>
        {title}
        {kicker ? (
          <span style={{ marginLeft: 8, fontSize: 11, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: A.DIM }}>
            {kicker}
          </span>
        ) : null}
      </h2>
      {onSeeAll ? (
        <button
          type="button"
          onClick={onSeeAll}
          style={{ padding: 0, border: 0, background: 'transparent', cursor: 'pointer', fontFamily: SANS, fontSize: 13, fontWeight: 600, color: A.MUTE }}
        >
          {seeAll}
        </button>
      ) : null}
    </div>
  );
}

function Rail({ children, label }: { children: React.ReactNode; label: string }) {
  return (
    <div
      data-watch-rail={label}
      style={{ display: 'flex', gap: 10, padding: `0 ${INSET}px 2px`, overflowX: 'auto', maxWidth: '100%', scrollbarWidth: 'none', willChange: 'transform' }}
    >
      {children}
    </div>
  );
}

/** M.1 — Quick hits chip lays the same tile out as a 3-column grid; All keeps the rail. */
function QuickLayout({ grid, children }: { grid: boolean; children: React.ReactNode }) {
  if (!grid) return <Rail label="quick">{children}</Rail>;
  return (
    <div data-watch-grid="quick" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, alignItems: 'start', padding: `0 ${INSET}px 2px` }}>
      {children}
    </div>
  );
}

function Poster({ row, height, posterH, radius, autoplay, progress, aspect = '9 / 16', badge = 'glass', badgeTopRight = false, children }: { row: HubRpcRow; height: number | null; posterH: number; radius: number; autoplay: boolean; progress: number | null; aspect?: string; badge?: 'glass' | 'solid'; badgeTopRight?: boolean; children?: React.ReactNode }) {
  const poster = posterFor(row, posterH);
  const [failed, setFailed] = useState(false);
  const initial = getInitialsFromName(creatorName(row)) || '?';
  return (
    <span data-watch-frame style={{ display: 'block', position: 'relative', ...(height == null ? { aspectRatio: aspect } : { height }), flex: 'none', borderRadius: radius, overflow: 'hidden', background: A.PANEL }}>
      {poster && !failed ? (
        <img src={poster} alt="" loading="lazy" decoding="async" onError={() => setFailed(true)} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
      ) : (
        <PosterFallback initial={initial} size={20} />
      )}
      {autoplay ? <AutoplayLayer hlsUrl={hlsFor(row)} poster={poster} /> : null}
      <span style={{ position: 'absolute', inset: 0, zIndex: 2, pointerEvents: 'none' }}>
        {badge === 'solid' ? <SolidDurationBadge seconds={row.duration_seconds} /> : <GlassDurationBadge seconds={row.duration_seconds ?? null} {...(badgeTopRight ? SHELF_BADGE : null)} />}
      </span>
      {children}
      {progress != null ? <WatchProgressBar fraction={progress} /> : null}
    </span>
  );
}

export function WatchFeed({
  userId,
  onDepart,
  initialFilter = 'all',
  onOpenComments,
}: {
  userId: string | undefined;
  onDepart: () => void;
  /** ER1 entry selection maps community to Community; unknown values to For you. */
  initialFilter?: string;
  /** Opens ExploreMagazine's one mounted CommentsSheetV2 — never a second sheet here. */
  onOpenComments?: (postId: string) => void;
}) {
  const { t } = useTranslation('courses');
  const navigate = useNavigate();
  const [filter, setFilter] = useState<WatchFilter>(() => mapWatchFilter(initialFilter));
  const [query, setQuery] = useState('');
  /* WS3 — one spotlight pick per Explore visit: minted on mount, held across chips. */
  const [visitKey] = useState(() => `${Date.now()}:${Math.random().toString(36).slice(2)}`);

  /* THE SEARCH IS SERVER-SIDE: both RPCs take p_search_query. */
  const search = query.trim().length >= 2 ? query.trim() : null;
  const searching = !!search;
  const communityView = filter === 'community' && !searching;
  const contentFilter = searching && filter === 'community' ? 'all' : filter;

  const vParams = videoParams(filter);
  const cParams = clipParams(filter);
  const videos = useWatchVideos({ userId, mode: vParams.mode, search });
  const clips = useWatchClips({ userId, mode: cParams.mode, filter: cParams.filter, search });
  const onAll = allOnly(filter, searching);
  const moments = useMomentsOfTheWeek(30, { enabled: onAll && !!userId, candidateLimit: 72 });
  const community = useMomentsOfTheWeek(null, { enabled: filter === 'community' && !!userId, candidateLimit: 120 });
  const communityItems = useMemo(() => (community.data ?? [])
    .filter((m) => !userId || searching || m.post?.userId !== userId)
    .slice().sort((a, b) => new Date(b.post.createdAt).getTime() - new Date(a.post.createdAt).getTime()),
  [community.data, userId, searching]);
  const progress = useWatchProgress(userId);
  const { data: myCourses } = useUserAnalyticsCourses({ enabled: !!userId });
  const playedIds = useMemo(
    () => new Set((myCourses ?? []).filter((c) => c.rounds_count > 0).map((c) => c.course_id)),
    [myCourses],
  );
  const onYourCourse = useCallback((row: HubRpcRow) => !!row.course_id && playedIds.has(row.course_id), [playedIds]);

  /* ONE POOL, SPLIT ON DURATION. A row is the same video whichever read it came from. */
  const rawRows = useMemo(() => {
    const seen = new Set<string>();
    const out: HubRpcRow[] = [];
    for (const row of [...(videos.data?.pages ?? []).flat(), ...(clips.data?.pages ?? []).flat()] as HubRpcRow[]) {
      if (!row?.post_id || seen.has(row.post_id)) continue;
      if (userId && !searching && (row.post_actor_type ?? row.actor_type ?? 'personal') === 'personal'
        && (row.post_user_id ?? row.actor_id) === userId) continue;
      seen.add(row.post_id);
      out.push(row);
    }
    return out;
  }, [videos.data, clips.data, userId, searching]);
  const details = usePostVideoDetails(useMemo(() => singleVideoPostIds(toFeedPosts(rawRows)), [rawRows]));
  const rows = useMemo(() => rawRows.map(row => ({ ...row, video_details_title: details.get(row.post_id)?.title ?? null })), [rawRows, details]);

  const saved = progress.data;
  /* M.1 — one tile, two layouts: grid on the Quick hits chip, rail everywhere else. */
  const quickGrid = filter === 'quick';
  const quickRows = useMemo(() => (showsQuickHits(contentFilter) ? rows.filter((r) => isQuickHit(r.duration_seconds)) : []), [rows, contentFilter]);
  const topQuickRows = onAll ? quickRows.slice(0, SHORTS_SHELF_COUNT) : quickRows;
  const longRows = useMemo(
    () =>
      showsLongForm(contentFilter)
        ? spreadByCreator(
            rows.filter((r) => !isQuickHit(r.duration_seconds)),
            (r) => String(r.post_user_id ?? r.actor_id ?? creatorName(r)),
          )
        : [],
    [rows, contentFilter],
  );
  const continueRows = useMemo(
    () => (onAll && saved ? rows.filter((r) => isPartWatched(r, saved.get(r.post_id))) : []),
    [onAll, rows, saved],
  );

  const barFor = (row: HubRpcRow) => {
    const p = saved?.get(row.post_id);
    return isPartWatched(row, p) ? progressFraction(row, p) : null;
  };

  const quickPosts = useMemo(() => toFeedPosts(quickRows), [quickRows]);
  const longPosts = useMemo(() => toFeedPosts(longRows), [longRows]);
  /* L.2 — the like control lives on the long-form card (BRIEF_WATCH_VIDEO_ROW_REACTIONS). */
  const { activeActor } = useActiveActor();
  const { handleLike, getActiveLikeState } = useClubhouseLikes({ userId, activeActor });
  const likeAvailable = !!userId && !!activeActor;
  const continuePosts = useMemo(() => toFeedPosts(continueRows), [continueRows]);

  useEffect(() => {
    analyticsEvents.track('amateur_watch_filter_changed', { filter, searching });
  }, [filter, searching]);

  const open = useCallback(
    (kind: 'video' | 'clip' | 'continue', posts: ReturnType<typeof toFeedPosts>, list: HubRpcRow[], index: number) => {
      analyticsEvents.track('amateur_watch_tapped', { kind, filter });
      onDepart();
      const row = list[index];
      const resume = saved?.get(row?.post_id ?? '');
      openWithOrigin({
        posts,
        index,
        originEl: null,
        posterUrl: row?.poster_url ?? null,
        openedFrom: kind === 'clip' ? 'amateur-clips' : 'amateur-watch',
        forceStartAtZero: true,
        /* K.1: a part-watched video resumes where the member left it. */
        resumeAtSeconds: row && isPartWatched(row, resume) ? resume?.position ?? null : null,
      });
    },
    [filter, onDepart, saved],
  );

  /* PAGINATION: one sentinel, one page per trigger, from one read. Every view except Quick hits
     pages the long-form read. BF.0 — Quick hits pages the clip read until it is exhausted, THEN
     the videos read, because sub-3-minute videos live throughout that feed, not only on page one.
     Clips first: they are the dense source; videos yield a handful per page. */
  const sentinelRef = useRef<HTMLDivElement | null>(null);
  const driver = filter === 'quick' ? (clips.hasNextPage ? clips : videos) : videos;
  useEffect(() => {
    const el = sentinelRef.current;
    if (!el || communityView || !driver.hasNextPage || driver.isFetchingNextPage) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) void driver.fetchNextPage();
      },
      { rootMargin: '600px 0px' },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [driver, communityView]);

  /* ER1 — For you / Shorts / Long form / Community, in that order. */
  const chipLabel = (key: (typeof WATCH_CHIPS)[number]) =>
    key === 'all'
      ? t('amateur.watch.chip.all', 'For you')
      : key === 'quick'
        ? t('amateur.watch.chip.quick', 'Shorts')
        : key === 'long' ? t('amateur.watch.chip.long', 'Long form')
          : t('amateur.watch.chip.community', 'Community');
  const chips = WATCH_CHIPS.map((key) => ({ id: key, label: chipLabel(key) }));

  const openMoment = (moment: Moment, list: Moment[]) => {
    analyticsEvents.track('amateur_watch_tapped', { kind: 'moment', filter });
    onDepart();
    const { posts, index } = momentViewerPosts(list, moment);
    openWithOrigin({
      posts,
      index,
      originEl: null,
      posterUrl: moment.thumbnail,
      mediaIndex: moment.mediaIndex ?? 0,
      mediaId: moment.mediaId ?? null,
      openedFrom: 'amateur-moments',
      forceStartAtZero: true,
    });
  };

  /* K.6 — ONE ENTRY PER MEMBER, labelled with who, then where. */
  const members = useMemo(() => groupByMember((moments.data ?? []).filter((m) => !userId || searching || m.post?.userId !== userId), (m) => m.post?.userId ?? null), [moments.data, userId, searching]);
  const attemptedClipRails = useRef(new Set<number>());
  const pendingClipRails = useRef(new Set<number>());
  const [railReadVersion, setRailReadVersion] = useState(0);
  const woven = useMemo(() => {
    const rails = new Map<number, { kind: 'shorts' | 'community'; shorts: HubRpcRow[]; members: typeof members }>();
    const shownShorts = new Set(topQuickRows.map(row => row.post_id));
    const shownMembers = new Set<string>();
    const replenish: number[] = [];
    if (!onAll) return { rails, replenish };
    for (let position = RAIL_EVERY, slot = 0; position < longRows.length; position += WOVEN_RAIL_INTERVAL, slot++) {
      if (slot % 2 === 0) {
        const next = members.filter(item => !shownMembers.has(item.lead.post.userId)).slice(0, SHORTS_SHELF_COUNT);
        if (next.length < WOVEN_RAIL_MIN) continue;
        next.forEach(item => shownMembers.add(item.lead.post.userId));
        rails.set(position, { kind: 'community', shorts: [], members: next });
      } else {
        const next = quickRows.filter(row => !shownShorts.has(row.post_id)).slice(0, SHORTS_SHELF_COUNT);
        if (pendingClipRails.current.has(position)) {
          next.forEach(row => shownShorts.add(row.post_id));
          continue;
        }
        if (next.length < SHORTS_SHELF_COUNT && clips.hasNextPage && !attemptedClipRails.current.has(position)) {
          replenish.push(position);
          // Allocate this window even while waiting, so later slots cannot steal it.
          next.forEach(row => shownShorts.add(row.post_id));
          continue;
        }
        if (next.length < WOVEN_RAIL_MIN) continue;
        next.forEach(row => shownShorts.add(row.post_id));
        rails.set(position, { kind: 'shorts', shorts: next, members: [] });
      }
    }
    return { rails, replenish };
  }, [onAll, longRows, quickRows, members, clips.hasNextPage, railReadVersion]);
  useEffect(() => {
    const position = woven.replenish[0];
    if (!onAll || position == null || clips.isFetchingNextPage) return;
    attemptedClipRails.current.add(position);
    pendingClipRails.current.add(position);
    void clips.fetchNextPage().catch(() => undefined).finally(() => {
      pendingClipRails.current.delete(position);
      setRailReadVersion(version => version + 1);
    });
  }, [onAll, woven, clips.isFetchingNextPage, clips.fetchNextPage]);

  const communityRail = (items: typeof members, position: number) => {
    if (moments.isError) {
      return (
        <ShelfRetry
          heading={t('amateur.watch.rail.community', 'From the community')}
          label={t('amateur.stream.failed', 'This did not load.')}
          action={t('amateur.stream.retry', 'Try again')}
          onRetry={() => void moments.refetch()}
        />
      );
    }
    if (!moments.isFetched) return <ShelfShell tileW={CT_W} tileH={CT_W} />;
    if (items.length < WOVEN_RAIL_MIN) return null;
    return (
      <div data-woven-after={position} data-woven-kind="community" style={{ paddingBottom: 8 }}>
        {/* CM1 — Community shares the other shelves' in-place chip selection. */}
        <Section
          title={position === RAIL_EVERY ? t('amateur.watch.rail.community', 'From the community') : 'More from the community'}
          seeAll={t('amateur.watch.seeAll', 'See all')}
          onSeeAll={() => {
            analyticsEvents.track('amateur_shelf_see_all', { kind: 'community', surface: 'watch' });
            setFilter('community');
            scrollPageToTop();
          }}
        />
        <Rail label="community">
          {items.map(({ lead, count }) => (
            <div key={`member:${lead.key}`} data-watch-card="community" data-watch-member={lead.post.userId} style={{ ...cardButton, width: CT_W, cursor: 'default' }}>
              <div data-watch-frame style={{ width: CT_W, height: CT_W, flex: 'none', borderRadius: 11, overflow: 'hidden', position: 'relative' }}>
                <MomentTile
                  moment={lead}
                  radius={11}
                  initialsSize={14}
                  labelSize={11}
                  labelInset={8}
                  labelled={false}
                  autoplayGroup="amateur-watch-moments"
                  style={{ width: '100%', height: '100%', display: 'block' }}
                  onPress={() => openMoment(lead, items.map((x) => x.lead))}
                />
              </div>
              <span style={{ ...oneLine, marginTop: 7, fontSize: 12.5, fontWeight: 600 }}><InlineProMemberName userId={lead.post?.actorType === 'personal' ? lead.post.userId : undefined}>{lead.post?.displayName || lead.post?.username}</InlineProMemberName></span>
              <span style={{ ...oneLine, marginTop: 2, fontSize: 11.5, color: A.DIM }}>{photosCaption(lead.courseName, count)}</span>
            </div>
          ))}
        </Rail>
      </div>
    );
  };

  const settled = videos.isFetched && clips.isFetched;
  const loading = !settled && rows.length === 0;
  const nothing = settled && quickRows.length === 0 && longRows.length === 0 && !videos.isError && !clips.isError;
  const selectShorts = () => {
    analyticsEvents.track('amateur_shelf_see_all', { kind: 'clips', surface: 'watch' });
    setFilter('quick');
    scrollPageToTop();
  };
  const shortTiles = (items: HubRpcRow[]) => items.map(row => {
    const index = quickRows.findIndex(item => item.post_id === row.post_id);
    const who = creatorName(row);
    return <button key={`qh:${row.post_id}`} type="button" data-watch-card="quick" data-watch-short={row.post_id} onClick={() => open('clip', quickPosts, quickRows, index)} style={{ ...cardButton, width: QH_W, minWidth: 0 }}>
      <Poster row={row} height={QH_H} posterH={480} radius={12} autoplay progress={barFor(row)} badgeTopRight />
      <span style={{ ...clamp2, marginTop: 7, fontSize: 12, fontWeight: 600, lineHeight: 1.3, minHeight: 'calc(12px * 1.3 * 2)' }}>{videoTitle(row, t('amateur.watch.untitled', 'Untitled video'))}</span>
      {who ? <span data-watch-sub="creator" style={{ ...oneLine, marginTop: 3, fontSize: 11, color: A.DIM }}><InlineProMemberName userId={postAuthor(row).kind === 'personal' ? postAuthor(row).id : undefined}>{who}</InlineProMemberName></span> : null}
      {onYourCourse(row) && row.course_name ? <span style={{ ...oneLine, marginTop: 3, fontSize: 11, color: A.AMBER }}>{row.course_name}</span> : null}
    </button>;
  });
  /* Q.1: the Quick hits heading has ONE home, rendered by both the loading and rows branches,
     so the heading seen while loading can never drift from the one seen once loaded. */
  const quickSection = (
    /* WS2 §2 — today's Quick hits rail, renamed Shorts, in the Rounds this week heading pattern. */
    <ShelfHeading
      title={t('amateur.watch.rail.shorts', 'Shorts')}
      sub={t('amateur.watch.rail.shortsSub', 'Under three minutes')}
      /* BC.0: See all selects the Shorts chip in place; none once it is active. */
      seeAll={filter === 'quick' ? undefined : t('amateur.watch.seeAll', 'See all')}
      onSeeAll={filter === 'quick' ? undefined : selectShorts}
    />
  );

  /* BE.1 — the count always renders and is always true: while either read can still page,
     it says how many are on screen; once both are exhausted the loaded length is the total.
     No order word: clips read `trending`, videos read `latest`, and the rows are merged. */
  const quickMorePending = clips.hasNextPage || videos.hasNextPage;
  const quickHeading = (
    <>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 9, padding: '16px 16px 2px' }}>
        <h2 style={{ margin: 0, fontSize: 17, fontWeight: 750, letterSpacing: '-0.01em', color: A.INK }}>
          {t('amateur.watch.rail.quick', 'Quick hits')}
        </h2>
        <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: '0.13em', textTransform: 'uppercase', color: A.DIM }}>
          {t('amateur.watch.rail.quickKicker', 'Under 3 min')}
        </span>
      </div>
      {quickRows.length > 0 ? (
        <div data-watch-count style={{ padding: '2px 16px 12px', fontSize: 11.5, color: COUNT_INK, fontVariantNumeric: 'tabular-nums' }}>
          {quickMorePending
            ? t('amateur.watch.quickShowing', 'Showing {{count}}', { count: quickRows.length })
            : t('amateur.watch.quickCount', '{{count}} clips', { count: quickRows.length })}
        </div>
      ) : (
        <div style={{ height: 12 }} />
      )}
    </>
  );

  return (
    <div style={{ fontFamily: SANS }}>
      <ExploreTopControls
          query={query}
          onQuery={setQuery}
          placeholder={t('amateur.watch.searchPlaceholder', 'Search videos and creators')}
          options={chips}
          value={filter}
          onChange={(next) => {
            const to = next as WatchFilter;
            if (to !== filter) analyticsEvents.track('watch_chip_changed', { from: filter, to });
            setFilter(to);
          }}
          ariaLabel={t('amateur.watch.filters', 'Watch filters')}
      />

      {/* FW1 changes only the lead slot; thin/error reads retain WatchLead. */}
      {onAll ? <WatchFeaturedSlot userId={userId} onDepart={onDepart} onOpenComments={onOpenComments} selectShorts={selectShorts} /> : null}

      {communityView ? <>
        <p className="explore-community-sub">Photos and clips from members</p>
        {community.isError ? <ShelfRetry heading={chipLabel('community')} label={t('amateur.stream.failed', 'This did not load.')} action={t('amateur.stream.retry', 'Try again')} onRetry={() => void community.refetch()} />
          : !community.isFetched ? <div data-watch-grid-shell="community" className="explore-community-grid" aria-hidden>{Array.from({ length: 6 }, (_, i) => <div key={i} className="explore-community-square clb-shimmer-dark" />)}</div>
          : communityItems.length ? <div data-watch-grid="community" className="explore-community-grid">
            {communityItems.map((moment) => <div key={moment.key} data-community-item={moment.key} className="explore-community-item">
              <div className="explore-community-frame">
                <MomentTile moment={moment} radius={12} initialsSize={14} labelSize={11} labelInset={8} labelled={false} autoplay={false} onPress={() => openMoment(moment, communityItems)} />
                {moment.mediaType === 'video' ? <SolidDurationBadge seconds={moment.durationSeconds} /> : null}
              </div>
              <span className="explore-community-name"><InlineProMemberName userId={moment.post?.actorType === 'personal' ? moment.post.userId : undefined}>{moment.post?.displayName || moment.post?.username}</InlineProMemberName></span>
              <span className="explore-community-course">{moment.courseName}</span>
            </div>)}
          </div> : <p style={{ padding: '30px 24px', textAlign: 'center', color: A.MUTE }}>{t('amateur.watch.emptyFilter', 'Nothing here yet. Try another filter.')}</p>}
      </> : <>
          {/* K.2 — CONTINUE WATCHING: All only, only when something is part-watched. */}
          {continueRows.length > 0 ? (
            <>
              <Section title={t('amateur.watch.rail.continue', 'Continue watching')} />
              <Rail label="continue">
                {continueRows.map((row, index) => (
                  <button key={`cw:${row.post_id}`} type="button" data-watch-card="continue" onClick={() => open('continue', continuePosts, continueRows, index)} style={{ ...cardButton, width: CW_W }}>
                    <Poster row={row} height={CW_H} posterH={360} radius={10} autoplay={false} progress={barFor(row)} />
                    <span style={{ ...clamp2, marginTop: 7, fontSize: 12.5, fontWeight: 600, lineHeight: 1.32 }}>
                      {videoTitle(row, t('amateur.watch.untitled', 'Untitled video'))}
                    </span>
                    <span style={{ marginTop: 4, fontSize: 11.5, fontWeight: 700, color: A.AMBER }}>{remainingLabel(row, saved?.get(row.post_id))}</span>
                  </button>
                ))}
              </Rail>
            </>
          ) : null}

          {/* K.3 — QUICK HITS. The rail carries the GLASS duration badge, as every Poster always has. The grid carries the SOLID badge instead: at 3-column width a translucent badge over a bright poster is unreadable, and solid 62% black is legible whatever is behind it. An earlier version of this comment claimed the rail had no badge; it never matched the code. */}
          {clips.isError && quickRows.length === 0 && showsQuickHits(contentFilter) ? (
            <ShelfRetry
              heading={t('amateur.watch.rail.quick', 'Quick hits')}
              label={t('amateur.stream.failed', 'This did not load.')}
              action={t('amateur.stream.retry', 'Try again')}
              onRetry={() => void clips.refetch()}
            />
          ) : quickRows.length > 0 && quickGrid ? (
            <>
              {quickHeading}
              <div data-watch-grid="quick" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, alignItems: 'start', padding: '0 14px' }}>
                {quickRows.map((row, index) => {
                  const who = creatorName(row);
                  return (
                    <button key={`qh:${row.post_id}`} type="button" data-watch-card="quick" onClick={() => open('clip', quickPosts, quickRows, index)} style={{ ...cardButton, width: '100%', minWidth: 0 }}>
                      {/* N.2: no autoplay in a 3-across grid. */}
                      <Poster row={row} height={null} aspect="126 / 224" posterH={480} radius={12} autoplay={false} progress={barFor(row)} badge="solid" />
                      <span style={{ ...clamp2, marginTop: 7, fontSize: 12.5, fontWeight: 600, lineHeight: 1.32, minHeight: 'calc(12.5px * 1.32 * 2)' }}>
                        {videoTitle(row, t('amateur.watch.untitled', 'Untitled video'))}
                      </span>
                      {who ? <span data-watch-sub="creator" style={{ ...oneLine, marginTop: 3, fontSize: 11.5, color: A.DIM }}><InlineProMemberName userId={postAuthor(row).kind === 'personal' ? postAuthor(row).id : undefined}>{who}</InlineProMemberName></span> : null}
                      {onYourCourse(row) && row.course_name ? (
                        <span style={{ ...oneLine, marginTop: 3, fontSize: 11.5, color: A.AMBER }}>{row.course_name}</span>
                      ) : null}
                    </button>
                  );
                })}
              </div>
            </>
          ) : quickRows.length > 0 ? (
            <>
              {quickSection}
              <QuickLayout grid={false}>
                {shortTiles(topQuickRows)}
              </QuickLayout>
            </>
          ) : loading && showsQuickHits(contentFilter) ? (
            /* P.1: the heading is static text, so it renders during loading exactly as it
               will once loaded — the skeleton then holds the tiles' place and nothing shifts.
               A settled chip with no rows renders no heading (falls to null below). */
            <>
              {quickGrid ? quickHeading : quickSection}
              {quickGrid ? <GridShell inset={INSET} radius={12} /> : <ShelfShell tileW={QH_W} tileH={QH_H} heading={false} />}
            </>
          ) : null}

          {/* WS2 — FILMED AT YOUR COURSES and BY REGION: For you only, directly after Quick
              hits and before Watch. Both hide themselves for guests and thin data. */}
          {onAll ? (
            <>
              <CourseVideosShelf userId={userId} onDepart={onDepart} />
              <RegionsShelf userId={userId} />
              {/* WS3 — CREATOR TO FOLLOW and TOP 100 ON FILM: For you only, after By
                  region and before Long form. Both hide for guests and thin data. */}
              <CreatorSpotlight userId={userId} visitKey={visitKey} onDepart={onDepart} />
              <Top100FilmShelf userId={userId} onDepart={onDepart} />
            </>
          ) : null}

          {/* K.4 — THE LONG-FORM COLUMN, with the community rail once after the third card. */}
          {videos.isError && showsLongForm(contentFilter) ? (
            <div style={{ paddingTop: 18 }}>
              <ShelfRetry
                heading={t('amateur.watch.rail.videos', 'Videos')}
                label={t('amateur.stream.failed', 'This did not load.')}
                action={t('amateur.stream.retry', 'Try again')}
                onRetry={() => void videos.refetch()}
              />
            </div>
          ) : null}
          {longRows.length > 0 ? (
            <>
              {/* WS3 §4 — today's Watch column, renamed Long form, in Shorts' heading pattern. */}
              {/* WS3.1 — See all (mock wins): selects the Long form chip in place and scrolls
                  to the top of the feed; none once the chip is active, like Shorts. */}
              <ShelfHeading
                title={t('amateur.watch.rail.longForm', 'Long form')}
                sub={t('amateur.watch.rail.longFormSub', 'Three minutes and over')}
                seeAll={filter === 'long' ? undefined : t('amateur.watch.seeAll', 'See all')}
                onSeeAll={filter === 'long' ? undefined : () => {
                  analyticsEvents.track('amateur_shelf_see_all', { kind: 'videos', surface: 'watch' });
                  setFilter('long');
                  scrollPageToTop();
                }}
              />
              {longRows.map((row, index) => {
                const p = saved?.get(row.post_id);
                const part = isPartWatched(row, p);
                return (
                  <div key={`lf:${row.post_id}`} style={{ marginBottom: 4 }}>
                    <VideoCard
                      row={row}
                      onPress={() => open('video', longPosts, longRows, index)}
                      courseChip={row.review_course_id && row.review_course_name
                        ? { name: shortCourseName(row.review_course_name), onPress: () => navigate(`/courses/${row.review_course_id}`) }
                        : null}
                      progress={barFor(row)}
                      reason={reasonLine({
                        partWatched: part,
                        remaining: remainingLabel(row, p),
                        courseName: row.course_name,
                        onYourCourse: onYourCourse(row),
                        fromFollowed: row.creator_relation === 'following' || row.creator_relation === 'friend',
                      })}
                      engagement={(() => {
                        /* longPosts[index] is 1:1 with longRows[index] (load-bearing). */
                        const post = longPosts[index] ?? null;
                        const like = getActiveLikeState(post);
                        return {
                          likeAvailable,
                          liked: like.isLiked,
                          likeCount: like.count,
                          own: !!userId && (row.post_user_id ?? row.actor_id) === userId,
                          onToggleLike: () => handleLike(post),
                          commentCount: Number(row.comment_count ?? 0),
                          onOpenComments: () => onOpenComments?.(row.post_id),
                        };
                      })()}
                    />
                    {(() => {
                      const position = index + 1;
                      const rail = woven.rails.get(position);
                      if (rail?.kind === 'community') return communityRail(rail.members, position);
                      if (rail?.kind === 'shorts') return <div data-woven-after={position} data-woven-kind="shorts">
                        <ShelfHeading title="More shorts" sub={t('amateur.watch.rail.shortsSub', 'Under three minutes')} seeAll={t('amateur.watch.seeAll', 'See all')} onSeeAll={selectShorts} />
                        <QuickLayout grid={false}>{shortTiles(rail.shorts)}</QuickLayout>
                      </div>;
                      return null;
                    })()}
                  </div>
                );
              })}
            </>
          ) : null}

          {nothing ? (
            <p style={{ margin: 0, padding: '30px 24px', textAlign: 'center', fontSize: 13.5, lineHeight: 1.5, color: A.MUTE }}>
              {t('amateur.watch.emptyFilter', 'Nothing here yet. Try another filter.')}
            </p>
          ) : null}
        </>}

      <div ref={sentinelRef} aria-hidden style={{ height: 1 }} />
    </div>
  );
}

export default WatchFeed;

import { InlineProMemberName } from '@/features/pro-verification/InlineProMemberName';
/**
 * WS1 §3 — THE LEAD (watch-s1.html, signed off — the mock is the spec).
 *
 * For you only, after the Creators row. One video, picked by get_watch_lead:
 * the newest creator video from the last 7 days, otherwise the most-liked of
 * the last 30. Upright sources lead tall (mock A, 440px media with the words
 * over a bottom gradient); landscape sources lead wide (mock B, 16:9 with the
 * words underneath). Hidden when the read returns no row; while loading a
 * 440px rounded skeleton holds the place and collapses only when the section
 * is dropped (the expand-outwards rule).
 *
 * PLAYBACK IS THE PAGE'S OWN. The lead registers with the SAME
 * registerRailVideo coordinator every Watch and All video uses, so the
 * 60%-visible rule and the one-playing-stream rule are the coordinator's,
 * not a second implementation; attachTileHls does the HLS/stream handling.
 * The mute button (upright only, as the mock draws it) toggles sound for this
 * card alone. The media tap opens the post in the existing fullscreen viewer
 * through openWithOrigin, exactly as a Watch row tap does.
 */
import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { MapPin, Volume2, VolumeX } from 'lucide-react';

import { A, SANS } from '@/features/courses/components/holes/analytical/tokens';
import { SquircleAvatar } from '@/components/ui/SquircleAvatar';
import { ProOrVerifiedMark } from '@/features/pro-verification/ProOrVerifiedMark';
import { autoplayBlocked } from '@/components/explore-tab-new/courseled/reviewVideoAutoplay';
import { registerRailVideo } from '@/components/explore-tab-new/courseled/mediaRailAutoplay';
import { attachTileHls } from '@/components/explore-tab-new/courseled/tileHlsPlayer';
import { generateStreamHlsUrl } from '@/config/cloudflareStream';
import { usePrefersReducedMotion } from '@/hooks/usePrefersReducedMotion';
import { toFeedPosts, type HubRpcRow } from '@/features/watch-v2/utils/toFeedPost';
import { openWithOrigin } from '@/lib/openWithOrigin';
import { formatDuration } from '@/features/watch-v2/utils/formatDuration';
import { formatRelativeWithSeconds } from '@/i18n/format';
import { shortCourseName } from '@/lib/courses/shortCourseName';
import { getProfilePathById } from '@/lib/profileRoutes';
import { getThumbnailUrl } from '@/utils/thumbnail';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { useWatchLead, type WatchLeadRow } from './useWatchLead';
import { leadCaption, leadKickerKey, leadShape } from './watchTopRules';
import { attachPosterPreview } from './posterPreview';

/** watch_lead_viewed fires once per session per lead post, at 50% visible. */
const VIEWED = new Set<string>();

/** Test-only: clears the session view set. The app never calls this. */
export function resetWatchLeadSessionForTests() {
  VIEWED.clear();
}

const TEXT_SHADOW = '0 1px 4px rgba(0,0,0,0.6)';

function leadHubRow(row: WatchLeadRow): HubRpcRow {
  return {
    post_id: row.post_id,
    post_content: row.caption,
    post_created_at: row.created_at,
    post_user_id: row.actor_type === 'personal' ? row.actor_id : null,
    post_actor_type: row.actor_type,
    post_actor_id: row.actor_id,
    actor_id: row.actor_id,
    actor_type: row.actor_type,
    media_type: 'video',
    media_url: row.media_url,
    poster_url: row.poster_url,
    hls_url: row.hls_url,
    stream_id: row.stream_id,
    duration_seconds: row.duration_seconds,
    width: row.width,
    height: row.height,
    creator_username: row.actor_type === 'personal' ? row.handle : null,
    creator_display_name: row.display_name,
    creator_avatar_url: row.avatar_url,
    creator_is_verified: row.is_verified,
    business_name: row.actor_type === 'business' ? row.display_name : null,
    business_logo_url: row.actor_type === 'business' ? row.avatar_url : null,
    business_is_verified: row.actor_type === 'business' ? row.is_verified : null,
    like_count: row.like_count,
    comment_count: row.comment_count,
    course_id: row.course_id,
    course_name: row.course_name,
  };
}

export function WatchLead({ userId, onDepart }: { userId: string | undefined; onDepart: () => void }) {
  const lead = useWatchLead(!!userId);
  if (!userId) return null;
  if (!lead.isFetched) {
    /* The skeleton only shrinks when the section is dropped. */
    return (
      <div
        data-watch-lead="skeleton"
        aria-hidden
        style={{ margin: '22px 16px 0', height: 440, borderRadius: 20, background: '#17171B' }}
      />
    );
  }
  if (lead.isError || !lead.data) return null;
  return <LeadCard row={lead.data} onDepart={onDepart} />;
}

function LeadCard({ row, onDepart }: { row: WatchLeadRow; onDepart: () => void }) {
  const { t } = useTranslation('courses');
  const navigate = useNavigate();
  const shape = leadShape(row.width, row.height);
  const upright = shape === 'upright';
  const kicker = leadKickerKey(row.reason);
  const caption = leadCaption(row.caption, row.course_name);
  const age = formatRelativeWithSeconds(row.created_at);
  const likes = t('amateur.watch.lead.likes', '{{count}} likes', { count: row.like_count });
  const course = row.course_name ? shortCourseName(row.course_name) : '';

  const poster = row.poster_url ?? (row.stream_id ? getThumbnailUrl({ streamId: row.stream_id, height: 720 }) : null);
  const hls = row.hls_url ?? (row.stream_id ? generateStreamHlsUrl(row.stream_id) : null);

  /* Muted autoplay in place through the page's one coordinator; the mute
     button toggles sound for this card only. */
  const reducedMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [active, setActive] = useState(false);
  const [playing, setPlaying] = useState(false);
  const [failed, setFailed] = useState(false);
  const [muted, setMuted] = useState(true);
  const mount = !!hls && !failed && !autoplayBlocked(reducedMotion);

  useEffect(() => {
    const el = hostRef.current;
    if (!mount || !el) return;
    return registerRailVideo(el, setActive);
  }, [mount]);

  useEffect(() => {
    const video = videoRef.current;
    if (!active || !video || !hls) return;
    video.muted = muted;
    const disposePreview = attachPosterPreview(video, poster, setPlaying);
    const attachment = attachTileHls(video, hls, () => setFailed(true));
    return () => {
      disposePreview();
      video.pause();
      attachment.detach();
    };
    // muted is applied live by the toggle below; re-attaching on every toggle
    // would restart the stream.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, hls, poster]);

  const toggleMute = () => {
    setMuted((prev) => {
      const next = !prev;
      if (videoRef.current) videoRef.current.muted = next;
      return next;
    });
  };

  /* watch_lead_viewed — once per session per post, at 50% visible. */
  const rootRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    const el = rootRef.current;
    if (!el || VIEWED.has(row.post_id)) return;
    const obs = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting && !VIEWED.has(row.post_id)) {
            VIEWED.add(row.post_id);
            analyticsEvents.track('watch_lead_viewed', { reason: row.reason, shape });
            obs.disconnect();
          }
        }
      },
      { threshold: 0.5 },
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [row.post_id, row.reason, shape]);

  const openPost = () => {
    analyticsEvents.track('watch_lead_opened', { reason: row.reason });
    onDepart();
    openWithOrigin({
      posts: toFeedPosts([leadHubRow(row)]),
      index: 0,
      originEl: null,
      posterUrl: poster,
      openedFrom: 'amateur-watch',
      forceStartAtZero: true,
    });
  };

  const openCreator = () => {
    navigate(
      row.actor_type === 'business'
        ? `/business/${row.handle || row.actor_id}`
        : getProfilePathById(row.actor_id, undefined, row.handle),
    );
  };

  const openCourse = () => {
    if (row.course_id) navigate(`/courses/${row.course_id}`);
  };

  const kickerLabel =
    kicker === 'new'
      ? t('amateur.watch.lead.kickerNew', 'New this week')
      : t('amateur.watch.lead.kickerLiked', 'Most liked this month');

  const kickerEl = (
    <span
      data-watch-lead="kicker"
      style={{
        position: 'absolute',
        left: 14,
        top: 14,
        zIndex: 3,
        height: 26,
        padding: '0 10px',
        borderRadius: 999,
        background: 'rgba(0,0,0,0.5)',
        display: 'flex',
        alignItems: 'center',
        fontSize: 11,
        fontWeight: 800,
        letterSpacing: '0.12em',
        textTransform: 'uppercase',
        color: A.INK,
        pointerEvents: 'none',
      }}
    >
      {kickerLabel}
    </span>
  );

  const durationEl = (
    <span
      data-watch-lead="duration"
      style={{
        position: 'absolute',
        right: 12,
        ...(upright ? { top: 14 } : { bottom: 12 }),
        zIndex: 3,
        background: 'rgba(0,0,0,0.6)',
        borderRadius: 7,
        padding: '3px 7px',
        fontSize: 12,
        fontWeight: 700,
        fontVariantNumeric: 'tabular-nums',
        color: A.INK,
        pointerEvents: 'none',
      }}
    >
      {formatDuration(row.duration_seconds)}
    </span>
  );

  const muteEl = upright ? (
    <button
      type="button"
      data-watch-lead="mute"
      aria-label={muted ? t('amateur.watch.lead.unmute', 'Unmute') : t('amateur.watch.lead.mute', 'Mute')}
      aria-pressed={!muted}
      onClick={(e) => {
        e.stopPropagation();
        toggleMute();
      }}
      style={{
        position: 'absolute',
        right: 12,
        bottom: 14,
        zIndex: 3,
        width: 34,
        height: 34,
        borderRadius: 999,
        border: 0,
        background: 'rgba(0,0,0,0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: A.INK,
        cursor: 'pointer',
      }}
    >
      {muted ? <VolumeX size={16} strokeWidth={2} /> : <Volume2 size={16} strokeWidth={2} />}
    </button>
  ) : null;

  const courseChip = (onDark: boolean) =>
    row.course_id && course ? (
      <button
        type="button"
        data-watch-lead="course"
        onClick={(e) => {
          e.stopPropagation();
          openCourse();
        }}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 5,
          marginTop: 10,
          height: 26,
          padding: '0 10px',
          borderRadius: 999,
          border: 0,
          background: onDark ? 'rgba(255,255,255,0.16)' : '#1E1E23',
          color: onDark ? A.INK : 'rgba(248,250,252,0.78)',
          fontSize: 12,
          fontWeight: 600,
          fontFamily: SANS,
          cursor: 'pointer',
        }}
      >
        <MapPin size={12} strokeWidth={2.2} aria-hidden />
        {course}
      </button>
    ) : null;

  const whoAvatar = (size: number) => (
    <SquircleAvatar
      src={row.avatar_url ?? undefined}
      alt={row.display_name}
      userId={row.actor_type === 'personal' ? row.actor_id : null}
      size={size}
      hairlineRing
    />
  );

  return (
    <div
      ref={rootRef}
      data-watch-lead={shape}
      style={{ margin: '22px 16px 0', borderRadius: 20, overflow: 'hidden', position: 'relative', background: '#17171B', fontFamily: SANS }}
    >
      {/* THE MEDIA opens the post full screen, as a Watch row tap does. */}
      <div
        ref={hostRef}
        role="button"
        tabIndex={0}
        aria-label={caption ?? row.display_name}
        onClick={openPost}
        onKeyDown={(e) => {
          if (e.target !== e.currentTarget) return;
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openPost();
          }
        }}
        style={{ position: 'relative', ...(upright ? { height: 440 } : { aspectRatio: '16 / 9' }), cursor: 'pointer', background: A.PANEL }}
      >
        {poster ? (
          <img src={poster} alt="" loading="lazy" decoding="async" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : null}
        {mount ? (
          <video
            ref={videoRef}
            poster={poster ?? undefined}
            muted={muted}
            playsInline
            preload="none"
            disableRemotePlayback
            tabIndex={-1}
            onError={(event) => {
              if (event.currentTarget.getAttribute('src')) setFailed(true);
            }}
            style={{
              position: 'absolute',
              inset: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: playing ? 1 : 0,
              transition: 'opacity 140ms linear',
              pointerEvents: 'none',
            }}
          />
        ) : null}
        {upright ? (
          <span
            aria-hidden
            style={{
              position: 'absolute',
              inset: 0,
              zIndex: 1,
              background: 'linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,0.8))',
              pointerEvents: 'none',
            }}
          />
        ) : null}
        {kickerEl}
        {durationEl}
        {muteEl}
        {upright ? (
          <div style={{ position: 'absolute', left: 14, right: 60, bottom: 16, zIndex: 2 }}>
            <button
              type="button"
              data-watch-lead="who"
              onClick={(e) => {
                e.stopPropagation();
                openCreator();
              }}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 9,
                padding: 0,
                border: 0,
                background: 'transparent',
                cursor: 'pointer',
                fontFamily: SANS,
                color: A.INK,
              }}
            >
              {whoAvatar(30)}
              <span style={{ fontSize: 14, fontWeight: 600, textShadow: TEXT_SHADOW, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                {row.display_name}
                <ProOrVerifiedMark userId={row.actor_type === 'personal' ? row.actor_id : undefined} verified={row.is_verified} name={row.display_name} />
              </span>
            </button>
            {caption ? (
              <p
                data-watch-lead="caption"
                style={{
                  margin: '10px 0 0',
                  fontSize: 17,
                  fontWeight: 700,
                  letterSpacing: '-0.01em',
                  lineHeight: 1.3,
                  color: A.INK,
                  textShadow: '0 1px 6px rgba(0,0,0,0.6)',
                  display: '-webkit-box',
                  WebkitLineClamp: 3,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                }}
              >
                {caption}
              </p>
            ) : null}
            <div data-watch-lead="meta" style={{ marginTop: 6, fontSize: 12, color: A.MUTE, textShadow: TEXT_SHADOW }}>
              {likes}
              {age ? ` · ${age}` : ''}
            </div>
            {courseChip(true)}
          </div>
        ) : null}
      </div>

      {upright ? null : (
        <div style={{ display: 'flex', gap: 10, padding: '12px 14px 14px' }}>
          <button
            type="button"
            data-watch-lead="who"
            aria-label={row.display_name}
            onClick={openCreator}
            style={{ flex: 'none', padding: 0, border: 0, background: 'transparent', cursor: 'pointer' }}
          >
            {whoAvatar(36)}
          </button>
          <div style={{ minWidth: 0, flex: 1 }}>
            {caption ? (
              <p
                data-watch-lead="caption"
                style={{
                  margin: 0,
                  fontSize: 15,
                  fontWeight: 600,
                  lineHeight: 1.3,
                  color: A.INK,
                  display: '-webkit-box',
                  WebkitLineClamp: 2,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                }}
              >
                {caption}
              </p>
            ) : null}
            <div data-watch-lead="meta" style={{ marginTop: 3, fontSize: 12.5, color: A.MUTE, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              <InlineProMemberName userId={row.actor_type === 'personal' ? row.actor_id : undefined}>{row.display_name}</InlineProMemberName>
              {row.is_verified ? ' ✓' : ''}
              {` · ${likes}`}
              {age ? ` · ${age}` : ''}
            </div>
            {courseChip(false)}
          </div>
        </div>
      )}
    </div>
  );
}

export default WatchLead;

src/features/explore-magazine/watch/feat:
.watch-featured { margin-top:22px; color:var(--featured-ink); }
.featured-head { display:flex; align-items:flex-end; justify-content:space-between; padding:0 16px; }
.featured-kicker { font-size:11px; font-weight:800; letter-spacing:0.2em; color:var(--featured-amber); }
.featured-title { font-size:22px; font-weight:700; letter-spacing:-0.02em; margin:3px 0 0; }
.featured-counter { font-size:12px; font-weight:700; color:var(--featured-muted); font-variant-numeric:tabular-nums; padding-bottom:3px; flex:none; }
.featured-deck { position:relative; height:420px; margin:24px 16px 0; }
.featured-card { position:absolute; inset:0; border-radius:22px; overflow:hidden; transform-origin:50% 50%; transition:transform 350ms cubic-bezier(.2,.8,.2,1), filter 350ms cubic-bezier(.2,.8,.2,1); box-shadow:var(--featured-shadow); will-change:transform; touch-action:pan-y; background:var(--featured-end); }
.featured-card[data-top="true"] { cursor:grab; }
.featured-card[data-depth="1"] { transform:rotate(3deg) scale(0.97) translateY(6px); filter:brightness(0.62); opacity:1; z-index:9; }
.featured-card[data-depth="2"] { transform:rotate(-2.5deg) scale(0.95) translateY(10px); filter:brightness(0.42); opacity:1; z-index:8; }
.featured-card[data-top="true"] { z-index:10; }
.featured-media, .featured-shade { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; pointer-events:none; }
.featured-video { opacity:0; transition:opacity 140ms linear; }
.featured-video[data-playing="true"] { opacity:1; }
.featured-shade { background:var(--featured-shade); }
.featured-badge, .featured-duration { height:30px; border-radius:10px; display:flex; align-items:center; pointer-events:none; }
.featured-badge { position:absolute; top:14px; }
.featured-badge { left:14px; padding:0 12px; background:var(--featured-glass); backdrop-filter:blur(16px); border:1px solid var(--featured-edge); font-size:10.5px; font-weight:800; letter-spacing:0.16em; }
.featured-topright { position:absolute; top:14px; right:14px; display:flex; align-items:center; gap:8px; z-index:3; }
.featured-duration { position:static; padding:0 10px; background:var(--featured-duration); font-size:13px; font-weight:700; font-variant-numeric:tabular-nums; }
.featured-playing { position:absolute; left:14px; top:52px; height:12px; display:flex; gap:2px; align-items:flex-end; pointer-events:none; }
.featured-playing i { width:3px; height:4px; background:var(--featured-white); border-radius:1px; animation:featured-eq 0.9s infinite ease-in-out; }
.featured-playing i:nth-child(2) { animation-delay:0.2s; }.featured-playing i:nth-child(3) { animation-delay:0.4s; }
@keyframes featured-eq { 0%,100% { height:4px; } 50% { height:12px; } }
.featured-foot { position:absolute; left:16px; right:16px; bottom:16px; pointer-events:none; }
.featured-who { display:flex; align-items:center; gap:9px; font-size:14px; font-weight:600; text-shadow:var(--featured-text-shadow); }
.featured-avatar { width:32px; height:34px; border-radius:34%; flex:none; border:1px solid var(--featured-dot); overflow:hidden; }
.featured-avatar img { width:100%; height:100%; object-fit:cover; }
.featured-who span:last-child { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.featured-caption { font-size:17px; font-weight:700; line-height:1.28; margin:10px 0 0; text-shadow:var(--featured-caption-shadow); display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; overflow-wrap:anywhere; }
.featured-meta { font-size:12px; color:var(--featured-meta); margin-top:6px; }
.watch-featured .featured-mute { position:relative; width:30px; height:30px; flex:none; padding:0; border-radius:10px; background:var(--featured-glass); border:1px solid var(--featured-edge); color:var(--featured-ink); backdrop-filter:blur(16px); opacity:1; }
.watch-featured .featured-mute::before { content:""; position:absolute; inset:-7px; }
.watch-featured .featured-mute svg { width:16px; height:16px; }
.featured-bar { display:flex; align-items:center; gap:8px; margin:34px 16px 0; min-height:40px; }
.watch-featured .featured-action { height:40px; padding:0 13px; border-radius:13px; border:1px solid var(--featured-edge); background:transparent; color:var(--featured-ink); font-size:14px; font-weight:700; font-variant-numeric:tabular-nums; gap:7px; flex:none; }
.watch-featured .featured-action svg { width:18px; height:18px; }
.featured-dots { margin-left:auto; display:flex; gap:5px; align-items:center; }
.featured-dots i { width:6px; height:6px; border-radius:3px; background:var(--featured-dot); transition:width 250ms, background 250ms; }
.featured-dots i[data-current="true"] { width:18px; background:var(--featured-white); }
.featured-end { border:1px solid var(--featured-end-edge); background:var(--featured-end); padding:30px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; }
.featured-end h3 { font-size:20px; font-weight:700; margin:0; }
.featured-end p { font-size:13.5px; color:var(--featured-body); line-height:1.5; margin:8px 0 0; }
.featured-end-actions { display:flex; gap:10px; margin-top:20px; flex-wrap:wrap; justify-content:center; }
.watch-featured .featured-end-button { height:auto; padding:11px 16px; border-radius:13px; font-size:13.5px; font-weight:700; color:var(--featured-ink); border:1px solid var(--featured-outline); background:transparent; }
.watch-featured .featured-restart { background:var(--featured-white); color:var(--featured-on-white); border-color:var(--featured-white); }
@media (max-width:340px) { .featured-dots { display:none; } }
@media (prefers-reduced-motion:reduce) { .featured-card { transition:none; } .featured-playing i { animation:none; height:8px; } .featured-dots i { transition:none; } }

src/features/explore-magazine/watch/stan:
.standout-shelf { min-width: 0; max-width: 100%; color: var(--standout-ink); }
.standout-heading { display:flex; justify-content:space-between; align-items:flex-end; padding:28px 16px 12px; }
.standout-heading b { display:block; font-size:19px; font-weight:700; }
.standout-heading span { display:block; font-size:12.5px; color:var(--standout-dim); margin-top:2px; }
.standout-scopes { display:flex; gap:6px; padding:10px 16px 0; overflow-x:auto; flex-wrap:nowrap; scrollbar-width:none; will-change:transform; }
.standout-scopes .standout-chip { flex:none; height:30px; padding:0 12px; border-radius:10px; border:1px solid var(--standout-chip-edge); background:transparent; color:var(--standout-mute); font-size:12.5px; font-weight:600; white-space:nowrap; }
.standout-scopes .standout-chip[aria-pressed="true"] { background:var(--standout-selected); color:var(--standout-ink); border-color:var(--standout-selected-edge); }
.standout-rail { display:flex; gap:10px; padding:12px 16px 2px; overflow-x:auto; scroll-snap-type:x mandatory; scroll-padding-inline:16px; scrollbar-width:none; overscroll-behavior-x:contain; will-change:transform; }
.standout-scopes::-webkit-scrollbar, .standout-rail::-webkit-scrollbar { display:none; }
.standout-card { flex:none; width:232px; min-height:214px; box-sizing:border-box; padding:14px; border:1px solid var(--standout-hair); border-radius:18px; background:var(--standout-card); display:flex; flex-direction:column; scroll-snap-align:start; cursor:pointer; text-align:left; }
.standout-card:focus-visible { outline:2px solid var(--standout-amber); outline-offset:-2px; }
.standout-card .standout-who { display:flex; align-items:center; gap:9px; padding:0; border:0; height:auto; min-width:0; width:100%; background:transparent; text-align:left; justify-content:flex-start; white-space:normal; }
.standout-identity { min-width:0; flex:1; }
.standout-name { display:block; font-size:14px; font-weight:600; line-height:1.25; color:var(--standout-ink); overflow-wrap:anywhere; white-space:normal; }
.standout-course { display:block; font-size:11.5px; color:var(--standout-dim); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
/* EXPLORE TILES A: the sentence is never clamped and never ends in an
   ellipsis; the tile grows to fit the full course name. */
.standout-story { font-size:14px; font-weight:600; line-height:1.36; color:var(--standout-ink); margin-top:12px; display:block; overflow-wrap:anywhere; flex-shrink:0; }
.standout-circle { font-size:9px; font-weight:800; letter-spacing:0.12em; color:var(--standout-dim); }
.standout-bottom { margin-top:auto; }
/* The feat hole's mark carries the old raised-bar highlight as a gold ring
   around the cell (the figure and its grade mark stay HoleMarks' own). */
.standout-card .tour-hole-marks > i[data-raised="true"]::before { content:''; position:absolute; inset:-1px; border:1.3px solid var(--standout-eagle); border-radius:4px; }
.standout-foot { display:flex; align-items:flex-end; gap:16px; margin-top:10px; }
.standout-figure small { display:block; font-size:8.5px; font-weight:800; letter-spacing:0.14em; color:var(--standout-dim); }
.standout-figure b { font-size:20px; font-weight:800; color:var(--standout-ink); }
.standout-figure i { font-style:normal; font-size:11.5px; font-weight:700; margin-left:3px; color:var(--standout-mute); }
.standout-figure i[data-under="true"] { color:var(--standout-birdie); }
.standout-figure[data-kind="gross"] b { font-weight:700; color:var(--standout-mute); }
.standout-when { margin-left:auto; text-align:right; font-size:11px; color:var(--standout-dim); line-height:1.5; white-space:nowrap; }
.standout-comp { display:flex; gap:4px; align-items:center; justify-content:flex-end; font-size:9px; font-weight:800; letter-spacing:0.12em; }
.standout-kicker { display:flex; align-items:center; gap:6px; margin-bottom:9px; font-size:9.5px; font-weight:800; letter-spacing:0.14em; text-transform:uppercase; color:var(--standout-dim); }
.standout-kicker i { width:8px; height:8px; border-radius:50%; background:var(--standout-eagle); }
.standout-kicker[data-clean="true"] i { background:var(--standout-ink); }
.standout-rarity { font-size:12.5px; color:var(--standout-mute); line-height:1.4; margin-top:8px; }
.standout-you { margin-top:3px; font-size:12px; font-weight:700; color:var(--standout-amber); }
.standout-loading-heading { padding:28px 16px 10px; }
.standout-loading-heading i { display:block; height:19px; width:150px; border-radius:6px; background:var(--standout-skeleton); }
.standout-loading-heading i + i { height:12px; width:130px; margin-top:6px; }
.standout-loading .standout-rail { padding-top:0; overflow:hidden; }
.standout-loading .standout-card { background:var(--standout-skeleton); border:0; }
